import { Book } from "@/lib/types";

export const _2chronicles: Book = {
  id: "2chronicles",
  name: "2. Chronik",
  shortName: "2Chr",
  testament: "old",
  introduction: `Die Herrschaft der Nachkommen Davids\nUrsprünglich bildeten beide Chronikbücher ein einziges Werk. Das erste Buch beginnt bei Adam und behandelt die Zeit bis zum Tod von König Saul nur in Stammbäumen mit eingefügten Kurzgeschichten. Erst mit David wird es ausführlicher. **Das zweite Buch der Chronik** berichtet nach der Reichsteilung (Kapitel 11) praktisch nur von der Herrschaft der Nachkommen Davids im Südreich Juda.\nDie Chronik ist nicht einfach eine Wiederholung der Königsbücher, sondern bietet eine Vogelperspektive der Geschichte Israels. Sie betont die Erhabenheit Gottes, der trotz menschlichem Versagen seine Pläne erfüllt.\nDie jüdische Überlieferung nennt Esra als Verfasser. Sein Bericht stützt sich auf viele frühere Quellen, zum Beispiel auf die \"Chronik des Königs David\", 1. Chronik 27,24; das \"Buch der Könige von Juda und Israel\", 2. Chronik 16,11; die \"Geschichte der Könige von Israel\", Kapitel 33,18; die \"Geschichte des Propheten Natan\" usw. Viele Elemente, die in den Samuel- und Königsbüchern berichtet werden, ließ der Verfasser weg, weil sie für seine eigentliche Absicht unwesentlich waren. Er wollte vor allem die bewahrende Gnade Gottes für sein Bundesvolk durch den messianischen König David zeigen.\n****Wie die Nachkommen Davids aus der Perspektive Gottes beurteilt werden müssen.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Als Salomo Ben-David seine Königsherrschaft gefestigt hatte – Jahwe, sein Gott, stand ihm nämlich bei und ließ ihn sehr mächtig werden –,", heading: "1-9: Die Herrschaft Salomos\nSalomos Tempelbau (1-7)\nSalomos Bitte um Weisheit" },
      { number: 2, text: "da ließ er die Vertreter von ganz Israel zusammenrufen: die Befehlshaber der Tausend- und Hundertschaften, die Richter, die Fürsten und die Sippenoberhäupter." },
      { number: 3, text: "Mit der ganzen Versammlung ging er zu der Anhöhe bei Gibeon*, denn dort stand das Offenbarungszelt* Gottes, das Jahwes Diener Mose in der Wüste hatte anfertigen lassen.", footnotes: ["Gibeon. Heute El-Jib, 10 km nordwestlich von Jerusalem.", "Offenbarungszelt. Wörtlich: Zelt der Begegnung."] },
      { number: 4, text: "Für die Lade Gottes jedoch hatte David ein Zelt in Jerusalem aufbauen lassen und sie von Kirjat-Jearim* herbeigeholt.", footnotes: ["Kirjat-Jearim, \"Wälderstadt\", lag 14 km westlich von Jerusalem. Zum Geschehen siehe 1. Chronik 13+15."] },
      { number: 5, text: "Doch der Bronzealtar, den Bezalel Ben-Uri, der Enkel von Hur, gemacht hatte, stand in Gibeon vor der Wohnstätte Jahwes. Dorthin begab sich Salomo mit allen Versammelten." },
      { number: 6, text: "Auf diesem Bronzealtar vor dem Offenbarungszelt opferte Salomo tausend Tiere als Brandopfer* für Jahwe.", footnotes: ["Brandopfer. Bei dieser Opferart wurde das Tier mit Ausnahme der Haut vollständig auf dem Altar verbrannt."] },
      { number: 7, text: "In der folgenden Nacht erschien ihm Gott und sagte: \"Sag mir, was ich dir geben soll!\"" },
      { number: 8, text: "Salomo sagte zu Gott: \"Du hast meinem Vater David sehr viel Güte erwiesen, und hast mich nun zum König gemacht." },
      { number: 9, text: "Möge sich dein Wort an meinen Vater David als wahr erweisen, Jahwe, mein Gott! Denn du selbst hast mich zum König über ein Volk gemacht, das so zahlreich ist wie der Staub auf der Erde." },
      { number: 10, text: "Gib mir daher Weisheit und Wissen, dass ich sehe, wie ich mit diesem Volk umgehen soll. Wie könnte ich sonst dein großes Volk regieren?\"" },
      { number: 11, text: "Da sagte Gott zu Salomo: \"Weil dir das am Herzen lag und du nicht um Reichtum, Besitz und Ehre, um den Tod deiner Feinde oder langes Leben für dich gebeten hast, sondern um Weisheit und Wissen, damit du mein Volk regieren kannst, über das ich dich zum König eingesetzt habe," },
      { number: 12, text: "so gebe ich dir Weisheit und Wissen. Und dazu gebe ich dir Reichtum, Besitz und Ehre, wie sie noch kein König vor dir besessen hat und auch keiner nach dir haben wird.\"" },
      { number: 13, text: "Dann kam Salomo vom Offenbarungszelt, das auf der Anhöhe bei Gibeon stand, nach Jerusalem. Und von dort aus regierte er über Israel." },
      { number: 14, text: "Salomo schaffte Streitwagen und Pferde an und stationierte sie in den Wagenstädten und in Jerusalem. Er besaß schließlich 1400 Streitwagen und 12.000 Pferde*.", heading: "Salomos Reichtum", footnotes: ["Pferde. Das hebräische Wort in diesem Vers kann auch mit Reiter übersetzt werden."] },
      { number: 15, text: "Der König brachte es soweit, dass man in Jerusalem Silber und Gold wie Steine zählte und Zedern wie die Maulbeerfeigenbäume, die in der Niederung wachsen." },
      { number: 16, text: "Die Pferde ließ Salomo aus Ägypten einführen. Seine Händler kauften sie aber auch in Koë* zum Marktpreis auf.", footnotes: ["Koë lag im Gebiet von Zilizien, im Südosten der heutigen Türkei."] },
      { number: 17, text: "Bei der Ausfuhr aus Ägypten kostete ein Streitwagen 600 Silberstücke, ein Pferd 150. Die Händler Salomos belieferten auch die Könige der Hetiter und Syrer mit Streitwagen und Pferden." },
      { number: 18, text: "Salomo beschloss, ein Haus zur Ehre Jahwes zu bauen sowie einen Regierungspalast für sich selbst.", heading: "Vorbereitung für den Tempelbau" },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Dazu ließ er 70.000 Lastträger und 80.000 Steinhauer in den Bergen antreten. 3600 Mann setzte er als Aufseher über sie ein." },
      { number: 2, text: "Er schickte eine Gesandtschaft zu König Hiram von Tyrus und ließ ihm sagen: \"Du hast schon meinem Vater David geholfen und ihm Zedern geliefert, als er sich einen Palast bauen wollte." },
      { number: 3, text: "Ich möchte jetzt ein Haus für den Namen meines Gottes Jahwe bauen, ein Haus, das ihm geweiht ist. Dort soll ihm Weihrauch als Opfer aufsteigen, und die geweihten Brote werden aufgeschichtet sein. Jeden Morgen und jeden Abend, an den Sabbaten, am Neumondfest und den anderen Festen Jahwes sollen dort Brandopfer dargebracht werden, wie es Israel für immer auferlegt wurde." },
      { number: 4, text: "Das Haus, das ich bauen will, wird groß sein, denn groß ist unser Gott über alle Götter hinaus." },
      { number: 5, text: "Selbst der Himmel und das ganze Universum können ihn nicht fassen. Wer ist überhaupt berechtigt, ihm ein Haus zu bauen? Und wer bin ich, dass ich das könnte, es sei denn, es gäbe ein Heiligtum, in dem Weihrauch als Opfer zu ihm aufsteigt." },
      { number: 6, text: "Schick mir nun einen fähigen Mann, der alle Arbeiten in Gold, Silber, Bronze und Eisen ausführen kann! Ebenso muss er Rotpurpur, Karmesin und Blaupurpur verarbeiten können und sich aufs Gravieren verstehen. Er soll mit den Künstlern aus Juda und Jerusalem zusammenarbeiten, die schon mein Vater David angestellt hat." },
      { number: 7, text: "Schick mir dazu vom Libanon Zedern-, Zypressen- und Almuggimholz*! Ich weiß ja, wie gut deine Leute dort Holz schlagen können. Meine Leute sollen deinen dabei helfen.", footnotes: ["Almuggim bezeichnet eine nicht näher bestimmbare wertvolle Holzart."] },
      { number: 8, text: "Es muss eine Menge Bauholz bereitgestellt werden, denn das Haus, das ich bauen will, wird groß und wunderbar werden." },
      { number: 9, text: "Ich will deinen Leuten dafür je 3 300 Tonnen* Weizen und Gerste und je 440.000 Liter* Olivenöl und Wein liefern.\"", footnotes: ["3.300 Tonnen. Hebräisch: 20.000 Kor. 1 Kor = 10 Efa = 220 Liter. Das entspricht etwa 165 Kilogramm Getreide.", "440.000 Liter. Hebräisch: 20 000 Bat. 1 Bat = 22 Liter. Die Menge würde heute 18 Tanklaster füllen"] },
      { number: 10, text: "König Hiram von Tyrus antwortete Salomo mit folgendem Schreiben: \"Weil Jahwe sein Volk liebt, hat er dich zum König gemacht!\"" },
      { number: 11, text: "Weiter schrieb er: \"Gepriesen sei Jahwe, der Gott Israels, der Himmel und Erde erschuf, dass er König David einen weisen Sohn mit Einsicht und Verstand geschenkt hat, der ein Haus für Jahwe bauen will und eins für seine Regierungsgeschäfte." },
      { number: 12, text: "Ich kann dir einen erfahrenen Künstler schicken: Hiram-Abi." },
      { number: 13, text: "Seine Mutter kommt aus dem Stamm Dan, sein Vater ist Tyrer. Er versteht sich auf alle Arbeiten in Gold, Silber, Bronze, Eisen, Stein und Holz. Er kann Rotpurpur, Blaupurpur*, Byssus und Karmesin* verarbeiten, alle Gravierungen ausführen und alles entwerfen, was ihm aufgetragen wird. Er ist bereit, mit deinen Künstlern und denen deines verehrten Vaters David zusammenzuarbeiten.", footnotes: ["Blaupurpur. Tyrus war bekannt für die Herstellung und den Handel mit dem wertvollsten aller Farbstoffe, dem Purpur, der aus den dort gezüchteten Murex-Schnecken gewonnen wurde. Die Farbe Blau bis Violett entsteht durch Enzymreaktionen und die Mischung von rotem und blauem Purpur.", "Karmesin ist ein (scharlach)roter Farbstoff, der aus getrockneten weiblichen Kochenilleläusen gewonnen wird."] },
      { number: 14, text: "Mein Herr möge nun die angekündigte Sendung von Weizen, Gerste, Öl und Wein an seine Diener liefern." },
      { number: 15, text: "Wir unsererseits werden Holz im Libanon schlagen, so viel du brauchst, und es dir in Flößen über das Meer nach Jafo* bringen. Von dort kannst du es nach Jerusalem schaffen lassen.\"", footnotes: ["Jafo. Hafenstadt am Mittelmeer; heute: Jaffa."] },
      { number: 16, text: "Salomo ließ nun alle Fremden in Israel zählen, nachdem schon sein Vater David solch eine Zählung vorgenommen hatte. Es waren 153.600 Männer." },
      { number: 17, text: "70.000 von ihnen machte er zu Lastträgern, 80.000 zu Steinhauern im Gebirge und 3600 zu Aufsehern, um die Leute zur Arbeit anzuhalten." },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Dann begann Salomo, das Haus Jahwes in Jerusalem auf dem Berg Morija zu bauen. Die Stelle hatte schon sein Vater David bestimmt, denn dort, auf dem Dreschplatz des Jebusiters Ornan, war ihm Jahwe erschienen.", heading: "Der Tempelbau" },
      { number: 2, text: "Am 2. Mai* in seinem vierten Regierungsjahr begann der Bau.", footnotes: ["Mai. Wörtlich: des 2. Monats. Es war das Jahr 966 v.Chr. Zum Datum siehe unter Schaltmonat im Vorwort des Übersetzers."] },
      { number: 3, text: "Die Grundmaße, die Salomo für den Bau des Gotteshauses festgelegt hatte, betrugen dreißig mal zehn Meter*.", footnotes: ["dreißig ... Meter. Wörtlich: Die Länge 60 Ellen und die Breite 20 Ellen nach dem früheren Ellenmaß. Weil die für eine Elle angegebenen Maße zwischen 44,42 und 52,45 cm schwanken, gehen wir für die meisten Umrechnungen von 50 cm aus. Dadurch werden auch die Proportionen deutlicher."] },
      { number: 4, text: "Die Halle vor dem Haus war zehn Meter breit und zehn Meter* hoch. Ihre Innenwände ließ er mit reinem Gold überziehen.", footnotes: ["zehn ... Meter. So mit einigen griechischen und syrischen Handschriften. Hebräisch: 120 Ellen (60 Meter)."] },
      { number: 5, text: "Das Tempelhaus selbst ließ er innen mit Zypressenholz verkleiden und mit Gold überziehen. Darauf waren Palmen und Zierketten angebracht." },
      { number: 6, text: "Salomo ließ das ganze Haus mit Edelsteinen schmücken. Das verwendete Gold stammte aus Parwajim*.", footnotes: ["Parwajim ist eventuell ein Ort in Südarabien. Der Begriff kann aber auch eine besondere Goldqualität meinen (Parwajimgold)."] },
      { number: 7, text: "Damit wurde das Haus innen verkleidet: die Balken, Schwellen, Wände und Türflügel. In die Wände ließ er außerdem Bilder von Cherubim* einschnitzen.", footnotes: ["Cherub, Mehrzahl: Cherubim. Majestätisches (Engel-)Wesen, das Gottes Herrlichkeit repräsentiert."] },
      { number: 8, text: "Den Raum des Höchstheiligen machte Salomo zehn Meter lang und zehn Meter breit. Er überzog ihn mit reinem Gold im Gewicht von 21 Tonnen*.", heading: "Das Höchstheilige", footnotes: ["21 Tonnen. Wörtlich: 600 Talente. 1 Talent = 34,5 Kilogramm."] },
      { number: 9, text: "Allein für den Goldüberzug der Nagelköpfe wurde ein halbes Kilogramm* gebraucht. Auch die oberen Räume wurden mit Gold verkleidet.", footnotes: ["halbes Kilogramm. Hebräisch: 50 Schekel. 1 Schekel = 11,5 Gramm."] },
      { number: 10, text: "Für das Höchstheilige ließ er dann in Bildhauerarbeit zwei Cherubim anfertigen und überzog sie mit Gold." },
      { number: 11, text: "Die Flügel der Cherubim hatten zusammen eine Spannweite von zehn Metern. Der eine zweieinhalb Meter lange Flügel des einen Cherub berührte die Wand und der andere den Flügel des zweiten." },
      { number: 12, text: "Beim zweiten Cherub war es ebenso. Einer der zweieinhalb Meter langen Flügel berührte die Wand, der andere berührte den Flügel des ersten." },
      { number: 13, text: "Das ergab eine Gesamtspannweite von zehn Metern. Die Cherubim standen auf ihren Füßen und hatten ihre Gesichter dem Heiligtum zugewandt." },
      { number: 14, text: "Auch den Vorhang ließ Salomo anfertigen. Er bestand aus blauem und rotem Purpur, blutroter Wolle und feiner Baumwolle. Cherubim waren darauf gestickt." },
      { number: 15, text: "Vor dem Haus ließ Salomo zwei Säulen anfertigen, die zusammen achtzehn Meter* hoch waren. Jede hatte ein Kapitell von zweieinhalb Metern Höhe.", heading: "Die Bronzesäulen", footnotes: ["achtzehn Meter. Wörtlich: 35 Ellen. Nach 1. Könige 7,15; 2. Könige 25,17 und Jeremia 52,21 war jede Säule neun Meter hoch."] },
      { number: 16, text: "Oben ließ er Zierketten anbringen, an denen 100 Nachbildungen von Granatäpfeln befestigt waren." },
      { number: 17, text: "Die Säulen ließ er links und rechts vor dem Tempel aufstellen. Die rechte nannte er Jachin, \"er richtet auf\", und die linke Boas, \"in ihm ist Stärke\"." },
    ] },
    { number: 4, verses: [
      { number: 1, text: "Salomo ließ einen Altar aus Bronze anfertigen, der zehn Meter lang, zehn Meter breit und fünf Meter hoch war.", heading: "Die Ausstattung des Tempels" },
      { number: 2, text: "Dann kam das so genannte Meer an die Reihe. Es wurde aus Bronze gegossen und hatte einen Durchmesser von fünf Metern. Seine Höhe betrug zweieinhalb Meter und eine Schnur von 15 Metern Länge umspannte es." },
      { number: 3, text: "Zwei Reihen von rinderähnlichen Formen verzierten das Meer ringsum unterhalb des Randes. Sie waren aus einem Guss mit dem Becken. Auf einen halben Meter kamen zehn solcher Rinder*.", footnotes: ["Diese Rinder waren so stark stilisiert, dass sie in 1. Könige 7,24 mit Buckeln (oder wilden Kürbissen) beschrieben werden konnten."] },
      { number: 4, text: "Das Becken selbst stand auf zwölf Rindern, deren Hinterteile nach innen gekehrt waren. Jeweils drei von ihnen schauten nach Norden, Westen, Süden und Osten." },
      { number: 5, text: "Der Rand des Beckens war wie bei einem Kelch oder einer Lilienblüte nach außen gewölbt und etwa eine Handbreit dick. Das Becken fasste 66.000 Liter*.", footnotes: ["66.000 Liter. Hebräisch: 3000 Bat. 1 Bat = 22 Liter."] },
      { number: 6, text: "Salomo ließ auch zehn Kessel anfertigen. Fünf stellte er rechts und fünf links vom Meer auf. Darin wusch man alles, was zum Brandopfer gehörte. Das Meer selbst war nur für die Waschungen der Priester bestimmt." },
      { number: 7, text: "Er ließ auch zehn goldene Leuchter genau nach Vorschrift anfertigen und in die Tempelhalle stellen, fünf an die rechte und fünf an die linke Seite." },
      { number: 8, text: "Weiterhin ließ er zehn Tische machen und in die Halle stellen, fünf an die rechte und fünf an die linke Seite. Außerdem ließ er hundert goldene Opferschalen anfertigen." },
      { number: 9, text: "Dann richtete er den Vorhof ein, der nur von den Priestern betreten werden durfte, sowie den großen Vorhof mit seinen Toren. Die Torflügel ließ er mit Bronze überziehen." },
      { number: 10, text: "Das Meer wurde an der Südostecke rechts vom Eingang des Tempels aufgestellt." },
      { number: 11, text: "Schließlich machte Hiram die Töpfe, die Schaufeln und die Opferschalen und vollendete so für König Salomo die Arbeit am Haus Gottes." },
      { number: 12, text: "Er hatte zwei Säulen mit ihren becherförmigen Kapitellen angefertigt, dazu die Zierketten, die die Kapitelle bedeckten," },
      { number: 13, text: "und die 400 Granatäpfel für die beiden Zierketten, die in zwei Reihen an jeder Kette befestigt waren, um die beiden Kapitelle zu bedecken." },
      { number: 14, text: "Er hatte die zehn Gestelle gemacht und die Kessel darauf gestellt;" },
      { number: 15, text: "außerdem das sogenannte Meer und die zwölf Rinder darunter," },
      { number: 16, text: "die Töpfe, Schaufeln, Fleischgabeln und alles, was noch dazu gehörte. All diese Teile fertigte Hiram-Abi dem König Salomo für das Haus Jahwes aus polierter Bronze an." },
      { number: 17, text: "In der Jordanebene hatte der König sie gießen lassen, in den Tonablagerungen zwischen Sukkot und Zaretan*.", footnotes: ["Sukkot und Zaretan liegen etwa 34 km nordöstlich von Jericho auf der Ostseite des Jordan und der Nordseite des Jabbok."] },
      { number: 18, text: "Und Salomo hatte all diese Stücke in großer Menge anfertigen lassen. Auf das Gewicht der verarbeiteten Bronze kam es dabei nicht an." },
      { number: 19, text: "Nun ließ Salomo alle Gegenstände anfertigen, die zum Haus Gottes gehörten: den goldenen Altar, die Tische, auf denen die geweihten Brote lagen," },
      { number: 20, text: "die Leuchter mit ihren Lampen aus reinem Gold, damit sie vorschriftsmäßig vor dem hinteren Raum angezündet würden," },
      { number: 21, text: "die blütenförmigen Aufsätze für die Lichtschalen und die Dochtscheren – alles aus reinstem Gold –," },
      { number: 22, text: "die Lichtmesser und die Opferschalen, die Schüsseln und die Feuerbecken aus reinem Gold. Auch der Eingang des Hauses, die Türflügel zum Höchstheiligen hin und die Türflügel zum Tempelraum waren aus Gold." },
    ] },
    { number: 5, verses: [
      { number: 1, text: "Schließlich waren alle Arbeiten für das Haus Jahwes vollendet. Da brachte Salomo die Gaben, die sein Vater David Gott geweiht hatte, in die Schatzkammern des Gotteshauses: das Silber, das Gold und alle Gegenstände." },
      { number: 2, text: "Dann ließ Salomo die Ältesten von Israel, die Oberhäupter der Stämme und die Fürsten der Sippen Israels nach Jerusalem kommen. Sie sollten die Bundeslade Jahwes aus der Davidsstadt* Zion in den Tempel hinaufbringen.", heading: "Die Überführung der Bundeslade", footnotes: ["Die Davidsstadt umfasste das Gebiet des alten Jebus, das von David erobert worden war. Es bildete den Kern Jerusalems."] },
      { number: 3, text: "Am Laubhüttenfest, das im Oktober* stattfindet, versammelten sich alle Männer Israels beim König.", footnotes: ["Oktober. Wörtlich: im 7. Monat. Nach 1. Könige 6,38 war der Tempel schon im 8. Monat des Vorjahres fertig gestellt worden. Salomo hatte aber noch 11 Monate bis zum nächsten Laubhüttenfest mit der Einweihung gewartet, also bis zum Herbst 958 v.Chr."] },
      { number: 4, text: "In Gegenwart der Ältesten Israels nahmen die Leviten die Lade" },
      { number: 5, text: "und trugen sie zum Tempel hinauf. Auch das Zelt der Gottesbegegnung und die heiligen Gegenstände, die im Zelt waren, wurden von den Priestern und Leviten hinaufgebracht." },
      { number: 6, text: "König Salomo und die ganze Gemeinschaft Israels, die sich bei ihm vor der Lade eingefunden hatte, opferten eine unzählbare Menge von Schafen und Rindern." },
      { number: 7, text: "Dann brachten die Priester die Bundeslade Jahwes an ihren Platz im hintersten Raum des Hauses, dem Höchstheiligen, unter die Flügel der Cherubim." },
      { number: 8, text: "Die Cherubim hielten ihre Flügel nämlich über dem Platz der Lade ausgebreitet und überspannten damit die Lade und ihre Tragestangen." },
      { number: 9, text: "Die Stangen waren so lang, dass man ihre Enden vom Heiligtum aus nur sehen konnte, wenn man direkt vor dem hinteren Raum stand. Sonst waren sie vom Heiligtum aus nicht zu sehen. Die Lade befindet sich noch heute* dort.", footnotes: ["Heute meint den Zeitpunkt, als 2. Chronik verfasst wurde."] },
      { number: 10, text: "In der Lade waren nur die beiden Tafeln, die Mose am Horeb hineingelegt hatte, als Jahwe den Bund mit den Israeliten bei deren Auszug aus Ägypten schloss*.", footnotes: ["Bund ... schloss. Vergleiche 2. Mose 24; 32-34."] },
      { number: 11, text: "Dann zogen die Priester aus dem Heiligtum aus. Alle anwesenden Priester hatten sich geheiligt, unabhängig davon, ob sie Dienst hatten oder nicht." },
      { number: 12, text: "Und alle anwesenden Tempelsänger, die Leviten Asaf, Heman und Jedutun mit allen ihren Söhnen und Brüdern, waren in feines weißes Leinen gekleidet und standen mit ihren Zimbeln, Harfen und Zithern an der Ostseite des Altars. Neben ihnen standen etwa 120 Priester mit Trompeten." },
      { number: 13, text: "Als die Trompeter und die Sänger einstimmig begannen, Jahwe zu loben und zu preisen, als der gemeinsame Klang von Trompeten, Zimbeln und den anderen Instrumenten beim Lob Jahwes erklang – \"Denn er ist gütig und seine Güte hört niemals auf!\" –, da wurde das ganze Haus, das Haus Jahwes, mit einer Wolke erfüllt." },
      { number: 14, text: "Und die Priester konnten wegen der Wolke nicht hingehen, um ihren Dienst zu tun, weil die Herrlichkeit Jahwes das Haus Gottes erfüllte." },
    ] },
    { number: 6, verses: [
      { number: 1, text: "Damals sagte Salomo: \"Jahwe hat beschlossen, im Wolkendunkel zu wohnen.", heading: "Salomos Ansprache" },
      { number: 2, text: "Doch ich, ich habe dir ein Herrscherhaus gebaut, eine Wohnstätte für ewige Zeiten.\"" },
      { number: 3, text: "Die ganze Versammlung Israels stand dabei. Dann wandte sich der König der Versammlung zu und segnete sie." },
      { number: 4, text: "Er sagte: \"Gepriesen sei Jahwe, der Gott Israels, der mit seiner Hand wahr machte, was er meinem Vater David mit dem Mund versprach:" },
      { number: 5, text: "'Seit der Zeit, als ich mein Volk aus Ägypten führte, habe ich in keinem der Stämme Israels eine Stadt erwählt, um dort einen Wohnsitz für meinen Namen errichten zu lassen. Ich habe auch niemand als Herrscher über mein Volk bestimmt." },
      { number: 6, text: "Aber jetzt habe ich Jerusalem als Wohnsitz für meinen Namen erwählt und David zum Herrscher über mein Volk Israel.'" },
      { number: 7, text: "Nun war es meinem Vater David ein Anliegen, dem Namen Jahwes, des Gottes Israels, ein Haus zu bauen." },
      { number: 8, text: "Doch Jahwe sagte zu meinem Vater David: 'Wenn du dir vorgenommen hast, meinem Namen ein Haus zu bauen, hast du einen guten Entschluss gefasst." },
      { number: 9, text: "Aber nicht du, sondern dein leiblicher Sohn soll dieses Haus für meinen Namen bauen.'" },
      { number: 10, text: "Und Jahwe hat dieses Versprechen gehalten. Ich bin an die Stelle meines Vaters David getreten und habe den Thron Israels bestiegen, wie Jahwe es zugesagt hat. Und ich habe nun das Haus für den Namen Jahwes gebaut" },
      { number: 11, text: "und die Lade hineingestellt, in der die Tafeln des Bundes liegen, den Jahwe mit den Israeliten schloss.\"" },
      { number: 12, text: "Dann trat Salomo vor den Augen der Versammlung Israels zum Altar Jahwes und breitete seine Hände aus.", heading: "Salomos Weihegebet" },
      { number: 13, text: "Salomo hatte ein Podest aus Bronze anfertigen lassen und mitten in den Vorhof gestellt. Es war zweieinhalb Meter lang, zweieinhalb Meter breit und anderthalb Meter hoch. Er stieg auf dieses Podest, kniete sich vor der ganzen Versammlung Israels hin, breitete seine Hände zum Himmel aus" },
      { number: 14, text: "und sagte: \"Jahwe, Gott Israels! Kein Gott ist dir vergleichbar, weder im Himmel noch auf der Erde. Du stehst zu deinem Bund und erhältst deinen Dienern deine Güte, denen, die vor dir leben und dir mit ganzem Herzen dienen." },
      { number: 15, text: "Du hast auch deinem Diener, meinem Vater David, gegenüber deine Versprechen gehalten. Was du mit dem Mund versprachst, hast du mit der Hand wahr gemacht, wie es dieser Tag zeigt." },
      { number: 16, text: "Jahwe, Gott Israels, nun erfülle auch die andere Zusage, die du meinem Vater David gegeben hast, als du sagtest: 'Es soll dir nie an einem Mann fehlen, der vor mir auf dem Thron Israels sitzt, wenn nur deine Söhne darauf achten, so nach meinen Weisungen zu leben, wie du das getan hast.'" },
      { number: 17, text: "Jahwe, Gott Israels, lass doch in Erfüllung gehen, was du deinem Diener David zugesagt hast." },
      { number: 18, text: "Aber will Gott wirklich bei den Menschen auf der Erde wohnen? Selbst der Himmel und das ganze Universum können dich nicht fassen, geschweige denn dieses Haus, das ich gebaut habe!" },
      { number: 19, text: "Trotzdem bitte ich dich, Jahwe, mein Gott, achte doch auf das Gebet deines Dieners und höre auf sein Flehen und seine Bitte, die er vor dich bringt." },
      { number: 20, text: "Halte deine Augen Tag und Nacht über diesem Haus offen, von dem du gesagt hast, dass dein Name dort wohnen soll, und höre auf das Gebet, das dein Diener zu dieser Stätte hin richtet!" },
      { number: 21, text: "Höre doch auf das Flehen, das dein Diener und dein Volk zu dieser Stätte hin richten werden! Höre du es selbst in deiner himmlischen Wohnung, dort, wo du thronst! Ja, erhöre uns und vergib!" },
      { number: 22, text: "Wenn sich jemand an seinem Nächsten versündigt und dieser einen Eid von ihm verlangt und er kommt vor deinen Altar in dieses Haus und spricht die Selbstverfluchung* aus,", footnotes: ["Selbstverfluchung. Siehe 2. Mose 22, 10-12; 4. Mose 5,11-31."] },
      { number: 23, text: "dann höre es vom Himmel her und greife ein! Verschaff deinen Dienern Recht! Bestrafe den Schuldigen und lass sein böses Tun auf ihn selbst zurückfallen, den Schuldlosen aber sprich frei und gib ihm, was seiner Gerechtigkeit entspricht." },
      { number: 24, text: "Und wenn dein Volk Israel von Feinden besiegt wird, weil es gegen dich gesündigt hat, und dann wieder umkehrt und deinen Namen preist und in diesem Haus zu dir betet und fleht," },
      { number: 25, text: "dann höre du es im Himmel und vergib deinem Volk Israel seine Schuld und bring es wieder in das Land zurück, das du ihnen und ihren Vorfahren gegeben hast." },
      { number: 26, text: "Wenn sich der Himmel verschließt, dass es nicht regnet, weil sie gegen dich gesündigt haben, und sie dann zu dieser Stätte hin beten und deinen Namen preisen und von ihrer Sünde umkehren, weil du sie gedemütigt hast," },
      { number: 27, text: "dann höre du es im Himmel und vergib deinen Dienern und deinem Volk Israel die Sünde – denn du führst sie den rechten Weg – und lass es wieder regnen auf dein Land, das du deinem Volk als Grundbesitz gegeben hast." },
      { number: 28, text: "Wenn eine Hungersnot im Land ausbricht, wenn die Pest wütet, wenn das Getreide durch Brand- oder Rostpilze, Heuschrecken oder andere Schädlinge vernichtet wird, wenn der Feind ins Land einfällt, wenn irgendeine Krankheit oder Plage sie trifft," },
      { number: 29, text: "dann höre du jedes Gebet und Flehen. Sei es ein Einzelner oder dein ganzes Volk, je nachdem, was einer als seine Plage oder seinen Schmerz erkennt, wenn er seine Hände nach diesem Haus hin ausbreitet," },
      { number: 30, text: "dann höre du es im Himmel, dem Ort wo du thronst! Und vergib; und gib jedem, was er verdient! Denn du kennst die verborgenen Gedanken der Menschen und siehst ihnen ins Herz." },
      { number: 31, text: "Dann werden sie dich fürchten und auf deinen Wegen gehen, solange sie in dem Land leben, das du unseren Vätern gegeben hast." },
      { number: 32, text: "Auch wenn ein Ausländer, der nicht zu deinem Volk Israel zählt, aus einem fernen Land kommt, weil er von deinem großen Namen hörte und von dem, was du mit deiner starken Hand und deinem ausgestreckten Arm getan hast – wenn er also kommt und zu diesem Haus hin betet," },
      { number: 33, text: "dann höre du es im Himmel, dem Ort wo du thronst, und erfülle seine Bitte! So werden alle Völker der Erde deinen Namen erkennen und dich fürchten, wie dein Volk Israel es tut. Und sie werden wissen, dass dein Name über diesem Haus, das ich gebaut habe, ausgerufen ist." },
      { number: 34, text: "Wenn dein Volk gegen seine Feinde in den Krieg zieht, egal wohin du sie schickst, und sie dann zu dir beten in Richtung dieser Stadt, die du erwählt hast, und dieses Hauses, das ich deinem Namen gebaut habe," },
      { number: 35, text: "dann höre ihr Gebet und Flehen im Himmel und verschaffe ihnen ihr Recht!" },
      { number: 36, text: "Wenn sie gegen dich sündigen – denn es gibt keinen Menschen, der nicht sündigt – und du zornig über sie wirst und sie ihren Feinden preisgibst, und diese sie in ein fernes oder nahes Land verschleppen," },
      { number: 37, text: "und sie fangen an, es sich dort zu Herzen zu nehmen, und kehren um und flehen im Land ihrer Gefangenschaft zu dir und sagen: 'Wir haben gesündigt, wir haben Unrecht getan, wir haben gottlos gehandelt!';" },
      { number: 38, text: "wenn sie in dem Land, in dem sie gefangen sind, anhaltend und mit ganzem Herzen und ihrer ganzen Seele zu dir umkehren und beten in Richtung dieses Landes, das du ihren Vätern gegeben hast, und dieser Stadt, die du erwählt hast, und dieses Hauses, das ich deinem Namen gebaut habe," },
      { number: 39, text: "dann höre ihr Gebet und Flehen im Himmel, dem Ort wo du thronst, und schaffe ihnen ihr Recht! Und vergib deinem Volk, was es gegen dich gesündigt hat." },
      { number: 40, text: "Nun denn, mein Gott, lass deine Augen offen sein und deine Ohren hören auf das Gebet an diesem Ort.\"" },
      { number: 41, text: "\"Und jetzt ziehe ein, Jahwe, unser Gott, / komm zu deinem Ruheplatz / und begleite deine Lade, / das Symbol deiner Macht! / Lass an deinen Priestern, Jahwe, Gott, / die Rettung sichtbar sein. / Mögen deine Frommen des Guten sich freuen!" },
      { number: 42, text: "Und weise deinen Gesalbten nicht ab, Jahwe, Gott! / Denk an die Beweise deiner Gnade, / die du David, deinem Diener, zugesagt hast!\"" },
    ] },
    { number: 7, verses: [
      { number: 1, text: "Als Salomo sein Gebet beendet hatte, fiel Feuer vom Himmel und verzehrte das Brand- und die Freudenopfer*, und die Herrlichkeit Jahwes erfüllte das Haus.", heading: "Salomos Festopfer", footnotes: ["Beim Freudenopfer wurde der größte Teil des Tieres während der anschließenden Opfermahlzeit gemeinsam mit Freunden verzehrt."] },
      { number: 2, text: "Die Priester konnten das Haus Jahwes nicht betreten, weil die Herrlichkeit Jahwes es ausfüllte." },
      { number: 3, text: "Alle Israeliten sahen, wie das Feuer herabfiel und die Herrlichkeit Jahwes sich über dem Haus zeigte. Da knieten sie sich hin und beugten sich mit dem Gesicht auf das Pflaster nieder und beteten an. Sie priesen Jahwe, weil er gütig ist und seine Gnade niemals aufhört." },
      { number: 4, text: "Der König und das ganze Volk feierten vor Jahwe ein großes Opfermahl." },
      { number: 5, text: "Salomo ließ zu dem Anlass 22.000 Rinder und 120.000 Schafe schlachten. So weihten sie das Haus Gottes ein." },
      { number: 6, text: "Die Priester versahen ihren Dienst, und die Leviten hatten sich mit den Musikinstrumenten aufgestellt, die König David für das Lob Jahwes hatte anfertigen lassen – \"Denn seine Güte hört niemals auf!\" Die Leviten begleiteten damit die Danklieder Davids. Die Priester standen ihnen gegenüber und bliesen ihre Trompeten, und ganz Israel stand dabei." },
      { number: 7, text: "Zu diesem besonderen Anlass weihte Salomo den mittleren Teil des Vorhofs vor dem Haus Jahwes zum Opferaltar. Denn dort ließ er die Brandopfer und die Fettstücke der Freudenopfer verbrennen, weil der Bronzealtar, den er hatte anfertigen lassen, für die Menge der Brand- und Speisopfer und Fettstücke zu klein war." },
      { number: 8, text: "Salomo feierte damals auch das Laubhüttenfest mit ganz Israel sieben Tage lang. Es war eine sehr große Versammlung aus dem ganzen Land zusammengekommen, von Lebo-Hamat* bis zum Bach Ägyptens*.", footnotes: ["Lebo-Hamat. Heute Labwe, etwa 70 km nördlich vom Hermon.", "Nach Josua 15,4 war der Bach Ägyptens die Grenze zwischen Israel und Ägypten. Heute: Wadi El-Arisch."] },
      { number: 9, text: "Am achten Tag fand die Abschlussfeier statt. Sie hatten zuerst sieben Tage lang die Einweihung des Altars gefeiert und dann noch sieben Tage lang das Laubhüttenfest." },
      { number: 10, text: "Am 23. Oktober* verabschiedete Salomo das Volk. Alle freuten sich über das Gute, das Jahwe David, Salomo und seinem Volk Israel getan hatte, und zogen voller Zuversicht nach Hause.", footnotes: ["Oktober. Wörtlich: des 7. Monats."] },
      { number: 11, text: "Als nun Salomo das Haus Jahwes und das Haus für den König vollendet hatte und alles gut gelungen war, was er sich vorgenommen hatte,", heading: "Gottes Antwort" },
      { number: 12, text: "erschien ihm Jahwe in der Nacht und sagte zu ihm: \"Ich habe dein Gebet erhört und dieses Haus als Opferstätte angenommen." },
      { number: 13, text: "Wenn ich den Himmel verschließe und es nicht mehr regnet, wenn ich den Heuschrecken befehle, das Land kahl zu fressen, und wenn ich die Pest unter mein Volk sende," },
      { number: 14, text: "und wenn dann mein Volk, über dem mein Name ausgerufen ist, sich demütigt und zu mir betet, wenn es meine Gegenwart sucht und von seinen bösen Wegen umkehrt, dann werde ich es vom Himmel her hören, ihre Sünden vergeben und ihr Land heilen." },
      { number: 15, text: "Jetzt lasse ich meine Augen offen sein über diesem Ort, und meine Ohren werden auf die Gebete hier hören." },
      { number: 16, text: "Jetzt habe ich dieses Haus erwählt und zu meiner heiligen Stätte gemacht. Hier soll mein Name für immer wohnen, und meine Augen und mein Herz werden jeden Tag dort sein." },
      { number: 17, text: "Und du, wenn du so vor mir lebst wie dein Vater David und meine Gebote, Vorschriften und Rechte beachtest," },
      { number: 18, text: "dann werde ich deine Herrschaft bestehen lassen, wie ich es deinem Vater David zugesagt habe, als ich den Bund mit ihm schloss: 'Es soll dir nie an einem Mann fehlen, der über Israel herrscht.'" },
      { number: 19, text: "Wenn ihr euch aber von mir abwendet, wenn ihr meine Vorschriften und Gebote nicht mehr beachtet und stattdessen anderen Göttern nachlauft und euch vor ihnen niederwerft," },
      { number: 20, text: "dann werde ich Israel aus meinem Land, das ich ihnen gegeben habe, herausreißen. Dann werde ich dieses Haus, das ich meinem Namen geheiligt habe, keines Blickes mehr würdigen und es zum Gespött und zum Hohn für alle Völker machen," },
      { number: 21, text: "ja, dieses Haus, das so erhaben war. Jeder, der vorübergeht, wird sich dann entsetzt fragen: 'Warum hat Jahwe das diesem Land und diesem Haus angetan?'" },
      { number: 22, text: "Dann wird man ihnen antworten: 'Weil sie Jahwe, den Gott ihrer Väter, der sie aus Ägypten herausführte, verlassen und sich anderen Göttern zugewandt haben, weil sie diese verehrt und sich vor ihnen niedergeworfen haben, hat er all dieses Unheil über sie gebracht.'\"" },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Nachdem Salomo zwanzig Jahre lang am Haus Jahwes und an seinem Regierungspalast gebaut hatte,", heading: "Salomos Ruhm und Macht (8-9)\nSalomos Unternehmungen" },
      { number: 2, text: "baute er auch die Städte aus, die Hiram ihm gegeben* hatte, und siedelte Israeliten dort an.", footnotes: ["Hiram ihm gegeben. Siehe Fußnote zu 1. Könige 9,14."] },
      { number: 3, text: "Hierauf zog Salomo nach Hamat-Zoba* und eroberte die Stadt.", footnotes: ["Hamat-Zoba. Unbekannte Stadt im Libanon."] },
      { number: 4, text: "Dann baute er Tadmor* in der Wüste aus und legte Vorratsstädte um Hamat* herum an.", footnotes: ["Tadmor ist ein Karawanenplatz, eine große Oase in der nordsyrischen Wüste. Heute: Palmyra, 208 km nordöstlich von Damaskus.", "Hamat galt als nördlichster Punkt des \"idealen\" Israel. Heute: Lebweh im libanesischen Beqa-Tal, 72 km nördlich von Damaskus."] },
      { number: 5, text: "Das obere und das untere Bet-Horon* baute er zu Festungen aus, die mit Mauern, Toren und Riegeln gesichert waren.", footnotes: ["Bet-Horon. Die Zwillingsstädte waren nur 3 km voneinander entfernt und beherrschten die wichtige Zugangsstraße von der Küstenebene ins Hügelland. Sie lagen 19 km nordwestlich von Jerusalem."] },
      { number: 6, text: "Ebenso befestigte er Baalat* und alle anderen Vorratsstädte sowie alle Städte, in denen seine Streitwagentruppen stationiert waren. Auch in Jerusalem, im Libanon und in seinem ganzen Reich baute er alles, was er wollte.", footnotes: ["Baalat ist der ältere Name für Kirjat-Jearim an der Grenze von Juda und Benjamin. Heute: Deir el-Azar, 14 km westlich von Jerusalem."] },
      { number: 7, text: "Alle Nachkommen der Hetiter, Amoriter, Perisiter, Hiwiter und Jebusiter, die von Israel nicht beseitigt worden waren" },
      { number: 8, text: "und noch in Israel lebten, verpflichtete Salomo zur Zwangsarbeit. So ist es bis heute geblieben." },
      { number: 9, text: "Israeliten machte Salomo nicht zu Sklaven* für seine Arbeiten. Sie waren seine Soldaten, die Obersten seiner Wagenkämpfer und seiner Reiter.", footnotes: ["Sklaven. Israeliten wurden nur zeitweise zu Zwangsarbeiten herangezogen (1. Könige 5,27-28), die Vorgenannten aber dauerhaft."] },
      { number: 10, text: "König Salomo hatte 250 Oberaufseher, die das Volk bei der Arbeit beaufsichtigten." },
      { number: 11, text: "Salomo brachte die Tochter des Pharao von der Davidsstadt in das Haus hinauf, das er eigens für sie hatte bauen lassen, denn er sagte: \"Meine Frau soll nicht im Haus des Königs von Israel wohnen, im Haus Davids, denn es ist heilig, weil dort einmal die Bundeslade Jahwes gestanden hat.\"" },
      { number: 12, text: "Von da an opferte Salomo die Brandopfer für Jahwe auf dem Altar Jahwes, den er vor der Halle des Tempelhauses gebaut hatte," },
      { number: 13, text: "so wie es der Anordnung Moses für jeden Tag entsprach. Auch an den Sabbaten, den Neumondstagen und den drei Jahresfesten tat er das: dem Fest der ungesäuerten Brote*, dem Wochenfest* und dem Laubhüttenfest.", footnotes: ["Das Fest der ungesäuerten Brote folgte unmittelbar auf das Passafest (2. Mose 12-13) und dauerte eine Woche.", "Das Wochenfest oder Pfingstfest wurde 50 Tage nach dem Passa als Erntefest gefeiert. Gleichzeitig gedachte man dabei besonders der Gabe des Gesetzes Gottes."] },
      { number: 14, text: "Nach den Anweisungen seines Vaters David wies er die Abteilungen der Priester in ihren Dienst ein, ebenso die Leviten, die für den Gesang verantwortlich waren und den Priestern und Torwächtern in ihren Dienstabteilungen halfen, genauso, wie es David, der Mann Gottes, festgelegt hatte." },
      { number: 15, text: "Man wich in keinem Punkt von den Anordnungen ab, die der König für die Priester, die Leviten, für die Tempelschätze und für alles andere gegeben hatte." },
      { number: 16, text: "So wurde das ganze Werk Salomos planmäßig ausgeführt, vom Tag der Grundsteinlegung des Hauses Jahwes an bis zu seiner Vollendung. Das Haus Jahwes war fertig." },
      { number: 17, text: "Damals kam Salomo auch nach Ezjon-Geber und Elat* an der Küste des Roten Meeres im Land Edom.", footnotes: ["Ezjon-Geber und Elat lagen am Nordende des Golfs von Akaba in der Nähe der Stadt Akaba."] },
      { number: 18, text: "Hiram schickte ihm Schiffe mit erfahrenen Seeleuten dorthin. Zusammen mit den Männern Salomos segelten sie bis nach Ofir* und brachten Salomo von dort 16 Tonnen* Gold.", footnotes: ["Ofir. Die LXX verstand das als Indien. Dafür spricht, dass es alle in der Bibel erwähnten Güter (Gold, Silber, Edelsteine, Hölzer, Elfenbein, Affen und Pfauen) im alten Indien gab. Ferner ist bekannt, dass vom 2. Jahrtausend v. Chr. an lebhafter Handel zwischen dem Persischen Golf und Indien getrieben wurde. Dazu waren Hochseeschiffe (1. Könige 22,48: Tarschisch-Schiffe) nötig. Eine andere Theorie besagt, dass Ofir eine Stadt war, die vermutlich an der südwestlichen Küste Arabiens oder 75 km nördlich von Bombay (Supura) lag.", "16 Tonnen. Wörtlich: 450 Talente. Als Gewichtseinheit entspricht 1 Talent etwa 34,5 Kilogramm."] },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Als die Königin von Saba* vom Ruhm Salomos hörte, kam sie mit einem gewaltigen Gefolge nach Jerusalem. Ihre Kamele waren schwer mit duftenden Ölen, Gold und Edelsteinen beladen. Sie wollte Salomo mit schwierigen Fragen prüfen und besprach mit ihm alles, was sie sich überlegt hatte.", heading: "Die Königin von Saba", footnotes: ["Saba. Land südlich von Israel (siehe Matthäus 12,42), vielleicht auf der südwestlichen arabischen Halbinsel in der Nähe des heutigen Jemen. Die genaue Lage ist ungewiss."] },
      { number: 2, text: "Salomo beantwortete alle ihre Fragen. Es gab nichts, was ihm verborgen war, worauf er keine Antwort gewusst hätte." },
      { number: 3, text: "Als die Königin von Saba die Weisheit Salomos erkannte, als sie den Palast sah, den er gebaut hatte," },
      { number: 4, text: "die Speisen an seiner Tafel, die Sitzplätze seiner Beamten, die gute Bedienung und die kostbaren Gewänder seiner Diener und Mundschenke und die prunkvolle Prozession, wenn er in das Haus Jahwes ging, da verschlug es ihr den Atem." },
      { number: 5, text: "Sie sagte zum König: \"Es ist tatsächlich alles wahr, was ich in meinem Land über dich und deine Weisheit gehört habe." },
      { number: 6, text: "Ich wollte es nicht glauben, bis ich es mit eigenen Augen gesehen hatte. Und nun sehe ich: Man hat mir nicht einmal die Hälfte gesagt. Deine Weisheit übertrifft alles, was ich je über dich gehört habe." },
      { number: 7, text: "Was für ein Vorrecht haben deine Männer und deine Minister, die täglich bei dir sind und deine weisen Worte hören!" },
      { number: 8, text: "Gepriesen sei Jahwe, dein Gott, dem es gefiel, dich auf deinen Thron zu setzen als König für Jahwe, deinen Gott. Dein Gott liebt sein Volk und will, dass es für immer besteht. Deshalb hat er dich zum König gemacht, dass du für Recht und Gerechtigkeit sorgst.\"" },
      { number: 9, text: "Dann übergab sie dem König mehr als vier Tonnen* Gold, eine Menge duftender Öle und Edelsteine. Nie wieder hat es so kostbares Öl gegeben wie dieses, das die Königin von Saba Salomo als Geschenk überbrachte.", footnotes: ["vier Tonnen. Wörtlich: 120 Talente."] },
      { number: 10, text: "Die Leute Hirams und Salomos, die Gold aus Ofir geholt hatten, brachten Almuggimholz* und Edelsteine.", footnotes: ["Almuggimholz. Siehe 2. Chronik 2,7."] },
      { number: 11, text: "Der König hatte aus dem Almuggimholz Geländer für das Haus Jahwes und den Regierungspalast anfertigen lassen und Zithern und Harfen für die Tempelsänger. Vorher war so etwas im Land Juda nie gesehen worden." },
      { number: 12, text: "König Salomo erfüllte der Königin von Saba jeden Wunsch, den sie äußerte, zusätzlich zu der Gegengabe für das, was sie dem König mitgebracht hatte. Danach kehrte sie mit ihrem Gefolge wieder in ihr Land zurück." },
      { number: 13, text: "In einem einzigen Jahr erhielt Salomo 23 Tonnen* Gold als Steuerabgabe.", heading: "Salomos Reichtum", footnotes: ["23 Tonnen. Wörtlich: 666 Talente."] },
      { number: 14, text: "Dazu kam noch das, was die Händler einbrachten. Auch alle Könige Arabiens und die Statthalter des Landes brachten Salomo Gold und Silber." },
      { number: 15, text: "König Salomo ließ 200 Langschilde anfertigen und mit Gold überziehen. Sieben Kilogramm* gehämmertes Gold verwendete er für jeden Schild.", footnotes: ["Sieben Kilogramm. Wörtlich: 600 (Schekel). Der königliche Schekel wog etwa 13 Gramm, der Schekel nach gefundenen Gewichten 11,5 Gramm."] },
      { number: 16, text: "Dazu ließ er noch 300 Kleinschilde machen und jeden mit dreieinhalb Kilogramm gehämmertem Gold überziehen. Er brachte sie alle in das Libanonwaldhaus*.", footnotes: ["Das Libanonwaldhaus war eine große Halle, die Salomo neben seinem Regierungspalast hatte bauen lassen, siehe 1. Könige 7,2."] },
      { number: 17, text: "Weiter ließ der König einen großen Thron aus Elfenbein anfertigen und mit purem Gold überziehen." },
      { number: 18, text: "Der Thron hatte sechs Stufen und einen goldenen Fußschemel. Zu beiden Seiten des Sitzes befanden sich Armlehnen, neben denen zwei Löwenfiguren standen." },
      { number: 19, text: "Auch auf jeder der sechs Stufen stand rechts und links je eine Löwenfigur. Noch nie ist so etwas für ein Königreich geschaffen worden." },
      { number: 20, text: "Alle Trinkgefäße Salomos waren aus reinem Gold und auch sämtliche Gegenstände, die zum Libanonwaldhaus gehörten. Silber war zur Zeit Salomos wertlos;" },
      { number: 21, text: "denn der König hatte eine Flotte, die mit den Leuten Hirams bis nach Tarschisch* fuhr. Alle drei Jahre kam die Tarschisch-Flotte und brachte Gold und Silber, Elfenbein, Affen und Pfauen.", footnotes: ["Tarschisch war die phönizische Kolonie Tartessus in Südspanien, wo Silber abgebaut wurde. Doch konnte offenbar auch ein anderes Gebiet im südlichen Teil des Roten Meeres, wo kostbare Metalle abgebaut wurden, so genannt werden (siehe 2. Chronik 20,36). Die großen hochseetüchtigen Handelsschiffe der Phönizier nannte man generell Tarschisch-Schiffe."] },
      { number: 22, text: "Somit übertraf König Salomo alle anderen Könige der Erde an Reichtum und Weisheit;" },
      { number: 23, text: "und alle Könige suchten ihn auf, um sich persönlich von der Weisheit zu überzeugen, die Gott ihm verliehen hatte." },
      { number: 24, text: "Alle brachten ihm Geschenke mit: silberne und goldene Gegenstände, Festgewänder und Waffen, kostbare Öle, Pferde und Maultiere. So ging es Jahr um Jahr." },
      { number: 25, text: "Salomo hatte 4000 Stallplätze für seine Pferde und Streitwagen sowie 12.000 Pferde. Er stationierte sie in den Wagenstädten und bei sich in Jerusalem." },
      { number: 26, text: "Er herrschte über alle Könige vom Euphrat bis zum Land der Philister und bis zur Grenze Ägyptens." },
      { number: 27, text: "Unter seiner Regierung war Silber in Jerusalem so viel wert wie Steine, und Zedern wie die Maulbeerfeigenbäume, die in der Niederung wachsen." },
      { number: 28, text: "Die Pferde bekam Salomo aus Ägypten und aus allen möglichen anderen Ländern." },
      { number: 29, text: "Was sonst noch über Salomo zu sagen ist, seine frühere und spätere Geschichte, findet man in der Chronik des Propheten Natan, den Weissagungen Ahias von Schilo und in den Visionen des Sehers Jedo, die dieser über Jerobeam Ben-Nebat erhalten hat.", heading: "Salomos Tod" },
      { number: 30, text: "Vierzig Jahre lang regierte Salomo über ganz Israel in Jerusalem." },
      { number: 31, text: "Als er gestorben war, bestattete man ihn in der Davidsstadt, und sein Sohn Rehabeam trat die Herrschaft an." },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Rehabeam reiste nach Sichem*, denn ganz Israel war dorthin gekommen, um ihn als König zu bestätigen.", heading: "10-36: Die Könige von Juda\nDie Reichsteilung (10-16)\nDie Teilung Israels", footnotes: ["Sichem war eine strategisch und religiös bedeutende Stadt auf dem Pass (Sichem = Schulter) zwischen den Bergen Ebal im Norden und Garizim im Süden."] },
      { number: 2, text: "Als Jerobeam Ben-Nebat davon gehört hatte, war er aus Ägypten zurückgekehrt, wohin er vor Salomo hatte fliehen müssen." },
      { number: 3, text: "Nun ließen die Stämme Israels ihn rufen. Da stellte er sich zusammen mit ihnen vor Rehabeam und sagte:" },
      { number: 4, text: "\"Dein Vater hat uns ein hartes Joch auferlegt. Erleichtere uns jetzt die Last, die dein Vater uns aufgebürdet hat, und seinen harten Arbeitsdienst, dann wollen wir dir untertan sein.\"" },
      { number: 5, text: "\"Kommt in drei Tagen wieder zu mir!\", erwiderte Rehabeam. Als das Volk gegangen war," },
      { number: 6, text: "beriet sich König Rehabeam mit den Alten, die bereits im Dienst seines Vaters Salomo gestanden hatten. Er fragte sie: \"Was ratet ihr mir? Welche Antwort soll ich dem Volk geben?\"" },
      { number: 7, text: "Sie sagten: \"Wenn du ihnen entgegenkommst und sie mit Güte behandelst, werden sie dir für immer gehorchen.\"" },
      { number: 8, text: "Doch er verwarf den Rat der Alten und fragte die jungen Leute, die mit ihm aufgewachsen waren und jetzt in seinem Dienst standen." },
      { number: 9, text: "\"Was ratet ihr mir? Was sollen wir diesem Volk sagen, das von mir verlangt, das Joch zu erleichtern, das mein Vater auf sie gelegt hat?\"" },
      { number: 10, text: "Da sagten ihm die jungen Leute, die mit ihm aufgewachsen waren: \"Dem Volk, das von dir verlangt, das schwere Joch zu erleichtern, das dein Vater ihm auferlegt hat, sollst du sagen: 'Mein kleiner Finger ist dicker als die Hüften meines Vaters!" },
      { number: 11, text: "Mein Vater hat euch eine schwere Last aufgeladen, ich werde sie noch schwerer machen! Mein Vater hat euch mit Peitschen gezüchtigt, ich werde es mit Stachelpeitschen tun!'\"" },
      { number: 12, text: "Am dritten Tag kamen Jerobeam und das ganze Volk wieder zu Rehabeam, wie der König gesagt hatte." },
      { number: 13, text: "König Rehabeam gab ihnen eine harte Antwort. Er verwarf die Empfehlung der Alten" },
      { number: 14, text: "und richtete sich nach dem Rat der jungen Leute. Er sagte: \"Mein Vater hat euch eine schwere Last aufgeladen, ich werde sie noch schwerer machen! Mein Vater hat euch mit Peitschen gezüchtigt, ich werde es mit Stachelpeitschen tun!\"" },
      { number: 15, text: "Der König hörte also nicht auf das Volk. Gott hatte es so gefügt, um das Wort wahr zu machen, das er, Jahwe, durch Ahija von Schilo zu Jerobeam Ben-Nebat gesprochen hatte.*", footnotes: ["Siehe 1. Könige 11,29-31."] },
      { number: 16, text: "Als nun die Männer Israels sahen, dass der König nicht auf sie hören wollte, riefen sie:Was geht uns Davids Sippe an? / Isais Sohn gehört nicht zu uns! / Auf, nach Hause, Israel! / Mag Davids Sippe doch sehen, wo sie bleibt!So löste sich die Versammlung auf, und jeder ging nach Hause." },
      { number: 17, text: "Nur über die Israeliten, die in den Städten Judas wohnten, blieb Rehabeam König." },
      { number: 18, text: "Als König Rehabeam dann Hadoram hinschickte, den Beauftragten für die Zwangsarbeit, steinigten ihn die Israeliten zu Tode. Der König selbst konnte sich gerade noch auf seinen Wagen retten und nach Jerusalem entkommen." },
      { number: 19, text: "So sagten sich die Nordstämme Israels vom Königshaus David los und sind bis zum heutigen Tag von ihnen getrennt." },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Als Rehabeam in Jerusalem angekommen war, stellte er aus den Stämmen Juda und Benjamin ein Heer von 180.000 Soldaten zusammen. Sie sollten gegen Israel kämpfen, um die Königsherrschaft für Rehabeam zurück zu erobern.", heading: "Rehabeam von Juda" },
      { number: 2, text: "Da kam das Wort Jahwes zu einem Mann Gottes namens Schemaja:" },
      { number: 3, text: "\"Sage zu Rehabeam Ben-Salomo, dem König von Juda, und zu ganz Israel in Juda und Benjamin:" },
      { number: 4, text: "'So spricht Jahwe: Zieht nicht los! Kämpft nicht gegen eure Brüder! Kehrt allesamt nach Hause zurück! Ich selbst habe es so gefügt.'\" Da gehorchten sie den Worten Jahwes, kehrten um und zogen nicht gegen Jerobeam." },
      { number: 5, text: "So blieb Rehabeam in Jerusalem und ließ verschiedene Städte in Juda zu Festungen ausbauen." },
      { number: 6, text: "Es waren: Bethlehem, Etam, Tekoa," },
      { number: 7, text: "Bet-Zur, Socho, Adullam," },
      { number: 8, text: "Gat, Marescha, Sif," },
      { number: 9, text: "Adorajim, Lachisch, Aseka," },
      { number: 10, text: "Zora, Ajalon und Hebron." },
      { number: 11, text: "Er ließ diese Städte stark befestigen, setzte Kommandanten ein und ließ Vorräte an Lebensmitteln, Olivenöl und Wein anlegen." },
      { number: 12, text: "In jeder Stadt befanden sich Schilde und Spieße, sodass die Städte in jeder Hinsicht stark waren. So herrschte er über Juda und Benjamin." },
      { number: 13, text: "Die Priester und Leviten, die überall in Israel wohnten, standen zu Rehabeam." },
      { number: 14, text: "Die Leviten verließen ihre Weideplätze und ihren Besitz und kamen nach Juda und Jerusalem, weil Jerobeam und seine Söhne sie aus dem Priesterdienst für Jahwe verstoßen hatten." },
      { number: 15, text: "Jerobeam hatte nämlich eigene Priester für die Höhenheiligtümer angestellt, für die Bocksdämonen und die Stierbilder, die er hatte anfertigen lassen." },
      { number: 16, text: "Aus allen Stämmen Israels folgten den Leviten die Israeliten, die Jahwe, den Gott Israels, von Herzen suchten. Sie kamen nach Jerusalem, um dem Gott ihrer Vorfahren Opfer zu bringen." },
      { number: 17, text: "Und sie trugen dazu bei, das Königreich Juda zu stärken und Rehabeams Herrschaft zu festigen. Das taten sie drei Jahre, so lange, wie alle dem Vorbild Davids und Salomos folgten." },
      { number: 18, text: "Rehabeam heiratete Mahalat, die Tochter von Jerimot Ben-David und seiner Frau Abihajil, der Tochter von Eliab Ben-Isai." },
      { number: 19, text: "Sie gebar ihm die Söhne Jëusch, Schemarja und Saham." },
      { number: 20, text: "Danach heiratete er Maacha, die Tochter* Abschaloms. Von ihr wurden ihm Abija, Attai, Sisa und Schelomit geboren.", footnotes: ["Tochter. Ebenso wie Sohn in vielen Fällen auch Enkel oder Nachkomme allgemein bedeuten kann, meint Tochter hier offenbar Enkelin (ebenso Vers 22). Maacha war also wahrscheinlich eine Tochter von Abschaloms Tochter Tamar, die mit Uriel verheiratet war; siehe 2. Chronik 13,2."] },
      { number: 21, text: "Rehabeam liebte Maacha mehr als seine anderen Frauen. Insgesamt hatte er nämlich 18 Frauen und 60 Nebenfrauen genommen und mit ihnen 28 Söhne und 60 Töchter gezeugt." },
      { number: 22, text: "Deshalb gab er Abija, dem Sohn von Maacha, eine führende Stellung unter seinen Brüdern und bestimmte ihn zum Thronfolger." },
      { number: 23, text: "Rehabeam handelte wohlüberlegt und verteilte seine Söhne auf die befestigten Städte von Juda und Benjamin, gab ihnen ein sehr gutes Einkommen und suchte eine Menge Frauen für sie aus." },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Als Rehabeams Herrschaft gesichert war und er mächtig wurde, hielt er sich nicht mehr an die Weisung Jahwes. Ganz Israel* folgte ihm darin.", heading: "Einfall der Ägypter", footnotes: ["Israel ist hier und in Vers 6 im allgemeinen Sinn gebraucht und nicht auf das Nordreich bezogen."] },
      { number: 2, text: "Da zog im fünften Regierungsjahr Rehabeams* König Schischak* von Ägypten gegen Jerusalem in den Krieg, denn die Israeliten waren Jahwe untreu geworden.", footnotes: ["fünften ... Rehabeams. 925 v.Chr.", "Schischak wird gewöhnlich mit Pharao Scheschonk I identifiziert, was aber auf schwerwiegende Probleme stößt, wenn man den Feldzugsbericht des Pharaos mit den biblischen Angaben vergleicht. Neuerdings wird eine Revision der ägyptischen Chronologie diskutiert. Der entsprechende Pharao wäre dann vielleicht Ramses II, der angibt, in seinem 8. Regierungsjahr Jerusalem geplündert zu haben."] },
      { number: 3, text: "Schischak kam mit 1 200 Streitwagen, 60.000 Pferden und einer ungezählten Menge von libyschen, sukkijitischen* und nubischen* Hilfstruppen.", footnotes: ["sukkijitischen … Hilfstruppen. Nach ägyptischen Texten eine Söldnertruppe aus Libyen.", "Nubien. Hebräisch: Kusch. Land am Oberlauf des Nil, südlich von Ägypten."] },
      { number: 4, text: "Er eroberte die Festungen in Juda und rückte gegen Jerusalem vor." },
      { number: 5, text: "Da trat der Prophet Schemaja vor Rehabeam und die führenden Männer von Juda, die sich vor Schischak nach Jerusalem zurückgezogen hatten, und sagte zu ihnen: \"So spricht Jahwe: 'Ihr habt mich verlassen, darum überlasse auch ich euch der Gewalt Schischaks.'\"" },
      { number: 6, text: "Da beugten sich die führenden Männer Israels mit dem König und sagten: \"Jahwe ist gerecht!\"" },
      { number: 7, text: "Als Jahwe sah, dass sie sich demütigten, kam sein Wort zu Schemaja: \"Sie haben sich gedemütigt. Darum werde ich sie nicht beseitigen, sondern schenke ihnen ein wenig Rettung. Schischak soll nicht meinen Zorn über Jerusalem bringen." },
      { number: 8, text: "Doch sie müssen sich ihm unterwerfen, damit sie erkennen, was für ein Unterschied es ist, ob sie mir dienen oder den Königen anderer Länder.\"" },
      { number: 9, text: "König Schischak von Ägypten marschierte also in Jerusalem ein und eignete sich die Schätze aus dem Haus Jahwes und dem Königspalast an. Auch die goldenen Schilde, die Salomo hatte anfertigen lassen, nahm er mit." },
      { number: 10, text: "An deren Stelle ließ König Rehabeam Bronzeschilde anfertigen, die er dem Kommandanten der Leibwache übergab, die am Eingang des Palastes stationiert war." },
      { number: 11, text: "Jedes Mal, wenn der König in das Haus Jahwes ging, trugen seine Leibwächter die Schilde und brachten sie anschließend an ihren Platz zurück." },
      { number: 12, text: "Weil Rehabeam sich gedemütigt hatte, ließ der Zorn Jahwes von ihm ab, sodass er ihn nicht völlig vernichtete. Es gab ja auch noch manches Gute in Juda." },
      { number: 13, text: "König Rehabeam festigte seine Herrschaft und regierte weiter in Jerusalem. Er war 41 Jahre alt, als er die Herrschaft antrat. Siebzehn Jahre* regierte er in Jerusalem, der Stadt, die Jahwe aus allen Stämmen Israels als Wohnsitz für seinen Namen bestimmt hatte. Seine Mutter war die Ammoniterin Naama.", heading: "Das Ende Rehabeams", footnotes: ["Siebzehn Jahre. Rehabeam regierte von 931-913 v.Chr."] },
      { number: 14, text: "Doch er tat Böses und war nicht darauf bedacht, Jahwe zu suchen." },
      { number: 15, text: "Was sonst noch über Rehabeam zu sagen ist, seine frühere und spätere Geschichte, findet man in der Chronik des Propheten Schemaja und in der des Sehers Iddo. Sie enthalten auch seinen Stammbaum. Die Auseinandersetzungen zwischen Rehabeam und Jerobeam dauerten die ganze Zeit an." },
      { number: 16, text: "Als Rehabeam gestorben war, bestattete man ihn in der Davidsstadt; und sein Sohn Abija trat die Herrschaft an." },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Im 18. Regierungsjahr des Königs Jerobeam von Israel trat Abija die Herrschaft über Juda an.", heading: "Abija von Juda" },
      { number: 2, text: "Er regierte drei Jahre lang in Jerusalem. Seine Mutter hieß Maacha* und war die Tochter von Uriël aus Gibea. Auch Abija führte Krieg gegen Jerobeam.", footnotes: ["Maacha. So mit der LXX und 2. Chronik 11,20; 1. Könige 15,2. Der hebräische Text hat hier: Michaja. Vielleicht hatte Maacha, wie nicht selten in der Bibel, einen zweiten Namen."] },
      { number: 3, text: "Er eröffnete ihn mit einem Heer von 400.000 kampferprobten Soldaten. Jerobeam stellte sich ihm mit 800.000 wehrtüchtigen Männern entgegen." },
      { number: 4, text: "Vor dem Kampf stieg Abija auf den Berg Zemarajim*, der zum Bergland von Efraïm gehört, und rief: \"Hört mich an, Jerobeam und ganz Israel!", footnotes: ["Der Berg Zemarajim, der zur gleichnamigen benjaminitischen Stadt gehört, liegt etwa 15 km nördlich von Jerusalem."] },
      { number: 5, text: "Ihr müsst doch wissen, dass Jahwe, der Gott Israels, David und seinen Nachkommen die Herrschaft über Israel in einem Salzbund* für alle Zeiten verliehen hat.", footnotes: ["Ein Salzbund konnte nicht gebrochen werden, siehe 4. Mose 18,19. Der Begriff kommt vielleicht daher, dass Salz bei allen Opfern verwendet werden musste (3. Mose 2,13; Hesekiel 43,24) und deshalb wohl auch beim Bundesmahl Verwendung fand (2. Mose 24,5-11)."] },
      { number: 6, text: "Aber Jerobeam Ben-Nebat, ein Diener von Salomo Ben-David, rebellierte gegen seinen Herrn." },
      { number: 7, text: "Er scharte eine Gruppe von nichtswürdigen Abenteurern um sich und widersetzte sich Rehabeam Ben-Salomo. Rehabeam war damals noch zu jung, um ihnen standzuhalten." },
      { number: 8, text: "Und jetzt meint ihr, ihr könnt dem Königtum Jahwes standhalten, das den Nachkommen Davids übertragen ist? Meint ihr, das gelingt, weil ihr so viele seid und weil ihr die goldenen Kälber bei euch habt, die Jerobeam euch zu Göttern machte?" },
      { number: 9, text: "Habt ihr nicht die Priester Jahwes, die Nachkommen Aarons und die Leviten verstoßen und euch neue Priester eingesetzt, wie es die anderen Völker auch tun? Jeder, der mit einem jungen Stier und sieben Schafböcken kam, konnte sich zum Priester für die Nicht-Götter weihen lassen." },
      { number: 10, text: "Doch unser Gott ist Jahwe. Wir haben ihn nicht verlassen. Bei uns dienen ihm die Nachkommen Aarons, und auch die Leviten tun, was ihnen aufgetragen ist." },
      { number: 11, text: "Jeden Morgen und jeden Abend bringen sie Jahwe Brandopfer und wohlriechendes Räucherwerk dar. Sie sorgen für das Schichtbrot auf dem reinen Opfertisch und zünden jeden Abend die Lampen auf dem goldenen Leuchter an. Denn wir halten uns an die Anordnungen von Jahwe, unserem Gott. Doch ihr habt ihn verlassen." },
      { number: 12, text: "Seht, Gott ist mit uns, er steht an unserer Spitze! Bei uns sind auch seine Priester mit den Lärmtrompeten, um gegen euch Kriegslärm zu blasen. Ihr Männer von Israel, kämpft nicht gegen Jahwe, den Gott eurer Väter! Das wird euch nicht gelingen.\"" },
      { number: 13, text: "Aber Jerobeam ließ die Männer im Hinterhalt eine Umgehung machen, um den Leuten von Juda in den Rücken zu fallen. So stand ein Teil seines Heeres vor den Judäern, der Hinterhalt aber in ihrem Rücken." },
      { number: 14, text: "Als die Männer von Juda sahen, dass sie an zwei Fronten kämpfen mussten, schrien sie zu Jahwe. Die Priester bliesen die Trompeten," },
      { number: 15, text: "und die Männer von Juda stimmten das Kriegsgeschrei an. Da schlug Gott Jerobeam und ganz Israel durch Abija und Juda." },
      { number: 16, text: "Die Männer Israels mussten vor Juda fliehen. Gott gab sie in ihre Gewalt." },
      { number: 17, text: "Abija und seine Männer brachten ihnen eine schwere Niederlage bei. 500.000 wehrtüchtige Männer blieben erschlagen liegen." },
      { number: 18, text: "Damals wurden die Israeliten in die Knie gezwungen, und die Leute von Juda hatten die Oberhand, denn sie vertrauten auf Jahwe, den Gott ihrer Väter." },
      { number: 19, text: "Abija verfolgte Jerobeam noch weiter und nahm ihm die Städte Bet-El, Jeschana und Efron samt den dazugehörigen Ortschaften ab." },
      { number: 20, text: "Solange Abija lebte, kam Jerobeam nicht wieder zu Kräften, und Jahwe ließ ihn schließlich sterben." },
      { number: 21, text: "Abija aber wurde mächtig. Er nahm sich 14 Frauen und zeugte insgesamt 22 Söhne und 16 Töchter." },
      { number: 22, text: "Was sonst noch über Abija, seine Taten und Reden zu sagen ist, findet man in der Chronik des Propheten Iddo." },
      { number: 23, text: "Als Abija starb, bestattete man ihn in der Davidsstadt; und sein Sohn Asa trat die Herrschaft an. Unter seiner Regierung hatte das Land zehn Jahre Ruhe." },
    ] },
    { number: 14, verses: [
      { number: 1, text: "Asa tat, was gut und recht war und was Jahwe, seinem Gott, gefiel.", heading: "König Asas Erfolge" },
      { number: 2, text: "Er beseitigte die fremden Altäre und die Opferhöhen, ließ die geweihten Steinmale zerschlagen und die Aschera-Pfähle* umhauen.", footnotes: ["Die Aschera war eine Fruchtbarkeitsgöttin, die in handlichen Figuren, geweihten Bäumen oder Pfählen verehrt wurde."] },
      { number: 3, text: "Er befahl den Judäern, Jahwe, den Gott ihrer Väter, zu suchen und seine Weisung und seine Gebote zu befolgen." },
      { number: 4, text: "Auch in den anderen Städten Judas beseitigte er die Opferhöhen und die Räucheraltäre. In diesen Jahren hatte das Land Frieden," },
      { number: 5, text: "weil Jahwe dafür sorgte, dass niemand mit Asa Krieg führte. Damals ließ Asa einige Städte in Juda befestigen." },
      { number: 6, text: "Er sagte zu den Leuten von Juda: \"Lasst uns diese Städte ausbauen, sie mit Mauern umgeben und mit Türmen, Toren und Riegeln sichern. Noch haben wir freie Hand im Land, denn wir haben Jahwe, unseren Gott, gesucht, und er hat uns ringsherum Ruhe verschafft.\" So konnten sie bauen und hatten Erfolg." },
      { number: 7, text: "Asa hatte ein Heer von 300.000 Mann aus Juda, die Speer und Langschild trugen, und 280.000 Mann aus Benjamin, die Rundschilde trugen und mit Bogen ausgerüstet waren, alles wehrtüchtige Männer." },
      { number: 8, text: "Da rückte der Nubier Serach mit einem Heer von 1000 mal 1000 Mann und 300 Streitwagen gegen Juda vor und kam bis Marescha*.", footnotes: ["Marescha war eine der von Asa befestigten Städte im Hügelland von Juda. Sie liegt 21 km nordwestlich von Hebron."] },
      { number: 9, text: "Asa zog ihm entgegen, und die beiden Heere stellten sich im Zefata-Tal bei Marescha in Schlachtordnung auf." },
      { number: 10, text: "Asa betete zu Jahwe, seinem Gott: \"Jahwe\", sagte er, \"außer dir gibt es keinen, der helfen könnte, wenn ein Schwacher gegen einen Mächtigen bestehen muss. Hilf uns, Jahwe, unser Gott! Wir vertrauen auf dich, sind wir doch in deinem Namen gegen diese Menge gezogen. Du bist unser Gott, Jahwe! Kein Mensch kommt gegen dich an!\"" },
      { number: 11, text: "Da schlug Jahwe die Nubier vor Asa und Juda zurück, dass sie flohen." },
      { number: 12, text: "Asa verfolgte sie mit seinen Männern bis nach Gerar*. Dabei fielen von den Nubiern so viele, dass sie sich von diesem Verlust nicht wieder erholen konnten. Sie wurden durch Jahwe und sein Heer vernichtend geschlagen. Die Judäer aber machten reiche Beute.", footnotes: ["Gerar liegt in der Nähe von Gaza. Asa verfolgte die Feinde also etwa 50 km weit."] },
      { number: 13, text: "Sie konnten auch alle Städte rings um Gerar* erobern, denn der Schrecken Jahwes war über sie gekommen. Sie plünderten alle diese Orte, denn es gab dort reiche Beute.", footnotes: ["Städte ... Gerar. Das waren Ortschaften, die den Philistern gehörten."] },
      { number: 14, text: "Auch die Zeltlager der Hirten überwältigten sie. Und als sie wieder nach Jerusalem zurückkehrten, nahmen sie eine Menge Schafe, Ziegen und Kamele als Beute mit." },
    ] },
    { number: 15, verses: [
      { number: 1, text: "Da kam der Geist Gottes über Asarja Ben-Oded,", heading: "König Asas Reformen" },
      { number: 2, text: "sodass er Asa entgegenging und zu ihm sagte: \"Hört mir zu, Asa und ihr alle von Juda und Benjamin! Jahwe ist bei euch, solange ihr bei ihm seid. Wenn ihr ihn sucht, wird er sich von euch finden lassen. Wenn ihr ihn aber verlasst, wird auch er euch verlassen." },
      { number: 3, text: "Lange Zeit war Israel ohne den wahren Gott. Da hatten sie auch keine Priester, die sie lehrten, und kannten das Gesetz nicht." },
      { number: 4, text: "Doch jedes Mal, wenn die Israeliten bedrängt wurden, kehrten sie zu Jahwe, dem Gott Israels, um. Sie suchten ihn, und er ließ sich von ihnen finden." },
      { number: 5, text: "Damals konnte niemand ungefährdet reisen, denn es gab viele Unruhen in den Ländern." },
      { number: 6, text: "Die Völker bedrängten sich gegenseitig, und die Städte lagen im Streit, denn Gott hatte sie durch verschiedene Bedrängnisse verunsichert." },
      { number: 7, text: "Darum fasst Mut und legt die Hände nicht in den Schoß, denn euer Tun wird seinen Lohn finden!\"" },
      { number: 8, text: "Als Asa die prophetischen Worte vom Sohn Odeds* hörte, fasste er Mut. Er ließ die scheußlichen Götzenbilder aus dem ganzen Land entfernen, aus Juda, aus Benjamin und den Städten, die er auf dem Bergland von Efraïm erobert hatte. Auch den Altar Jahwes vor der Vorhalle des Tempels ließ er erneuern.", footnotes: ["Sohn Odeds. Wörtlich: von dem Propheten Oded, siehe aber V. 1."] },
      { number: 9, text: "Dann ließ er ganz Juda und Benjamin zusammenrufen sowie die Leute von Efraïm, Manasse und Simeon, die sich bei ihnen aufhielten. Es waren nämlich viele zu ihm übergelaufen, als sie sahen, dass Jahwe, sein Gott, auf seiner Seite war." },
      { number: 10, text: "Im Juni* des 15. Regierungsjahrs von Asa versammelten sich alle in Jerusalem", footnotes: ["Juni. Wörtlich: 3. Monat. Es war im Jahr 895 v.Chr."] },
      { number: 11, text: "und opferten Jahwe von der Beute, die sie heimgebracht hatten, 700 Rinder und 7000 Schafe." },
      { number: 12, text: "Sie legten sich die Verpflichtung auf, Jahwe, dem Gott ihrer Vorfahren, mit ganzem Herzen und ganzer Person zu folgen." },
      { number: 13, text: "Und wer Jahwe, den Gott Israels, nicht verehren würde, sollte mit dem Tod bestraft werden, egal ob Mann oder Frau, klein oder groß." },
      { number: 14, text: "Das gelobten sie Jahwe laut, unter Jubelrufen und dem Schall von Trompeten und Hörnern." },
      { number: 15, text: "Ganz Juda freute sich über den Schwur, denn sie hatten aus ganzer Überzeugung eingestimmt. Mit ganzem Willen hatten sie Jahwe gesucht, und er hatte sich ihnen zugewandt. Und er gab ihnen ringsherum Frieden." },
      { number: 16, text: "König Asa entzog sogar der Königsmutter Maacha ihren Rang*, weil sie der Aschera ein Schandbild aufgestellt hatte. Asa ließ das Scheusal umhauen, in Stücke schlagen und im Kidrontal verbrennen.", footnotes: ["entzog ... Rang. Siehe 2. Chronik 11,20-22."] },
      { number: 17, text: "Die Opferhöhen in Israel blieben allerdings bestehen, doch Asas Herz war sein Leben lang ungeteilt auf Gott ausgerichtet." },
      { number: 18, text: "Er brachte die Weihgaben seines Vaters in das Haus Gottes und dazu seine eigenen Gaben: goldene und silberne Gegenstände." },
      { number: 19, text: "Bis zum 35. Regierungsjahr* Asas gab es keinen Krieg.", footnotes: ["35. Regierungsjahr. Es muss wohl heißen: 15. Regierungsjahr, siehe Fußnote zu Kapitel 16,1."] },
    ] },
    { number: 16, verses: [
      { number: 1, text: "Im 36. Regierungsjahr* Asas baute König Bascha von Israel die Stadt Rama* zur Festung aus, um die Wege von und nach Juda kontrollieren zu können.", heading: "Asas Bündnis mit Syrien", footnotes: ["36. Regierungsjahr. Es muss wohl heißen: 16. Regierungsjahr, denn nach 1. Könige 16,6.8 war Bascha damals schon 10 Jahre tot. Die Spannung kann dadurch aufgelöst werden, dass man entweder annimmt, dass hier das 36. Jahr des Königreiches Juda gemeint sei, oder dass es sich um einen Abschreibfehler handelt, wobei die Vorlage die Zahlen als numerische Zeichen stehen hatte, die man im Althebräischen leicht verwechseln konnte.", "Rama liegt nur 8 km nördlich von Jerusalem."] },
      { number: 2, text: "Da schickte Asa Boten mit Gold und Silber aus den Schatzkammern des Tempels und des Königshauses zu König Ben-Hadad von Syrien nach Damaskus und ließ ihm sagen:" },
      { number: 3, text: "\"Zwischen mir und dir, zwischen meinem und deinem Vater soll ein Bündnis sein! Darum habe ich dir Silber und Gold geschickt. Brich deinen Bund mit König Bascha von Israel, damit er von meiner Grenze abzieht!\"" },
      { number: 4, text: "Ben-Hadad ging darauf ein und schickte seine Heerführer gegen Israels Städte. Sie verwüsteten Ijon, Dan und Abel-Majim* und alle Vorratslager der Städte im Stamm Naftali.", footnotes: ["Ijon ... Abel-Majim. Das sind drei Orte ganz im Norden Israels. Abel-Majim ist auch unter dem Namen Abel-Bet-Maacha bekannt."] },
      { number: 5, text: "Als Bascha das erfuhr, stellte er die Arbeiten ein und brach den Ausbau von Rama ab." },
      { number: 6, text: "König Asa bot alle Männer von Juda auf. Sie mussten die Steine und das Bauholz, das Bascha verwenden wollte, aus Rama abtransportieren. Asa ließ damit die Städte Geba und Mizpa* befestigen.", footnotes: ["Geba und Mizpa. Die Städte liegen ganz in der Nähe Ramas."] },
      { number: 7, text: "Zu dieser Zeit kam der Seher Hanani zu König Asa von Juda und sagte zu ihm: \"Du hast dich auf den König von Syrien verlassen und nicht auf Jahwe, deinen Gott! Damit hast du dich um die Möglichkeit gebracht, auch das Heer der Syrer zu besiegen." },
      { number: 8, text: "Hatten die Nubier und die Libyer nicht auch ein gewaltiges Heer mit vielen Streitwagen und Reitern? Doch weil du dich auf Jahwe verlassen hattest, gab er sie in deine Gewalt." },
      { number: 9, text: "Denn Jahwe hat die ganze Erde im Blick, damit er denen beistehen kann, die ihm uneingeschränkt vertrauen. In diesem Fall hast du töricht gehandelt, denn von jetzt an hast du ständig Krieg.\"" },
      { number: 10, text: "Asa ärgerte sich sehr über den Seher und ließ ihn ins Gefängnis werfen. Damals fing er auch an, einige aus dem Volk zu misshandeln." },
      { number: 11, text: "Asas frühere und spätere Geschichte findet man in der Chronik der Könige von Juda und Israel." },
      { number: 12, text: "Im 39. Jahr seiner Regierung erkrankte Asa schwer an den Füßen. Obwohl sein Leiden sehr ernst war, suchte er die Hilfe nicht bei Jahwe, sondern bei den Ärzten." },
      { number: 13, text: "Asa starb in seinem 41. Regierungsjahr*.", footnotes: ["41. Regspanerungsjahr. 870 v.Chr."] },
      { number: 14, text: "Man bestattete ihn in der Gruft, die er sich in der Davidsstadt hatte aushauen lassen. Dort wurde er auf ein Lager gebettet, das man mit Balsamöl, speziell zubereiteten Salben und anderen wohlriechenden Stoffen ausgestattet hatte. Auch wurde ein gewaltiges Feuer zu seiner Ehre angezündet.*", footnotes: ["Feuer ... angezündet. Das war keine Leichenverbrennung, sondern eine von den Nachbarvölkern übernommene Sitte, bei der Gewürze und Aromen, aber auch vom Herrscher benutzte Gebrauchsgegenstände verbrannt wurden. Diese Sitte hielt sich bis zu Herodes dem Großen."] },
    ] },
    { number: 17, verses: [
      { number: 1, text: "Sein Sohn Joschafat trat die Herrschaft an. Er zeigte sich stark gegenüber Israel", heading: "Joschafats Reform (17-23)\nKönig Joschafat" },
      { number: 2, text: "und stationierte Truppen in allen befestigten Städten Judas. Außerdem setzte er in ganz Juda Statthalter ein, ebenso in den Städten, die sein Vater Asa in Efraïm erobert hatte." },
      { number: 3, text: "Jahwe stand Joschafat bei, denn er folgte den früheren Wegen seines Vorfahren David. Er verehrte nicht die Baale*,", footnotes: ["Baal bedeutet \"Herr\" oder \"Gebieter\". Er wurde als Fruchtbarkeitsgott in Kanaan verehrt."] },
      { number: 4, text: "sondern hielt sich an den Gott seines Vaters und befolgte im Gegensatz zu den Israeliten Gottes Gebote." },
      { number: 5, text: "Jahwe bestätigte Joschafats Königtum, sodass ganz Juda ihm Geschenke brachte. Er wurde reich und war angesehen." },
      { number: 6, text: "Im Lauf der Zeit wurde er immer mutiger in der Nachfolge Jahwes. So ließ er in Juda die Opferhöhen und die Aschera-Pfähle wieder beseitigen." },
      { number: 7, text: "Im dritten Regierungsjahr schickte er seine Beamten Ben-Hajil, Obadja, Secharja, Netanel und Michaja zur Belehrung des Volkes in die Städte Judas." },
      { number: 8, text: "Mit ihnen gingen die Leviten Schemaja, Netanja, Sebadja, Asaël, Schemiramot, Jonatan, Adonija, Tobija und Tob-Adonija sowie die Priester Elischama und Joram." },
      { number: 9, text: "Sie hatten die Schriftrolle mit dem Gesetz Jahwes bei sich, zogen in allen Städten Judas umher und belehrten das Volk." },
      { number: 10, text: "Der Schrecken Jahwes fiel auf alle Königreiche rings um Juda, sodass niemand es wagte, gegen Joschafat zu kämpfen." },
      { number: 11, text: "Selbst von den Philistern wurden Geschenke und Silber als Tributzahlungen an Joschafat überbracht. Auch die Araber brachten ihm 7700 Schaf- und ebenso viele Ziegenböcke." },
      { number: 12, text: "So wurde Joschafat immer mächtiger. Er baute Burgen und Vorratsstädte in Juda." },
      { number: 13, text: "Auch in den übrigen Städten hatte er große Vorräte angelegt. Und in Jerusalem waren seine besten Kämpfer stationiert." },
      { number: 14, text: "Ihre Diensteinteilung richtete sich nach den Sippenverbänden. Die Truppenführer für Juda waren Adna, Oberst über 300.000 wehrtüchtige Männer," },
      { number: 15, text: "Johanan, Oberst über 280.000," },
      { number: 16, text: "und Amasja Ben-Sichri, der sich freiwillig mit 200.000 wehrtüchtigen Männern Jahwe zur Verfügung gestellt hatte." },
      { number: 17, text: "Truppenführer für Benjamin waren Eljada, ein tapferer Mann mit 200.000 Bewaffneten, die mit Bogen und Schild ausgerüstet waren," },
      { number: 18, text: "und Josabad mit 180.000 Bewaffneten." },
      { number: 19, text: "Sie alle standen im Dienst des Königs, abgesehen von den Besatzungen in den befestigten Städten Judas." },
    ] },
    { number: 18, verses: [
      { number: 1, text: "Joschafat hatte also jede Menge Reichtum und Ehre; doch ließ er seinen Sohn eine Tochter Ahabs heiraten.", heading: "Joschafats Bündnis mit Ahab" },
      { number: 2, text: "Nach einigen Jahren besuchte er Ahab in Samaria. Ahab ließ eine Menge Rinder für ihn und sein Gefolge schlachten und überredete ihn zu einem gemeinsamen Feldzug gegen Ramot* in Gilead*.", footnotes: ["Ramot war eine levitische Zufluchtsstadt, die Gad zugeteilt wurde. Das heutige Tel Ramith liegt 58 km nördlich von Amman in Jordanien.", "Gilead war die Landschaft östlich des Jordan, Wohnsitz der Stämme Ruben, Gad und halb Manasse."] },
      { number: 3, text: "König Ahab von Israel fragte also König Joschafat von Juda: \"Willst du mit mir in den Kampf gegen Ramot in Gilead ziehen?\" Der erwiderte: \"Ich ziehe mit dir, und mein Volk wird mit deinem Volk sein. Ja, ich ziehe mit in den Kampf!\"" },
      { number: 4, text: "Dann sagte Joschafat zum König von Israel: \"Du solltest aber zuerst fragen, was Jahwe dazu sagt!\"" },
      { number: 5, text: "Da ließ der König von Israel die Propheten kommen, 400 Mann. Er fragte sie: \"Sollen wir in den Kampf gegen Ramot in Gilead ziehen, oder soll ich es lassen?\" – \"Zieh hinauf\", erwiderten sie, \"Gott wird es in die Gewalt des Königs geben!\"" },
      { number: 6, text: "Aber Joschafat sagte: \"Gibt es hier sonst keinen Propheten Jahwes mehr, durch den wir Gott befragen können?\"" },
      { number: 7, text: "\"Es gibt noch einen, durch den man Jahwe fragen kann\", erwiderte der König von Israel, \"aber ich hasse ihn, weil er mir niemals Gutes, sondern immer nur Schlimmes prophezeit. Es ist Micha Ben-Jimla.\" Doch Joschafat sagte: \"Der König sage das nicht!\"" },
      { number: 8, text: "Da rief der König von Israel einen Hofbeamten herbei und befahl ihm: \"Schnell, hole Micha Ben-Jimla!\"" },
      { number: 9, text: "Der König von Israel und König Joschafat von Juda saßen im königlichen Ornat auf zwei Thronsesseln, die man für sie auf dem freien Platz am Toreingang von Samaria aufgestellt hatte. Und die Propheten weissagten vor ihnen." },
      { number: 10, text: "Ein gewisser Zidkija Ben-Kenaana hatte sich eiserne Hörner gemacht und rief: \"So spricht Jahwe: 'Damit wirst du die Syrer niederstoßen, bis du sie vernichtet hast!'\"" },
      { number: 11, text: "Die anderen Propheten weissagten ebenso. \"Greif Ramot in Gilead an und führe Israel zum Sieg! Jahwe wird die Stadt in die Hand des Königs geben!\"" },
      { number: 12, text: "Der Bote, der Micha holen sollte, sagte unterwegs zu ihm: \"Hör zu! Die Worte der Propheten sind einstimmig und sprechen für den König. Schließ dich doch ihrem Wort an und sage Gutes!\"" },
      { number: 13, text: "Micha erwiderte: \"So wahr Jahwe lebt, ich sage nur das, was mein Gott mir aufträgt!\"" },
      { number: 14, text: "Als er zum König kam, fragte ihn dieser: \"Micha, sollen wir in den Kampf gegen Ramot in Gilead ziehen, oder soll ich es lassen?\" – \"Zieh nur hin und führe Israel zum Sieg!\", sagte er. \"Sie sollen euch in die Hand gegeben werden.\"" },
      { number: 15, text: "Doch der König entgegnete: \"Wie oft muss ich dich noch beschwören, dass du mir nichts als die Wahrheit im Namen Jahwes verkündest!\"" },
      { number: 16, text: "Da sagte Micha: \"Ich sah ganz Israel über die Berge zerstreut, wie Schafe, die keinen Hirten haben. Und Jahwe sagte: 'Sie haben keinen Anführer mehr! Jeder kehre wohlbehalten in sein Haus zurück!'\"" },
      { number: 17, text: "Da sagte der König von Israel zu Joschafat: \"Habe ich dir nicht gesagt, dass er mir nichts Gutes prophezeit, sondern immer nur Schlimmes?\"" },
      { number: 18, text: "Micha fuhr fort: \"Darum hört das Wort Jahwes: Ich sah Jahwe sitzen auf seinem Thron. Das ganze Heer des Himmels stand rechts und links neben ihm." },
      { number: 19, text: "Jahwe fragte: 'Wer ködert Ahab, den König von Israel, dass er loszieht und bei Ramot in Gilead fällt?' Der eine sagte dies, der andere das." },
      { number: 20, text: "Zuletzt trat ein Geist vor. Er stellte sich vor Jahwe und sagte: 'Ich werde ihn ködern.' 'Womit?', fragte Jahwe." },
      { number: 21, text: "'Ich werde als Lügengeist aus dem Mund aller seiner Propheten sprechen', erwiderte er. 'Gut, du darfst ihn verführen', sagte er, 'und du wirst es auch schaffen. Geh los und tu es!'" },
      { number: 22, text: "Du siehst also, dass Jahwe deinen Propheten einen Lügengeist eingegeben hat, denn Jahwe hat dein Unheil beschlossen.\"" },
      { number: 23, text: "Da kam Zidkija Ben-Kenaana zu Micha, gab ihm eine Ohrfeige und sagte: \"Auf welche Weise soll der Geist Jahwes mich denn verlassen haben und nur noch mit dir reden?\"" },
      { number: 24, text: "\"Du wirst es ja sehen\", erwiderte Micha, \"und zwar an dem Tag, an dem du von einer Kammer in die andere flüchtest, um dich zu verstecken.\"" },
      { number: 25, text: "Da sagte der König: \"Nehmt ihn fest und führt ihn zum Stadtkommandanten Amon und zum Prinzen Joasch." },
      { number: 26, text: "Meldet ihnen: 'So spricht der König: Setzt diesen Mann ins Gefängnis und haltet ihn knapp bei Brot und Wasser, bis ich wohlbehalten zurückkomme!'\"" },
      { number: 27, text: "Da sagte Micha: \"Wenn du je wohlbehalten zurückkehrst, hat Jahwe nicht durch mich gesprochen.\" Dann fügte er noch hinzu: \"Hört es, ihr Völker alle!\"" },
      { number: 28, text: "Der König von Israel und König Joschafat von Juda zogen also nach Ramot in Gilead." },
      { number: 29, text: "Unterwegs sagte der König von Israel zu Joschafat: \"Ich will verkleidet in den Kampf ziehen, aber du kannst deine königliche Kleidung tragen!\" So zog er verkleidet in die Schlacht." },
      { number: 30, text: "Der König von Syrien hatte den Führern seiner Streitwagen befohlen: \"Kämpft nicht gegen Kleine oder Große, sondern greift allein den König von Israel an!\"" },
      { number: 31, text: "Als die Streitwagenführer Joschafat entdeckten, sagten sie: \"Das ist der König von Israel!\", und griffen ihn von allen Seiten an. Da schrie Joschafat, und Jahwe half ihm, indem er sie von ihm ablenkte." },
      { number: 32, text: "Als die Wagenführer nämlich merkten, dass er nicht der König von Israel war, ließen sie ihn in Ruhe." },
      { number: 33, text: "Einer ihrer Kämpfer schoss aber auf gut Glück einen Pfeil ab und traf den König von Israel zwischen Gurt und Panzer. \"Dreh um und bring mich aus der Schlacht!\", sagte der König zu seinem Wagenlenker. \"Ich bin verwundet.\"" },
      { number: 34, text: "Weil aber der Kampf an dem Tag immer heftiger wurde, hielt der König bis zum Abend durch und blieb den Syrern gegenüber in seinem Wagen aufrecht stehen. Als die Sonne unterging, starb er." },
    ] },
    { number: 19, verses: [
      { number: 1, text: "König Joschafat von Juda kehrte jedoch wohlbehalten in sein Haus nach Jerusalem zurück." },
      { number: 2, text: "Da trat ihm der Seher Jehu Ben-Hanani entgegen und sagte zu ihm: \"Musstest du dem Gottlosen helfen und die lieben, die Jahwe hassen? Deswegen ist Jahwe zornig auf dich!" },
      { number: 3, text: "Aber er hat bei dir auch etwas Gutes gefunden: Du hast die Aschera-Pfähle aus dem Land weggeschafft und dich bemüht, Gott nachzufolgen.\"" },
      { number: 4, text: "Nachdem Joschafat eine Zeit lang in Jerusalem geblieben war, bereiste er sein Land von Beerscheba bis zum Bergland von Efraïm und führte sein Volk zurück zu Jahwe, dem Gott ihrer Väter.", heading: "Joschafat sorgt für das Recht" },
      { number: 5, text: "In allen befestigten Städten Judas setzte er Richter ein" },
      { number: 6, text: "und sagte zu ihnen: \"Achtet genau auf das, was ihr tut! Denn ihr seid nicht von Menschen zum Richteramt berufen worden, sondern von Jahwe. Er wird euch beistehen, wenn ihr Recht sprecht." },
      { number: 7, text: "Lasst euch leiten von der Furcht vor Jahwe und übt euer Amt gewissenhaft aus! Denn bei Jahwe, unserem Gott, gibt es keine Ungerechtigkeit, keine Bevorzugung und keine Bestechlichkeit.\"" },
      { number: 8, text: "In Jerusalem setzte Joschafat einen obersten Gerichtshof ein, der aus Priestern, Leviten und den Sippenhäuptern Israels bestand, um im Namen Jahwes Recht zu sprechen. Gleichzeitig war er für die Rechtsstreitigkeiten der Einwohner Jerusalems zuständig." },
      { number: 9, text: "Er gab ihnen folgende Anweisung: \"Führt euer Amt in der Furcht vor Jahwe mit aller Treue und ungeteiltem Herzen!" },
      { number: 10, text: "Bei jedem Streitfall, den euch eure Brüder aus den anderen Städten vorlegen, ob es sich um Mord oder Totschlag handelt oder um Verstöße gegen Gesetze, Gebote, Bestimmungen und Anordnungen, sollt ihr sie verwarnen. Weder ihr noch sie dürfen an Jahwe schuldig werden. Sonst trifft euch sein Zorn." },
      { number: 11, text: "In allen Angelegenheiten, die Jahwe betreffen, hat der Hohe Priester Amarja den Vorsitz, in allen Angelegenheiten des Königs aber Sebadja Ben-Ismaël, der Fürst aus dem Haus Juda. Als Verwalter stehen euch die Leviten zur Verfügung. Geht mit Vertrauen ans Werk! Jahwe wird mit den Gerechten sein!\"" },
    ] },
    { number: 20, verses: [
      { number: 1, text: "Einige Zeit danach zogen die Moabiter*, die Ammoniter* und einige von den Mëunitern* zum Krieg gegen Joschafat heran.", heading: "Gott schenkt Joschafat den Sieg", footnotes: ["Die Moabiter lebten östlich des Toten Meeres zwischen den Flüssen Arnon und Zered.", "Die Ammoniter waren nordöstliche Nachbarn der Moabiter.", "Die Mëuniter lebten im Gebirge Seïr in Edom."] },
      { number: 2, text: "Man meldete dem König: \"Ein riesiges Heer ist gegen dich heraufgezogen. Sie kommen von der anderen Seite des Toten Meeres aus Edom* und stehen schon in Hazezon-Tamar.\" Das ist ein anderer Name für En-Gedi*.", footnotes: ["Edom. So mit einer Handschrift und der altlateinischen Übersetzung. Andere Handschriften lesen Aram = Syrien. Das Wort unterscheidet sich nur durch einen Buchstaben von Edom.", "En-Gedi war eine Stadt und Oase an der Westküste des Toten Meeres, 40 km südöstlich von Jerusalem."] },
      { number: 3, text: "Da erschrak Joschafat. Er beschloss, sich an Jahwe zu wenden, und ließ ein Fasten in ganz Juda ausrufen." },
      { number: 4, text: "Die Leute von Juda kamen nach Jerusalem zusammen, um die Hilfe Jahwes zu erbitten, selbst aus den Städten kamen sie herzu." },
      { number: 5, text: "Die Bevölkerung von Juda und Jerusalem versammelte sich im Haus Jahwes vor dem neuen Vorhof. Joschafat stand auf" },
      { number: 6, text: "und betete:\"Jahwe, du Gott unserer Väter! Du bist doch der Gott im Himmel, du bist doch der Herrscher über alle Reiche der Welt! In deiner Hand sind Kraft und Macht, und niemand kann vor dir bestehen!" },
      { number: 7, text: "Du, unser Gott, hast doch die früheren Bewohner dieses Landes vor deinem Volk Israel vertrieben und es den Nachkommen deines Freundes Abraham für immer gegeben!" },
      { number: 8, text: "Sie haben sich darin niedergelassen und dort ein Heiligtum für deinen Namen gebaut. Sie sagten:" },
      { number: 9, text: "'Wenn ein Unglück über uns kommt, ein Krieg als Strafgericht, die Pest oder eine Hungersnot, und wir treten vor dieses Haus und so vor dich – denn dein Name wohnt in diesem Haus – und schreien zu dir aus unserer Not, dann wirst du uns hören und helfen.'" },
      { number: 10, text: "Da stehen nun die Ammoniter und Moabiter und die vom Gebirge Seïr. Als Israel aus dem Land Ägypten kam, hast du nicht erlaubt, diese Völker anzugreifen. Israel musste ihnen ausweichen und hat sie nicht beseitigt." },
      { number: 11, text: "Zum Dank dafür kommen sie jetzt und wollen uns aus deinem Besitz vertreiben, den du uns zum Erbe gegeben hast." },
      { number: 12, text: "Unser Gott, willst du sie nicht richten? Denn in uns ist ja keine Kraft vor dieser riesigen Menge, die gegen uns marschiert. Wir wissen nicht, was wir tun sollen, und richten deshalb unsere Augen auf dich!\"" },
      { number: 13, text: "So standen die Judäer mit ihren Frauen und Kindern vor Jahwe." },
      { number: 14, text: "Da kam der Geist Jahwes auf Jachasiel Ben-Secharja, den Enkel Benajas, der wiederum ein Sohn von Jehiël Ben-Mattanja war. Er war ein Levit aus der Sippe Asafs und stand mitten in der Versammlung." },
      { number: 15, text: "Er rief: \"Hört her, ihr Judäer, ihr Einwohner von Jerusalem und du, König Joschafat! So spricht Jahwe zu euch: 'Habt keine Angst und erschreckt nicht vor dieser großen Masse! Denn das wird nicht euer Kampf sein, sondern es ist Gottes Sache!" },
      { number: 16, text: "Zieht ihnen morgen entgegen! Passt auf, sie werden die Steigung von Ziz* heraufkommen. Am Ausgang des Tals vor der Wüste Jeruël* werdet ihr sie finden.", footnotes: ["Ziz. Es handelt sich vielleicht um das Wadi Hasasa, das 14 km südöstlich von Tekoa, nördlich von En-Gedi ins Tote Meer mündete.", "Jeruël. Wüstenlandschaft südöstlich von Tekoa. Tekoa liegt im Hügelland Judas, nur 16 km südlich von Jerusalem."] },
      { number: 17, text: "Doch ihr müsst nicht kämpfen, Juda und Jerusalem. Stellt euch auf, tretet vor und schaut euch an, wie Jahwe euch rettet. Habt keine Angst und erschreckt nicht! Zieht ihnen morgen entgegen, und Jahwe wird bei euch sein!'\"" },
      { number: 18, text: "Da beugte sich Joschafat nieder mit dem Gesicht bis zur Erde. Auch das ganze Volk von Juda und die Bewohner Jerusalems warfen sich vor Jahwe nieder und beteten ihn an." },
      { number: 19, text: "Danach standen die Leviten von der Sippe der Kehatiter und Korachiter auf und priesen Jahwe, den Gott Israels, mit mächtiger Stimme." },
      { number: 20, text: "Früh am nächsten Morgen brachen sie zur Wüste Tekoa auf. Bei ihrem Auszug trat Joschafat vor und rief: \"Hört zu, ihr Judäer und ihr Jerusalemer! Glaubt an Jahwe, euren Gott, dann werdet ihr bestehen! Glaubt seinen Propheten, dann habt ihr Gelingen!\"" },
      { number: 21, text: "Nachdem er sich mit dem Volk beraten hatte, stellte er Sänger für Jahwe an die Spitze der Gerüsteten. Sie sangen in ihren heiligen Gewändern Loblieder. \"Preist Jahwe, denn seine Güte hört niemals auf!\"" },
      { number: 22, text: "Und zu derselben Zeit, als sie mit dem Jubel und Lobgesang anfingen, legte Jahwe einen Hinterhalt gegen die nach Juda anrückenden Ammoniter, Moabiter und die vom Gebirge Seïr, was zu ihrer Vernichtung führte." },
      { number: 23, text: "Denn die Ammoniter und Moabiter kämpften auf einmal gegen die Bewohner vom Gebirge Seïr. Als sie diese vollständig vernichtet hatten, fielen sie übereinander her und brachten sich gegenseitig um." },
      { number: 24, text: "Als nun die Judäer an die Stelle kamen, von wo aus man die Wüste überblicken kann, und sich nach dem Heerhaufen umschauten, sahen sie nur noch Leichen auf dem Boden liegen. Niemand war davongekommen." },
      { number: 25, text: "Joschafat und seine Leute sammelten die Beute ein. Sie fanden bei den Gefallenen eine Menge Dinge, auch kostbare Gegenstände. Sie plünderten so viel für sich, dass sie es nicht mehr tragen konnten. Drei Tage brauchten sie, um die riesige Beute einzusammeln." },
      { number: 26, text: "Am vierten Tag versammelten sie sich im Beracha-Tal*, um Jahwe zu preisen. Daher bekam es seinen Namen \"Lobpreistal\"; so heißt es heute noch.", footnotes: ["Beracha heißt Segen oder Lobpreis."] },
      { number: 27, text: "Schließlich kehrte die ganze Mannschaft von Juda und Jerusalem mit Joschafat an der Spitze wieder nach Jerusalem zurück. Sie waren voller Freude, denn Jahwe hatte ihnen Freude an ihren Feinden geschenkt." },
      { number: 28, text: "So zogen sie mit Harfen, Zithern und Trompeten in Jerusalem ein bis vor den Tempel." },
      { number: 29, text: "Der Schrecken Gottes fiel auf die umliegenden Königreiche, als sie hörten, dass Jahwe mit den Feinden Israels gekämpft hatte." },
      { number: 30, text: "Von da an konnte Joschafat in Ruhe regieren, Gott schaffte ihm Ruhe an allen Grenzen." },
      { number: 31, text: "Joschafat war also König von Juda. Als er an die Herrschaft kam, war er 35 Jahre alt. Er regierte 25 Jahre in Jerusalem. Seine Mutter hieß Asuba und war eine Tochter von Schilhi.", heading: "Das Ende der Regierung Joschafats" },
      { number: 32, text: "Er folgte konsequent dem Beispiel seines Vaters Asa, indem er tat, was Jahwe gefiel." },
      { number: 33, text: "Nur die Opferhöhen bestanden weiter, denn das Volk war noch nicht von Herzen auf den Gott seiner Väter ausgerichtet." },
      { number: 34, text: "Was sonst noch über Joschafat zu sagen ist, seine frühere und spätere Geschichte, findet man in der Chronik von Jehu Ben-Hanani, die ins Buch der Könige von Israel aufgenommen wurde." },
      { number: 35, text: "Einmal schloss König Joschafat von Juda eine Übereinkunft mit König Ahasja von Israel, der ein verwerfliches Leben führte." },
      { number: 36, text: "Sie beschlossen, in Ezjon-Geber* gemeinsam Schiffe zu bauen, die nach Tarschisch fahren sollten.", footnotes: ["Ezjon-Geber. Hafenstadt am Golf von Elat/Akaba, in der Nähe des heutigen Elat."] },
      { number: 37, text: "Da sagte Eliëser Ben-Dodawa aus Marescha ein Prophetenwort gegen Joschafat: \"Weil du dich mit Ahasja verbündet hast, wird Jahwe dein Werk zerstören.\" Die Flotte erlitt wirklich Schiffbruch und kam nie in Tarschisch an." },
    ] },
    { number: 21, verses: [
      { number: 1, text: "Als Joschafat starb, bestattete man ihn neben seinen Vorfahren in der Davidsstadt, und sein Sohn Joram trat die Herrschaft an.", heading: "König Joram von Juda" },
      { number: 2, text: "Seine Brüder hießen Asarja, Jehiël, Secharja, Asarjahu, Michael und Schefatja. Sie alle waren Söhne des Königs Joschafat von Israel*.", footnotes: ["Israel ist hier im allgemeinen Sinn gebraucht und nicht auf das Nordreich bezogen, ebenso in V. 4."] },
      { number: 3, text: "Ihr Vater hatte ihnen großzügige Geschenke gemacht: Gold, Silber und andere Kostbarkeiten. Außerdem gab er ihnen befestigte Städte in Juda. Aber das Königtum gab er Joram, weil er der Erstgeborene war." },
      { number: 4, text: "Als Joram das Reich seines Vaters übernommen und die Herrschaft fest in der Hand hatte, ließ er alle seine Brüder und auch einige führende Männer Israels mit dem Schwert hinrichten." },
      { number: 5, text: "Joram war 32 Jahre alt, als er die Herrschaft antrat. Er regierte acht Jahre in Jerusalem" },
      { number: 6, text: "und tat, was Jahwe missfiel. Wie die Familie Ahabs folgte er dem bösen Beispiel der Könige von Israel und tat, was Jahwe verabscheute. Seine Frau war nämlich eine Tochter Ahabs." },
      { number: 7, text: "Doch Jahwe wollte das Haus Davids nicht zugrunde richten, weil er einen Bund mit David geschlossen und ihm den Fortbestand seines Königtums zugesagt hatte." },
      { number: 8, text: "Während Jorams Regierungszeit lösten sich die Edomiter von der Herrschaft Judas und setzten einen eigenen König ein." },
      { number: 9, text: "Daher zog Joram mit seinen Truppenführern und Streitwagen gegen sie. Doch die Edomiter schlossen ihn und die Offiziere seiner Streitwagen ein. Da schlug Joram in der Nacht los und durchbrach den Ring." },
      { number: 10, text: "Damals sagte sich Edom von Judas Herrschaft los. So ist es noch bis heute. Auch die Stadt Libna sagte sich von Judas Herrschaft los. Der Grund war, dass Joram Jahwe, den Gott seiner Väter, verlassen hatte." },
      { number: 11, text: "Joram richtete sogar Opferhöhen auf den Bergen Judas ein. Er verführte die Jerusalemer zu unsittlichen Götzendiensten und die Judäer zur Untreue gegenüber Gott." },
      { number: 12, text: "Damals erhielt er ein Schreiben des Propheten Elija, das lautete: \"So spricht Jahwe, der Gott deines Vorvaters David: Du bist nicht den Weg deines Vaters Joschafat und deines Großvaters Asa gegangen," },
      { number: 13, text: "sondern bist dem bösen Beispiel der Könige von Israel gefolgt. Du hast die Judäer und die Jerusalemer nach dem unmoralischen Beispiel des Hauses Ahab zu unsittlichen Götzendiensten verführt und hast deine eigenen Brüder umgebracht, die besser waren als du." },
      { number: 14, text: "Darum wird Jahwe dein Volk, deine Söhne, deine Frauen und all deinen Besitz mit schweren Plagen strafen." },
      { number: 15, text: "Du selbst wirst eine qualvolle Krankheit in deinen Eingeweiden bekommen, die im Verlauf der Krankheit aus dir heraustreten werden.\"" },
      { number: 16, text: "Jahwe gab es den Philistern und den Arabern, die neben den Nubiern wohnen, in den Sinn, Joram anzugreifen." },
      { number: 17, text: "Sie zogen gegen Juda heran, drangen in das Land ein und schleppten alles Hab und Gut weg, das sich im Königspalast befand, dazu auch Jorams Söhne und Frauen. Nur sein jüngster Sohn Joahas blieb ihm." },
      { number: 18, text: "Nach all dem ließ Jahwe eine unheilbare Krankheit in seinen Eingeweiden entstehen," },
      { number: 19, text: "die sich lange hinzog. Nach zwei Jahren traten die Eingeweide aus ihm heraus, und er starb unter furchtbaren Schmerzen. Das Volk zündete kein Feuer zu seiner Ehre an, wie es bei seinen Vätern geschehen war." },
      { number: 20, text: "Er war mit 32 Jahren König geworden und hatte acht Jahre in Jerusalem regiert. Er starb, ohne bedauert zu werden. Man bestattete ihn zwar in der Davidsstadt, aber nicht in den Grüften der Könige." },
    ] },
    { number: 22, verses: [
      { number: 1, text: "Die Einwohner von Jerusalem riefen Jorams jüngsten Sohn Ahasja* zum König aus. Denn alle älteren Söhne hatte die Räuberhorde umgebracht, die mit den Arabern ins Heerlager Judas eingedrungen war. So wurde also Ahasja, der Sohn des Königs Joram von Juda, König.", heading: "König Ahasja von Juda", footnotes: ["Ahasja ist eine andere Form des Namens Joahas."] },
      { number: 2, text: "Ahasja war bei Herrschaftsantritt 22 Jahre* alt und regierte ein Jahr in Jerusalem. Seine Mutter war Atalja, die Enkeltochter Omris.", footnotes: ["22 Jahre. So mit 2. Könige 8,26. Der uns vorliegende hebräische Text hat hier, wahrscheinlich durch einen Abschreibefehler verursacht, 42 Jahre."] },
      { number: 3, text: "Auch er folgte dem schlechten Beispiel des Hauses Ahab, denn seine Mutter beeinflusste ihn zu gottlosem Handeln." },
      { number: 4, text: "Wie das Haus Ahabs tat er, was Jahwe missfiel, denn von dort kamen seine Berater nach dem Tod seines Vaters. Das führte zu seinem Untergang." },
      { number: 5, text: "Er folgte ihrem Rat und zog mit König Joram Ben-Ahab von Israel in den Krieg gegen König Hasaël von Syrien. Bei Ramot in Gilead kam es zum Kampf. Dabei wurde Joram von den Syrern verwundet." },
      { number: 6, text: "Da zog er sich nach Jesreel* zurück, um seine Wunden dort ausheilen zu lassen. König Ahasja Ben-Joram von Juda besuchte ihn in Jesreel.", footnotes: ["Jesreel. Stadt zwischen Bet-Schean und Megiddo in der Jesreel-Ebene."] },
      { number: 7, text: "Aber Gott hatte es so gefügt, dass dieser Besuch für Ahasja zum Verhängnis wurde. Denn als er dort angekommen war, fuhr er mit Joram zusammen Jehu, dem Enkel von Nimschi, entgegen. Dieser war von Jahwe zum König gesalbt worden, um die Nachkommen Ahabs auszurotten." },
      { number: 8, text: "Als Jehu das Gericht über die Nachkommen Ahabs vollstreckte, traf er die Obersten von Juda und die Neffen Ahasjas, die in dessen Dienst standen, und brachte sie um." },
      { number: 9, text: "Dann ließ er Ahasja, der sich in Samaria versteckt hielt, suchen und gefangen nehmen. Er wurde zu Jehu gebracht und getötet. Doch ihm gewährte man ein Begräbnis, denn man sagte: \"Er war immerhin ein Enkel Joschafats, der Jahwe von ganzem Herzen folgte.\" In der Familie Ahasjas war nun keiner mehr übrig, der fähig war, die Königsherrschaft zu übernehmen." },
      { number: 10, text: "Als Atalja, die Mutter von Ahasja erfuhr, dass ihr Sohn tot war, ließ sie die ganze Nachkommenschaft des Königshauses von Juda umbringen.", heading: "Ataljas Herrschaft" },
      { number: 11, text: "Doch Joscheba, die Frau des Priesters Jojada – sie war König Jorams Tochter und Ahasjas Schwester –, schaffte dessen kleinen Sohn Joasch von den Prinzen, die getötet werden sollten, heimlich beiseite. Sie versteckte ihn und seine Amme in der Bettenkammer und brachte ihn vor Atalja in Sicherheit, sodass er nicht getötet wurde." },
      { number: 12, text: "Sechs Jahre lang blieb er im Bereich des Tempels verborgen, während Atalja das Land regierte." },
    ] },
    { number: 23, verses: [
      { number: 1, text: "Im siebten Jahr fasste Jojada einen mutigen Entschluss. Er verbündete sich mit den Hauptleuten Asarja Ben-Jeroham, Jischmaël Ben-Johanan, Asarja Ben-Obed, Maaseja Ben-Adaja und Elischafat Ben-Sichri.", heading: "Ataljas Sturz und Tod" },
      { number: 2, text: "Sie zogen durch alle Städte Judas und brachten die Leviten und Familienoberhäupter von Israel in Jerusalem zusammen." },
      { number: 3, text: "Dort, im Haus Gottes, schloss die ganze Versammlung einen Bund mit dem König. Jojada sagte zu ihnen:\"Seht hier den Sohn des Königs! Er soll König sein, wie Jahwe es den Nachkommen Davids zugesagt hat." },
      { number: 4, text: "Wir sollten jetzt Folgendes tun: Ein Drittel der Priester und Leviten, die am nächsten Sabbat ihren Dienst antreten, bewachen die Eingänge des Tempels," },
      { number: 5, text: "das zweite Drittel den Königspalast und das letzte Drittel das Grundtor. Alles Volk soll sich in den Vorhöfen vom Haus Jahwes aufhalten." },
      { number: 6, text: "Außer den Priestern und den diensttuenden Leviten soll niemand ins Haus Jahwes hineingehen. Nur sie sind von Gott dazu bestimmt. Und alles Volk soll sich an die Vorschriften Jahwes halten." },
      { number: 7, text: "Die Leviten sollen mit der Waffe in der Hand den König umgeben und jeden töten, der ins Haus hinein will. Auf Schritt und Tritt müsst ihr den König beschützen.\"" },
      { number: 8, text: "Die Leviten und alle Judäer befolgten die Anweisungen des Priesters Jojada. Jeder rief seine Männer zusammen, und zwar die, die am Sabbat ihren Dienst antraten, und die, die ihn beendeten. Denn der Priester Jojada hatte die Abteilungen nicht entlassen." },
      { number: 9, text: "Dann gab Jojada den Offizieren die Speere, Schilde und Rundschilde, die noch von König David stammten und im Haus Gottes aufbewahrt wurden." },
      { number: 10, text: "Daraufhin stellten sich die Leibwächter auf, jeder mit seiner Waffe in der Hand. Sie bildeten eine Kette von der Südseite des Tempelhauses am Altar und dem Tempelhaus vorbei bis zu seiner Nordseite, um den König nach allen Seiten abzusichern." },
      { number: 11, text: "Dann führte man den Prinzen heraus. Man setzte ihm die Krone auf, überreichte ihm die Urkunde und machte ihn so zum König. Jojada und seine Söhne salbten ihn und riefen: \"Es lebe der König!\"" },
      { number: 12, text: "Als Atalja die Jubelrufe des herbeilaufenden Volkes hörte, kam auch sie zum Haus Jahwes." },
      { number: 13, text: "Da sah sie den König auf der obersten Stufe des Tempeleingangs stehen, umgeben von den Offizieren und Trompetern. Das Volk jubelte vor Freude, und die Trompeten schmetterten. Auch die Tempelsänger standen mit ihren Instrumenten dort und leiteten den Lobgesang. Da riss Atalja ihr Obergewand ein* und schrie: \"Verrat! Verschwörung!\"", footnotes: ["riss ... ein. Als Zeichen von Trauer und Entsetzen riss man das Kleidungsstück vom Halsausschnitt an mit einem heftigen Ruck etwa eine Handlänge ein."] },
      { number: 14, text: "Doch Jojada ließ die Offiziere, die das Kommando über die Truppen hatten, vortreten und sagte zu ihnen: \"Führt sie durch die Reihen eurer Leute hinaus. Wer ihr folgt, den tötet mit dem Schwert!\" Er wollte nämlich nicht, dass man sie im Haus Jahwes umbrachte." },
      { number: 15, text: "Da packten sie Atalja und brachten sie zum Eingang des Rosstores am königlichen Palast. Dort wurde sie getötet." },
      { number: 16, text: "Jojada schloss einen Bund zwischen sich, dem Volk und dem König. Sie verpflichteten sich, das Volk Jahwes zu sein." },
      { number: 17, text: "Dann zog das ganze Volk zum Baalstempel und riss ihn nieder. Sie zertrümmerten seine Altäre und Götzenbilder und erschlugen den Baalspriester Mattan dort vor den Altären." },
      { number: 18, text: "Dann übertrug Jojada den Priestern und Leviten die Aufsicht über das Haus Jahwes. David hatte sie in Dienstgruppen eingeteilt, damit sie Jahwe die Brandopfer unter Freudengesängen und Liedern darbringen konnten, wie es im Gesetz Moses vorgeschrieben ist." },
      { number: 19, text: "Er stellte auch Wachen an die Tore des Hauses Jahwes, damit niemand den Tempel betrat, der irgendwie mit einer Unreinheit behaftet war." },
      { number: 20, text: "Nun rief er die Offiziere, die Vornehmen und Großen des Volkes und das ganze Volk zusammen. Dann geleiteten sie den König aus dem Haus Jahwes durch das obere Tor in den Königspalast. Dort nahm er auf dem Königsthron Platz." },
      { number: 21, text: "Das ganze Volk freute sich, und die Stadt blieb ruhig, obwohl Atalja mit dem Schwert getötet worden war." },
    ] },
    { number: 24, verses: [
      { number: 1, text: "Joasch war bei Herrschaftsantritt sieben Jahre alt und regierte 40 Jahre lang in Jerusalem. Seine Mutter hieß Zibja und stammte aus Beerscheba.", heading: "Joaschs Reform (24-28)\nKönig Joasch von Juda" },
      { number: 2, text: "Solange der Priester Jojada lebte, tat Joasch, was Jahwe gefiel." },
      { number: 3, text: "Er heiratete die zwei Frauen, die Jojada für ihn ausgewählt hatte, und zeugte Söhne und Töchter mit ihnen." },
      { number: 4, text: "Einige Zeit später lag es Joasch am Herzen, das Haus Jahwes zu erneuern." },
      { number: 5, text: "Er rief die Priester und Leviten zusammen und sagte zu ihnen: \"Geht in die Städte Judas und sammelt von ganz Israel Geld ein, damit ihr jedes Jahr die nötigen Reparaturen am Haus Gottes durchführen könnt. Beeilt euch damit!\" Aber die Leviten ließen sich Zeit." },
      { number: 6, text: "Da ließ der König den Oberpriester Jojada rufen und sagte zu ihm: \"Warum hast du nicht dafür gesorgt, dass die Leviten die Abgabe einsammeln, die schon Jahwes Diener Mose den Israeliten für das Zelt mit dem Bundesgesetz auferlegt hat?" },
      { number: 7, text: "Denn die gottlose Atalja und ihre Anhänger haben das Haus Gottes verkommen lassen und haben selbst die heiligen Gaben, die für das Haus Jahwes bestimmt waren, für den Baalskult verwendet.\"" },
      { number: 8, text: "Der König ließ nun einen Kasten anfertigen und am Außentor des Hauses Jahwes aufstellen." },
      { number: 9, text: "Dann wurde in Juda und Jerusalem bekannt gegeben, dass jeder die Abgabe beisteuern sollte, die Mose, der Diener Gottes, den Israeliten in der Wüste auferlegt hatte." },
      { number: 10, text: "Alle führenden Männer und auch das Volk freuten sich darüber. Sie brachten ihre Gaben und warfen sie in den Kasten, bis er voll war." },
      { number: 11, text: "In bestimmten Abständen ließ man den Kasten durch die Leviten zur Verwaltung des Königs bringen. Wenn man sah, dass viel Geld im Kasten war, kamen der Schreiber des Königs und der Beauftragte des Oberpriesters. Sie leerten den Kasten gemeinsam aus und brachten ihn dann an seinen Platz zurück. So machte man es jeden Tag. Auf diese Weise kam viel Geld zusammen." },
      { number: 12, text: "Der König und Jojada übergaben das Geld den Handwerksmeistern, die für die Bauarbeiten am Tempel verantwortlich waren. Diese stellten Steinmetze und Zimmerleute ein, sowie Handwerker, die mit Eisen und Bronze umgehen konnten. Sie sollten das Haus Jahwes ausbessern." },
      { number: 13, text: "Die Meister gingen ans Werk, und die Arbeit machte gute Fortschritte. Sie stellten das Haus Gottes nach seinen ursprünglichen Maßen wieder her und machten es stabil." },
      { number: 14, text: "Als sie fertig waren, brachten sie den Rest des Geldes dem König und Jojada zurück. Jojada ließ davon Geräte für das Haus Jahwes anfertigen, die für den Dienst und die Brandopfer gebraucht wurden: Schalen sowie goldene und silberne Gegenstände.Solange Jojada lebte, wurden die Brandopfer im Haus Jahwes regelmäßig dargebracht." },
      { number: 15, text: "Jojada wurde sehr alt. Er starb nach einem erfüllten Leben mit 130 Jahren." },
      { number: 16, text: "Man begrub ihn in der Davidsstadt neben den Königen, denn er hatte für Gott und sein Haus viel Gutes in Israel bewirkt." },
      { number: 17, text: "Nach dem Tod Jojadas kamen die führenden Männer Judas zum König und warfen sich vor ihm nieder. Und der König hörte auf sie." },
      { number: 18, text: "Da gingen sie nicht mehr in das Haus Jahwes. Sie verließen den Gott ihrer Väter und verehrten stattdessen geweihte Pfähle und Götzenbilder. Wegen dieser Schuld kam Gottes Zorn über Juda und Jerusalem." },
      { number: 19, text: "Jahwe schickte Propheten zu ihnen, um sein Volk zurückzugewinnen. Die Propheten warnten sie, aber niemand hörte darauf." },
      { number: 20, text: "So kam der Geist Gottes über Secharja Ben-Jojada, den Sohn des Priesters. Er trat vor das Volk und sagte: \"So spricht Gott: 'Warum übertretet ihr die Gebote Jahwes und bringt euch selbst um euer Glück?' Weil ihr Jahwe verlassen habt, hat er auch euch verlassen.\"" },
      { number: 21, text: "Darauf taten sie sich gegen ihn zusammen und steinigten ihn auf Befehl des Königs im Vorhof des Hauses Jahwes." },
      { number: 22, text: "König Joasch dachte nicht mehr daran, wie viel er dessen Vater Jojada zu verdanken hatte, und brachte den Sohn um. Im Sterben rief Secharja noch: \"Jahwe sieht es und wird es vergelten!\"" },
      { number: 23, text: "Um die Jahreswende rückte eine Heeresgruppe der Syrer gegen Joasch heran. Sie drangen in Juda und Jerusalem ein, brachten alle führenden Männer um und schickten die gesamte Beute, die sie bei ihnen gemacht hatten, zum König nach Damaskus." },
      { number: 24, text: "Obwohl die Syrer nur mit wenigen Männern gekommen waren, gab Jahwe ein viel größeres Heer in ihre Gewalt, weil die Judäer Jahwe, den Gott ihrer Väter, verlassen hatten. So vollzogen die Syrer Gottes Strafgericht an Joasch." },
      { number: 25, text: "Als sie abzogen, ließen sie Joasch schwer verwundet zurück. Da verschworen sich einige seiner Hofbeamten wegen des Mordes am Sohn des Priesters Jojada und erschlugen Joasch auf seinem Krankenbett. Er wurde in der Davidsstadt begraben, aber nicht in den Königsgräbern." },
      { number: 26, text: "Die Verschwörer waren Sabat, ein Sohn der Ammoniterin Schimat, und Josabad, ein Sohn der Moabiterin Schimrit." },
      { number: 27, text: "Was seine Söhne betrifft und die vielen auf ihm lastenden Prophetenworte und die Beschreibung der grundlegenden Instandsetzung des Hauses Gottes, findet man in den Erläuterungen zum Buch der Könige. Sein Sohn Amazja trat die Herrschaft an." },
    ] },
    { number: 25, verses: [
      { number: 1, text: "Amazja war bei Herrschaftsantritt 25 Jahre alt und regierte 29 Jahre lang in Jerusalem. Seine Mutter hieß Joaddan und stammte aus Jerusalem.", heading: "König Amazja von Juda" },
      { number: 2, text: "Er tat, was Jahwe gefiel, wenn auch nicht mit ungeteiltem Herzen." },
      { number: 3, text: "Sobald er die Herrschaft fest in der Hand hatte, ließ er die Hofbeamten töten, die seinen Vater Joasch umgebracht hatten." },
      { number: 4, text: "Doch ihre Söhne verschonte er, wie es im Gesetzbuch von Mose geschrieben steht, wo Jahwe geboten hat: \"Die Väter sollen nicht für ihre Söhne und die Söhne nicht für ihre Väter mit dem Tod bestraft werden, sondern jeder soll nur für sein eigenes Verbrechen sterben.\"*", footnotes: ["5. Mose 24,16."] },
      { number: 5, text: "Amazja ließ die Männer aus Juda und Benjamin zusammenrufen, ordnete sie nach Sippenverbänden und unterstellte sie Befehlshabern und Hauptleuten. Dann ließ er alle Männer ab 20 Jahre mustern und fand heraus, dass er über ein Heer von 300.000 Wehrtüchtigen verfügte, die mit Spieß und Langschild bewaffnet waren." },
      { number: 6, text: "Zusätzlich ließ er aus Israel 100.000 Männer für dreieinhalb Tonnen* Silberstücke anwerben.", footnotes: ["dreieinhalb Tonnen. Wörtlich: 100 Talente."] },
      { number: 7, text: "Da kam ein Mann Gottes zu ihm und sagte: \"Mein König, lass die Soldaten aus Israel nicht mit dir ziehen! Denn Jahwe ist nicht mit Israel, mit all diesen Leuten aus Efraïm." },
      { number: 8, text: "Sondern zieh du nur entschlossen in den Kampf! Gott wird dich sonst vor dem Feind zu Fall bringen. Denn Gott hat die Macht, dir zu helfen oder dich zu Fall zu bringen.\"" },
      { number: 9, text: "\"Und was wird aus dem ganzen Silber, das ich den Söldnern aus Israel bezahlt habe?\", fragte Amazja den Mann Gottes. \"Jahwe hat genug, um dir mehr als das zu geben\", erwiderte dieser." },
      { number: 10, text: "Da entließ Amazja die Söldner, die aus Efraïm zu ihm gekommen waren, und schickte sie nach Hause. Diese wurden sehr zornig über Juda und kehrten wütend zurück." },
      { number: 11, text: "Amazja fasste Mut und führte sein Volk in den Kampf. Sie zogen ins Salztal und erschlugen 10.000 Männer von Seïr." },
      { number: 12, text: "Weitere 10.000 nahmen sie gefangen. Die Männer von Juda führten die Gefangenen auf die Höhe der Stadt Sela und stürzten sie von dort hinab, sodass alle zerschmettert wurden." },
      { number: 13, text: "Inzwischen überfielen die Söldner, die Amazja nicht mitkämpfen ließ, sondern zurückgeschickt hatte, die Städte zwischen Samaria und Bet-Horon, die Juda gehörten. Sie töteten dabei 3000 Männer und machten große Beute." },
      { number: 14, text: "Nach seiner Rückkehr vom Sieg über die Edomiter stellte Amazja die Götter aus Seïr, die er mitgebracht hatte, für sich als Götter auf. Er warf sich vor ihnen nieder und verbrannte ihnen Weihrauch." },
      { number: 15, text: "Da entflammte Jahwes Zorn gegen ihn. Er schickte einen Propheten und ließ Amazja sagen: \"Warum suchst du Hilfe bei den Göttern dieses Volkes, die nicht einmal ihr eigenes Volk vor dir beschützen konnten?\"" },
      { number: 16, text: "Aber Amazja ließ ihn nicht ausreden und rief: \"Haben wir dich etwa zum Ratgeber des Königs gemacht? Lass das, wenn du keine Schläge bekommen willst!\" Da unterbrach der Prophet seine Botschaft, sagte aber noch: \"Ich weiß, dass Gott deinen Untergang beschlossen hat, weil du die Götzen angebetet und nicht auf meinen Rat gehört hast.\"" },
      { number: 17, text: "Dann entschloss sich König Amazja von Juda, König Joasch Ben-Joahas von Israel, den Enkel Jehus, herauszufordern. \"Komm, wir wollen unsere Kräfte messen!\", ließ er ihm ausrichten." },
      { number: 18, text: "Doch König Joasch von Israel ließ ihm sagen: \"Der Dornstrauch auf dem Libanon sagte zur Zeder: 'Gib meinem Sohn deine Tochter zur Frau!' Aber die wilden Tiere auf dem Libanon liefen über den Dornstrauch und zertrampelten ihn." },
      { number: 19, text: "Ist dir der Sieg über die Edomiter zu Kopf gestiegen? Genieße deinen Ruhm und bleib zu Hause! Warum willst du dich ins Unglück stürzen und reißt ganz Juda mit hinein?\"" },
      { number: 20, text: "Doch Amazja wollte nicht hören. Gott hatte es so gefügt, denn er wollte sie ausliefern, weil sie Hilfe bei den Göttern der Edomiter gesucht hatten." },
      { number: 21, text: "Da zog König Joasch von Israel mit einem Heer nach Juda. Bei Bet-Schemesch*, das zu Juda gehört, kam es zur Schlacht zwischen ihm und König Amazja von Juda.", footnotes: ["Bet-Schemesch liegt 24 km westlich von Jerusalem in der Nähe der Grenze zwischen Juda und Dan, siehe Josua 15,10."] },
      { number: 22, text: "Die Männer Judas wurden von den Israeliten besiegt und flüchteten nach Hause." },
      { number: 23, text: "König Joasch von Israel nahm König Amazja Ben-Joasch von Juda, den Enkel des Joahas, bei Bet-Schemesch gefangen und nahm ihn mit nach Jerusalem. Dort ließ er die Stadtmauer auf einer Länge von 200 Metern zwischen dem Ephraïmtor und dem Ecktor niederreißen." },
      { number: 24, text: "Er räumte alles Gold und Silber und alle kostbaren Gegenstände aus dem Haus Gottes aus, die sich unter der Obhut von Obed-Edom befanden, dazu alles, was sich in den Schatzkammern des Palastes befand. Außerdem nahm er eine Anzahl von Geiseln nach Samaria mit." },
      { number: 25, text: "König Amazja Ben-Joasch von Juda überlebte König Joasch von Israel 15 Jahre." },
      { number: 26, text: "Was sonst noch über Amazja zu sagen ist, seine frühere und spätere Geschichte, findet man im Buch der Könige von Juda und Israel." },
      { number: 27, text: "Von der Zeit an, als Amazja von der Nachfolge Jahwes abgewichen war, kam es in Jerusalem zu einer Verschwörung gegen ihn. Da floh er nach Lachisch. Aber die Verschwörer ließen ihn bis dorthin verfolgen und umbringen." },
      { number: 28, text: "Man brachte ihn auf Pferden in die Hauptstadt Judas zurück und bestattete ihn in der Grabstätte seiner Vorfahren." },
    ] },
    { number: 26, verses: [
      { number: 1, text: "Das ganze Volk Judas hatte Usija* Ben-Amazja schon mit 16 Jahren zum König gemacht*. Er trat nun die Nachfolge seines Vaters an.", heading: "König Usija von Juda", footnotes: ["Usija. In 2. Könige 15 wird er Asarja genannt. Wahrscheinlich war Asarja sein persönlicher Name und Usija sein Thronname.", "zum König gemacht. Das geschah bereits 24 Jahre vor dem Tod Amazjas. Entweder war Asarja seitdem Mitregent oder sogar Gegenkönig."] },
      { number: 2, text: "Nach dessen Tod eroberte Usija die Stadt Elat für Juda zurück und baute sie wieder auf." },
      { number: 3, text: "Usija war 16 Jahre alt, als er Mitregent wurde, und regierte insgesamt 52 Jahre lang in Jerusalem. Seine Mutter hieß Jecholja und stammte aus Jerusalem." },
      { number: 4, text: "Wie sein Vater Amazja tat auch er, was Jahwe gefiel." },
      { number: 5, text: "Solange Secharja lebte, der ihn zur Gottesfurcht anhielt, folgte er Gott. Und solange er Jahwe suchte, gab Gott ihm Gelingen." },
      { number: 6, text: "Er unternahm einen Feldzug gegen die Philister und riss die Mauern von Gat, Jabne und Aschdod nieder. Andere Städte im Gebiet von Aschdod und im Philisterland baute er zu Festungen aus." },
      { number: 7, text: "Gott stand ihm bei im Kampf gegen die Philister, gegen die Araber von Gur-Baal und gegen die Mëuniter." },
      { number: 8, text: "Auch die Ammoniter zahlten Usija Tribut. Er wurde so mächtig, dass sein Name selbst in Ägypten bekannt wurde." },
      { number: 9, text: "In Jerusalem baute Usija Türme am Ecktor, am Taltor und am Winkel und befestigte sie stark." },
      { number: 10, text: "Auch in der Steppe ließ er Türme bauen und Zisternen graben, weil er in der Schefela* und der Hochebene große Viehherden besaß und in der fruchtbaren Niederung Bauern und Weingärtner beschäftigte. Er hatte nämlich viel für die Landwirtschaft übrig.", footnotes: ["Schefela. Niedriges, sehr fruchtbares Hügelland, das sich in nordsüdlicher Richtung zwischen dem Gebirge und der Küstenebene des Mittelmeeres erstreckt."] },
      { number: 11, text: "Usija hatte ein wehrfähiges Heer, das nach Abteilungen gegliedert war. Es rückte in der Stärke aus, die der Staatsschreiber Jëiël und der Verwalter Maaseja unter der Aufsicht von Hananja, einem der obersten königlichen Beamten, bei der Musterung erfasst hatten." },
      { number: 12, text: "Die Gesamtzahl der Familienoberhäupter der Wehrtüchtigen war 2 600." },
      { number: 13, text: "Sie befehligten ein Heer von 307 500 Mann, stark und schlagkräftig genug, dass der König es mit jedem Feind aufnehmen konnte." },
      { number: 14, text: "Usija rüstete sein Heer mit Schilden, Spießen, Helmen, Brustpanzern, Bogen und Schleudersteinen aus." },
      { number: 15, text: "Er ließ in Jerusalem auch raffinierte Wurfmaschinen bauen, mit denen man Pfeile abschießen und große Steine schleudern konnte. Sie sollten auf Türmen und Eckzinnen aufgestellt werden. Sein Ruhm drang bis in die Ferne, denn er empfing außergewöhnliche Hilfe. So wurde er immer mächtiger." },
      { number: 16, text: "Doch die Macht stieg ihm zu Kopf. Er wurde überheblich und verging sich an Jahwe, seinem Gott, indem er in den Tempel Jahwes eindrang, um Weihrauch auf dem Räucheraltar zu verbrennen." },
      { number: 17, text: "Doch der Priester Asarja ging hinter ihm her, und 80 Priester Jahwes kamen mit ihm, lauter beherzte Männer." },
      { number: 18, text: "Sie widerstanden König Usija und sagten: \"Dir, Usija, steht es nicht zu, Jahwe Räucheropfer zu bringen. Das ist nur den geweihten Priestern, den Söhnen Aarons, erlaubt. Verlass das Heiligtum! Du hast dich gegen Jahwe vergangen! Bei ihm kannst du damit keinen Ruhm ernten.\"" },
      { number: 19, text: "Aber Usija, der bereits die Räucherpfanne in der Hand hielt, wurde wütend. Als er sich zornig gegen die Priester umdrehte, brach der Aussatz* an seiner Stirn aus. Es geschah vor den Augen der Priester im Haus Jahwes, neben dem Räucheraltar.", footnotes: ["Aussatz. Bezeichnung für rasch um sich greifende Hautkrankheiten, Lepra eingeschlossen."] },
      { number: 20, text: "Als der Oberpriester Asarja und die anderen Priester sahen, wie der Aussatz auf einmal an seiner Stirn ausbrach, trieben sie ihn schleunigst von dort weg. Auch Usija selbst beeilte sich, hinauszukommen, weil Jahwe ihn gestraft hatte." },
      { number: 21, text: "Bis zu seinem Tod blieb König Usija aussätzig. Deshalb musste er in einem abgesonderten Haus wohnen und durfte das Haus Jahwes nie mehr betreten. Die Regierungsgeschäfte und die Aufsicht über den Palast übergab er seinem Sohn Jotam." },
      { number: 22, text: "Was sonst noch über Usija zu sagen ist, seine frühere und spätere Geschichte, hat der Prophet Jesaja Ben-Amoz aufgeschrieben." },
      { number: 23, text: "Als Usija starb, wurde er, weil er aussätzig war, auf dem Gelände neben der Grabstätte der Könige bestattet. Sein Sohn Jotam trat die Herrschaft an." },
    ] },
    { number: 27, verses: [
      { number: 1, text: "Jotam war bei Herrschaftsantritt 25 Jahre alt und regierte insgesamt 16 Jahre in Jerusalem*. Seine Mutter hieß Jeruscha und war eine Tochter Zadoks.", heading: "König Jotam von Juda", footnotes: ["regierte ... 16 Jahre. Von 750-740 v.Chr. war Jotam Mitregent neben seinem aussätzigen Vater Usija (in 2. Könige 15,1 ff. Asarja genannt). Allein regierte er bis 731 v.Chr."] },
      { number: 2, text: "Er tat, was Jahwe gefiel, und folgte in allem dem Vorbild seines Vaters Usija. Allerdings ging er nicht wie dieser in den Tempel Jahwes. Das Volk blieb jedoch bei seinem Verderben bringenden Tun." },
      { number: 3, text: "Jotam baute das obere Tor am Haus Jahwes und verstärkte die Mauern des Ofel* an vielen Stellen.", footnotes: ["Der Ofel war der befestigte Hügel südlich vom Tempelberg zwischen dem Tempel und der Davidsstadt."] },
      { number: 4, text: "Er baute außerdem einige Städte auf dem Gebirge Juda aus und errichtete Burgen und Türme in den Waldgebieten." },
      { number: 5, text: "Er war es auch, der mit dem König der Ammoniter kämpfte. Er besiegte die Ammoniter, und sie mussten ihm jenes Jahr 3,4 Tonnen Silberstücke abliefern, dazu 1 700 Tonnen Weizen und 1 700 Tonnen Gerste. Und das gleiche noch einmal im nächsten und übernächsten Jahr." },
      { number: 6, text: "Jotam wurde mächtig, denn er richtete sich in dem, was er tat, nach Jahwe, seinem Gott." },
      { number: 7, text: "Was es sonst noch über Jotam zu berichten gibt, seine Kriege und Unternehmungen, ist in der Chronik der Könige von Israel und Juda nachzulesen." },
      { number: 8, text: "Er war bei Herrschaftsantritt 25 Jahre alt und regierte insgesamt 16 Jahre in Jerusalem." },
      { number: 9, text: "Als Jotam starb, wurde er in der Davidsstadt bestattet. Sein Sohn Ahas trat die Herrschaft an." },
    ] },
    { number: 28, verses: [
      { number: 1, text: "Im Alter von 20 Jahren wurde Ahas König, und er regierte 16 Jahre in Jerusalem. Anders als sein Vorfahr David richtete er sich nicht nach dem, was Jahwe gefiel,", heading: "König Ahas von Juda" },
      { number: 2, text: "sondern folgte dem schlechten Beispiel der Könige von Israel. Er ließ Gussbilder für die Baale anfertigen" },
      { number: 3, text: "und brachte im Ben-Hinnom-Tal Räucheropfer. Er ließ sogar seine eigenen Söhne als Opfer verbrennen, wie es der grauenvollen Gewohnheit der heidnischen Völker entsprach, die Jahwe vor den Israeliten aus dem Land vertrieben hatte." },
      { number: 4, text: "Außerdem brachte er auf den Opferstätten der Höhen, auf den Hügeln und unter jedem grünen Baum Schlacht- und Räucheropfer dar." },
      { number: 5, text: "Da ließ ihn Jahwe, sein Gott, in die Gewalt des Königs von Syrien geraten. Die Syrer besiegten ihn und brachten eine große Anzahl gefangener Judäer nach Damaskus. Er geriet auch in die Gewalt des Königs von Israel, der ihm eine schwere Niederlage beibrachte." },
      { number: 6, text: "Es war Pekach Ben-Remalja, der an einem einzigen Tag 120.000 Mann umbrachte, alles hervorragende Soldaten, weil sie Jahwe, den Gott ihrer Väter, verlassen hatten." },
      { number: 7, text: "Sichri, ein efraïmitischer Held, erschlug den Prinzen Maaseja, den Sohn des Königs, den Palastvorsteher Asrikam und Elkana, den Zweiten nach dem König." },
      { number: 8, text: "Die Männer Israels nahmen aus ihrem Brudervolk 200.000 Frauen und Kinder als Gefangene mit. Außerdem machten sie reiche Beute und brachten sie nach Samaria." },
      { number: 9, text: "Dort lebte ein Prophet namens Oded. Als das Heer nach Samaria heimkam, ging er ihm entgegen und sagte: \"Passt auf! Im Zorn über Juda gab Jahwe, der Gott eurer Väter, sie in eure Gewalt. Aber ihr habt sie mit einer Wut umgebracht, dass es zum Himmel schreit." },
      { number: 10, text: "Und nun wollt ihr diese Leute aus Juda und Jerusalem auch noch zu Sklaven und Sklavinnen machen. Habt ihr denn eurem Gott Jahwe gegenüber noch nicht genug Schuld auf euch geladen?" },
      { number: 11, text: "Hört jetzt auf mich und schickt die Gefangenen zurück, die ihr aus eurem Brudervolk weggeführt habt, denn ein glühender Zorn Jahwes droht über euch loszubrechen!\"" },
      { number: 12, text: "Auch einige der führenden Männer aus dem Stamm Efraïm traten dem heimkehrenden Heer entgegen. Es waren Asarja Ben-Johanan, Berechja Ben-Meschillemot, Jehiskija Ben-Schallum und Amasa Ben-Hadlai." },
      { number: 13, text: "Sie sagten: \"Lasst die Gefangenen nicht hierher kommen! Denn was ihr vorhabt, wird unsere Sünde und Schuld nur noch vermehren. Dabei ist sie schon groß genug, und es liegt bereits eine Zornesglut über Israel!\"" },
      { number: 14, text: "Da gaben die Bewaffneten in Gegenwart der Oberen und der ganzen Versammlung die Gefangenen und die Beute frei." },
      { number: 15, text: "Männer, die namentlich dazu bestimmt wurden, nahmen sich der Gefangenen an, von denen manche kaum etwas auf dem Leib trugen. Sie gaben ihnen Kleidung und Schuhe aus der Beute. Dann gaben sie ihnen zu essen und zu trinken. Sie salbten die Schwachen unter ihnen und setzten sie auf Esel. Dann brachten sie die Gefangenen in die Palmenstadt Jericho, in die Nähe ihrer Stammesbrüder. Anschließend kehrten sie nach Samaria zurück." },
      { number: 16, text: "Damals schickte König Ahas eine Botschaft an den Königshof von Assyrien und bat um Hilfe," },
      { number: 17, text: "weil die Edomiter wieder ins Land eingedrungen waren. Sie hatten die Judäer besiegt und Gefangene gemacht." },
      { number: 18, text: "Die Philister fielen in die Städte der Niederung und des Südens von Juda ein. Sie eroberten Bet-Schemesch, Ajalon und Gederot, sowie Socho, Timna und Gimso mit den dazugehörigen Ortschaften und setzten sich dort fest." },
      { number: 19, text: "Jahwe ließ das geschehen, weil er Juda wegen König Ahas von Israel* demütigen wollte, denn dieser hatte ihm die Treue gebrochen und Zügellosigkeit in Juda geduldet.", footnotes: ["Israel ist hier im allgemeinen Sinn gebraucht und nicht auf das Nordreich bezogen."] },
      { number: 20, text: "Dann zog Tiglat-Pileser, der König von Assyrien, tatsächlich mit einem Heer heran. Doch bedrängte er Ahas, anstatt ihn zu unterstützen." },
      { number: 21, text: "Obwohl dieser das Haus Jahwes, den Königspalast und die Häuser der Oberen geplündert und alles dem König von Assyrien übergeben hatte, bekam er nicht die erwartete Hilfe." },
      { number: 22, text: "Aber selbst in dieser Bedrängnis blieb König Ahas Jahwe ungehorsam, er trieb es sogar noch schlimmer." },
      { number: 23, text: "Er opferte den Göttern von Damaskus, die ihn geschlagen hatten, und sagte: \"Diese Götter haben den Königen von Syrien geholfen. Denen will ich opfern, dann werden sie auch mir helfen.\" Doch gerade sie waren es, die ihn und ganz Israel zu Fall brachten." },
      { number: 24, text: "Ahas ließ die Gegenstände aus dem Haus Jahwes zusammentragen und zerschlagen. Dann ließ er die Tore von Jahwes Haus schließen und errichtete Altäre an allen Ecken Jerusalems." },
      { number: 25, text: "Außerdem ließ er in allen Städten Judas Opferhöhen errichten, um anderen Göttern Räucheropfer zu bringen. So forderte er Jahwe, den Gott seiner Väter, heraus." },
      { number: 26, text: "Was es sonst noch über ihn zu berichten gibt, seine frühere und spätere Geschichte, ist in der Chronik der Könige von Juda und Israel nachzulesen." },
      { number: 27, text: "Als Ahas starb, wurde er in Jerusalem beigesetzt, innerhalb der Stadt, nicht in der Grabstätte der Könige von Israel. Sein Sohn Hiskija trat die Herrschaft an." },
    ] },
    { number: 29, verses: [
      { number: 1, text: "Als Hiskija 25 Jahre alt war, wurde er König* von Juda. Er regierte 29 Jahre lang in Jerusalem. Seine Mutter hieß Abija und war eine Tochter Secharjas.", heading: "Hiskijas Reform (29-33)\nKönig Hiskija von Juda", footnotes: ["König. Das war 715 v.Chr. Seit 729 war er Mitregent gewesen. Als Alleinherrscher regierte er bis 686 v.Chr."] },
      { number: 2, text: "Wie sein Vorfahr David tat Hiskija, was Jahwe gefiel." },
      { number: 3, text: "Noch im ersten Jahr seiner Regierung ließ er die Tore vom Haus Jahwes wieder öffnen und instand setzen." },
      { number: 4, text: "Dann ließ er die Priester und Leviten kommen. Sie sollten sich auf dem Ostplatz versammeln." },
      { number: 5, text: "Er sagte zu ihnen: \"Hört zu, ihr Leviten! Heiligt euch jetzt und heiligt auch das Haus Jahwes, des Gottes eurer Väter, und schafft das Abscheuliche aus dem Heiligtum hinaus." },
      { number: 6, text: "Unsere Vorfahren sind Jahwe untreu geworden und taten, was ihm missfiel. Sie haben ihn verlassen und seiner Wohnung den Rücken gekehrt." },
      { number: 7, text: "Dann haben sie die Tore der Vorhalle geschlossen, die Lampen ausgelöscht und dem Gott Israels im Heiligtum kein Räucheropfer und kein Brandopfer mehr gebracht." },
      { number: 8, text: "Darum ist Jahwes Zorn über Juda und Jerusalem gekommen, und er hat sie zum Schreckensbild gemacht, zu einer Stätte des Entsetzens und zum Gespött, wie ihr mit eigenen Augen seht." },
      { number: 9, text: "Deshalb fielen unsere Väter dem Schwert zum Opfer, und unsere Frauen und Kinder kamen in Gefangenschaft." },
      { number: 10, text: "Ich habe nun vor, einen Bund mit Jahwe, dem Gott Israels, zu schließen, damit sein glühender Zorn von uns ablässt." },
      { number: 11, text: "Nun los, meine Söhne, verliert keine Zeit! Euch hat Jahwe doch erwählt, dass ihr als seine Diener vor ihm steht und ihm Räucheropfer bringt.\"" },
      { number: 12, text: "Da machten sich die Leviten auf. Es waren Mahat Ben-Amasai und Joël Ben-Asarja von den Nachkommen Kehats, Kisch Ben-Abdi und Asarja Ben-Jehallelel von den Nachkommen Meraris, Joach Ben-Simma und Eden Ben-Joach von den Nachkommen Gerschons." },
      { number: 13, text: "Von den Nachkommen Elizafans waren es Schimri und Jëiël, von den Nachkommen Asafs: Secharja und Mattanja." },
      { number: 14, text: "Von den Nachkommen Hemans waren es Jehiël und Schimi, von den Nachkommen Jedutuns: Schemaja und Usiël." },
      { number: 15, text: "Sie riefen ihre Stammesbrüder zusammen und heiligten sich für ihren Dienst. Dann gingen sie nach der Anordnung des Königs und den Worten Jahwes entsprechend ins Haus Jahwes, um es zu reinigen." },
      { number: 16, text: "Die Priester betraten das Innere des Hauses und brachten alles Besudelte aus dem Tempel in den Vorhof hinaus, wo es die Leviten in Empfang nahmen, um es ins Kidrontal zu schaffen." },
      { number: 17, text: "Am 1. April* begannen sie mit der Reinigung. Nach einer Woche kamen sie zu der Vorhalle Jahwes. Während der folgenden acht Tage reinigten sie das Haus Jahwes, und am 16. April waren sie fertig.", footnotes: ["April Wörtlich: des 1. Monats."] },
      { number: 18, text: "Dann gingen sie zum König Hiskija und meldeten: \"Wir haben das Haus Jahwes gereinigt, auch den Brandopferaltar und den Tisch für die geweihten Brote und alle dazugehörigen Gegenstände." },
      { number: 19, text: "Wir haben auch all die anderen Gegenstände wieder hergerichtet und geweiht, die König Ahas während seiner Herrschaft entweiht hatte, als er Jahwe untreu wurde. Sie stehen am Altar Jahwes bereit.\"" },
      { number: 20, text: "Am nächsten Morgen rief Hiskija die führenden Männer der Stadt zu sich und ging mit ihnen zum Haus Jahwes hinauf." },
      { number: 21, text: "Man führte sieben Stiere, sieben Schafböcke, sieben Lämmer und sieben Ziegenböcke als Sündopfer für das Königshaus, das Heiligtum und für Juda mit. Der König befahl den Priestern, den Nachkommen Aarons, sie auf dem Altar Jahwes zu opfern." },
      { number: 22, text: "Man schlachtete die Rinder; die Priester nahmen das Blut in Empfang und sprengten es an den Altar. Ebenso taten sie es bei den Schafböcken und den Lämmern." },
      { number: 23, text: "Dann brachten sie die Ziegenböcke für das Sündopfer vor den König und die Versammlung. Diese legten ihre Hände auf die Opfertiere." },
      { number: 24, text: "Dann schlachteten die Priester die Böcke und sprengten ihr Blut als Sündopfer an den Altar, um für ganz Israel Sühne zu erwirken, denn der König hatte das Brand- und das Sündopfer für ganz Israel angeordnet." },
      { number: 25, text: "Er hatte auch die Leviten mit Zimbeln, Harfen und Lauten wieder im Haus Jahwes eingesetzt. So war es von König David angeordnet worden nach dem Befehl Jahwes, der ihm durch seinen Seher Gad und den Propheten Natan übermittelt worden war." },
      { number: 26, text: "Die Leviten standen also mit den Instrumenten Davids bereit und die Priester mit den Trompeten." },
      { number: 27, text: "Als Hiskija befahl, das Brandopfer auf dem Altar zu opfern, begann der Gesang für Jahwe unter Begleitung der Instrumente des Königs David und der Trompeten." },
      { number: 28, text: "Die ganze Versammlung warf sich nieder, während der Gesang ertönte und die Trompeten schmetterten. Das Ganze dauerte bis zum Abschluss des Opfers." },
      { number: 29, text: "Nach der Opferung knieten sich der König und alle, die bei ihm waren, nieder und beteten an." },
      { number: 30, text: "Dann forderte König Hiskija mit den Oberen die Leviten auf, Jahwe mit den Worten Davids und des Sehers Asaf Loblieder zu singen. Sie taten das mit Freude. Dann verneigten sie sich und beteten an." },
      { number: 31, text: "Hiskija sagte zu den Versammelten: \"Nun habt ihr euch Jahwe geweiht. Kommt jetzt und bringt eure Schlacht- und Freudenopfer zum Haus Jahwes!\" Die Versammelten brachten ihre Opfer herbei, und manche gaben freiwillig noch Brandopfer hinzu." },
      { number: 32, text: "Auf diese Weise kamen 70 Rinder, 100 Schafböcke und 200 Schafe als Brandopfer für Jahwe zusammen." },
      { number: 33, text: "Die Weihgaben beliefen sich auf 600 Rinder und 3000 Schafe." },
      { number: 34, text: "Es waren aber zu wenig Priester da, um alle Brandopfer enthäuten zu können. Deshalb wurden sie von ihren Stammesbrüdern, den Leviten, unterstützt, bis die Arbeit geschafft war und sich genügend Priester geheiligt hatten. Die Leviten hatten sich nämlich eifriger um ihre Heiligung bemüht als die Priester." },
      { number: 35, text: "Außerdem war die Zahl der Brandopfer und die dazu gehörenden Trankopfer, die neben den Fettstücken der Freudenopfer dargebracht werden mussten, sehr hoch.So wurde der Dienst im Haus Jahwes wiederhergestellt." },
      { number: 36, text: "Hiskija und das ganze Volk freuten sich über das, was Gott ihnen auf diese Weise geschenkt hatte; denn die Sache war sehr rasch vor sich gegangen." },
    ] },
    { number: 30, verses: [
      { number: 1, text: "Hiskija schickte Boten mit Briefen durch ganz Israel und Juda, auch an die Stämme Efraïm und Manasse. Er lud sie ein, zum Haus Jahwes nach Jerusalem zu kommen, um Jahwe, dem Gott Israels, das Passafest* zu feiern.", heading: "Die Feier des Passa", footnotes: ["Passa. Siehe 2. Mose 12-13."] },
      { number: 2, text: "Der König hatte sich mit den verantwortlichen Männern und der ganzen Versammlung in Jerusalem beraten, ob sie das Passa nicht einen Monat später feiern sollten," },
      { number: 3, text: "denn sie konnten es nicht rechtzeitig tun, weil sich nicht genügend Priester geheiligt hatten und das Volk noch nicht nach Jerusalem gekommen war." },
      { number: 4, text: "Der Plan gefiel dem König und der ganzen Versammlung." },
      { number: 5, text: "So fassten sie also den Beschluss, durch ganz Israel von Dan bis Beerscheba* einen Aufruf ergehen zu lassen, um Jahwe, dem Gott Israels, das Passa in Jerusalem zu feiern. Denn sie hatten es lange Zeit nicht vollzählig gefeiert, wie es vorgeschrieben war.", footnotes: ["Dan bis Beerscheba. Das meint vom nördlichsten bis zum südlichsten Ort in Israel."] },
      { number: 6, text: "So zogen die Eilboten mit den Briefen des Königs und seiner führenden Männer durch ganz Israel und Juda. Wie der König es ihnen aufgetragen hatte, riefen sie aus: \"Ihr Leute von Israel, kehrt um zu Jahwe, dem Gott Abrahams, Isaaks und Israels! Dann wird er sich auch euch zuwenden, den Übriggebliebenen, die dem Zugriff der Könige von Assyrien entkommen sind." },
      { number: 7, text: "Seid nicht wie eure Väter und Brüder, die Jahwe, dem Gott eurer Vorfahren, untreu geworden sind, sodass er sie zu einem Bild des Entsetzens machte, wie ihr seht." },
      { number: 8, text: "Seid nicht so stur wie eure Väter! Reicht Jahwe die Hand und kommt zu seinem Heiligtum, das er für alle Zeiten geheiligt hat, und dient Jahwe, eurem Gott, damit er die Glut seines Zorns von euch abwendet." },
      { number: 9, text: "Wenn ihr zu Jahwe umkehrt, werden auch eure Brüder und Kinder Erbarmen finden bei denen, die sie verschleppt haben, und sie werden in euer Land zurückkehren. Denn Jahwe, euer Gott, ist gütig und barmherzig und wird sich nicht von euch abwenden, wenn ihr zu ihm umkehrt.\"" },
      { number: 10, text: "Die Eilboten zogen von Stadt zu Stadt durch das Gebiet von Efraïm und Manasse bis nach Sebulon*. Doch man lachte sie aus und verspottete sie.", footnotes: ["Sebulon. Der Stamm bewohnte einen Teil Galiläas und der Jesreel-Ebene."] },
      { number: 11, text: "Nur einige Männer aus den Stämmen Ascher*, Manasse und Sebulon demütigten sich und kamen nach Jerusalem.", footnotes: ["Ascher war der Nachbarstamm Sebulons zum Mittelmeer hin. Er bewohnte etwa das Gebiet zwischen Tyrus und Acco."] },
      { number: 12, text: "In Juda bewirkte Gott, dass alle einmütig dem Aufruf des Königs und der Oberen folgten, den diese nach dem Gebot Jahwes erlassen hatten." },
      { number: 13, text: "So versammelte sich eine große Menge Menschen in Jerusalem, um das Fest der ungesäuerten Brote* im Mai* zu feiern. Es war eine ungewöhnlich große Versammlung.", footnotes: ["Das Fest der ungesäuerten Brote folgte unmittelbar auf das Passafest und dauerte eine Woche.", "Mai. Wörtlich: im 2. Monat."] },
      { number: 14, text: "Zuerst beseitigten sie alle Altäre und Räucheraltäre, die in Jerusalem standen, und warfen sie ins Kidrontal." },
      { number: 15, text: "Am 14. Mai schlachteten sie die Lämmer für das Passa. Die Priester und Leviten hatten sich geschämt und sich diesmal geheiligt und Brandopfer in das Haus Jahwes gebracht." },
      { number: 16, text: "Sie standen jetzt auf ihrem Posten, wie es das Gesetz Moses, des Mannes Gottes, vorschreibt, und sprengten das Blut, das sie von den Leviten erhielten, an den Altar." },
      { number: 17, text: "Weil viele in der Versammlung sich nicht geheiligt hatten, schlachteten die Leviten die Passalämmer für alle, die nicht rein waren, damit die Lämmer Jahwe geweiht werden konnten." },
      { number: 18, text: "Denn ein großer Teil des Volkes, viele aus Efraïm und Manasse, Issachar und Sebulon hatten sich nicht gereinigt und aßen das Passamahl nicht so, wie es vorgeschrieben war. Darum betete Hiskija für sie: \"Jahwe, du gütiger Gott! Vergib jedem," },
      { number: 19, text: "der dich, den Gott seiner Väter, von ganzem Herzen sucht, auch wenn er selbst nicht der Reinheit des Heiligtums entspricht.\"" },
      { number: 20, text: "Jahwe erhörte Hiskija und ließ das Volk gesund bleiben." },
      { number: 21, text: "Die in Jerusalem versammelten Israeliten feierten sieben Tage lang voller Freude das Fest der ungesäuerten Brote. Tag für Tag sangen die Priester und Leviten für Jahwe, begleitet von den Instrumenten, die zum Lob Jahwes bestimmt waren." },
      { number: 22, text: "Hiskija bedankte sich herzlich bei den Leviten, die so großes Verständnis für Jahwe bewiesen hatten. Als dann die sieben Tage des Festes zu Ende waren, an denen sie Freudenopfer brachten und Jahwe, den Gott ihrer Väter, priesen," },
      { number: 23, text: "beschloss die ganze Versammlung, noch weitere sieben Tage zu feiern. Auch diese Woche machten sie zu einem Freudenfest." },
      { number: 24, text: "König Hiskija von Juda hatte der Versammlung dazu 1000 junge Stiere und 7000 Schafe gespendet. Auch die Oberen hatten 1000 junge Stiere und 10.000 Schafe gegeben. Von den Priestern hatten sich sehr viele geheiligt." },
      { number: 25, text: "So freute sich die ganze Versammlung: das Volk von Juda, die Priester und Leviten und alle, die aus den Stämmen Israels gekommen waren, sowie die Fremden, die von dort mitgekommen waren oder in Juda wohnten." },
      { number: 26, text: "In ganz Jerusalem herrschte große Freude, denn seit der Zeit von König Salomo Ben-David hatte es so etwas in Jerusalem nicht mehr gegeben." },
      { number: 27, text: "Dann erhoben sich die Priester, die Nachkommen Levis, und segneten das Volk. Ihr Rufen wurde erhört, ihr Gebet drang bis in Gottes heilige Wohnung im Himmel." },
    ] },
    { number: 31, verses: [
      { number: 1, text: "Nachdem alle Festlichkeiten zu Ende waren, zogen die versammelten Israeliten in die anderen Städte Judas und zertrümmerten die Steinmale, hieben die geweihten Pfähle um und zerstörten die Opferhöhen und Altäre. Sie ruhten nicht eher, bis sie ihr Werk in ganz Juda und Benjamin, Efraïm und Manasse vollendet hatten. Dann erst kehrten alle Israeliten nach Hause zurück." },
      { number: 2, text: "Hiskija stellte die Abteilungen der Priester und Leviten nach ihren Dienstgruppen auf. Er wies sie in ihre Dienste bei den Brand- und Freudenopfern ein, ebenso beim Lobpreis in den Toren der Wohnstätten Jahwes.", heading: "Neuordnung des Tempeldienstes" },
      { number: 3, text: "Der Beitrag, den der König aus seinem Vermögen für die Brandopfer gab, betraf die Opfer am Morgen und Abend, sowie die Brandopfer an den Sabbaten, den Neumondstagen und den Festen, die durch das Gesetz Jahwes vorgeschrieben waren." },
      { number: 4, text: "Dann befahl er den Einwohnern Jerusalems, die Abgaben zu bringen, die den Priestern und Leviten zustanden, damit diese sich den im Gesetz Jahwes vorgeschriebenen Aufgaben widmen könnten." },
      { number: 5, text: "Sobald dieser Befehl bekannt wurde, brachten die Israeliten in großen Mengen die Ersterträge von Getreide, Most, Öl, Honig und allen Feldfrüchten, dazu den vorgeschriebenen zehnten Teil von allen Erträgen." },
      { number: 6, text: "Auch die Bewohner der anderen Städte Judas und die Israeliten, die sich bei ihnen niedergelassen hatten, brachten den zehnten Teil der Rinder, des Kleinviehs und der Gaben, die sie Jahwe, ihrem Gott, geweiht hatten. Sie reihten Stapel neben Stapel." },
      { number: 7, text: "Im Juni begannen sie damit, die unterste Schicht zu legen, und im Oktober* waren sie damit fertig.", footnotes: ["Juni … Oktober. Wörtlich: im 3. … 7. Monat."] },
      { number: 8, text: "Als Hiskija und die Oberen kamen und die aufgeschichteten Mengen sahen, priesen sie Jahwe und lobten sein Volk Israel." },
      { number: 9, text: "Hiskija fragte die Priester und Leviten nach den Stapeln." },
      { number: 10, text: "Der Oberpriester Asarja aus dem Haus Zadoks erwiderte ihm: \"Seit man begonnen hat, die Abgaben in das Haus Jahwes zu bringen, haben wir gut und reichlich zu essen gehabt und noch viele Vorräte übrig. Jahwe hat sein Volk so reich gesegnet, dass wir diese Mengen hier übrig haben.\"" },
      { number: 11, text: "Hiskija befahl deshalb, im Haus Jahwes Vorratskammern einzurichten. Als das geschehen war," },
      { number: 12, text: "lagerten sie die Abgaben, den Zehnten und die geweihten Gaben sorgfältig dort ein. Als Oberaufseher darüber wurde der Levit Konanja bestimmt mit seinem Bruder Schimi als Stellvertreter." },
      { number: 13, text: "Auf Anweisung von König Hiskija und dem Oberpriester Asarja unterstanden Konanja und seinem Bruder Schimi die Leviten Jehiël, Asasja, Nahat, Asaël, Jerimot, Josabad, Eliël, Jismachja, Mahat und Benaja." },
      { number: 14, text: "Der Levit Kore Ben-Jimna, Torwächter des Osttors, hatte die Aufsicht über die freiwilligen Gaben für Gott, damit die für Jahwe bestimmten Abgaben und das Höchstheilige den Priestern zukamen." },
      { number: 15, text: "Unter seiner Leitung standen Eden, Minjamin, Jeschua, Schemaja, Amarja und Schechanja, die in den Priesterstädten wirkten. Sie sorgten dafür, dass ihre Amtsbrüder in den verschiedenen Dienstgruppen ihre Anteile zuverlässig erhielten, egal wie alt sie waren." },
      { number: 16, text: "Außerdem hatte man Verzeichnisse angelegt, in denen die männlichen Personen von drei Jahren an erfasst waren. Das betraf alle Priester, die in Dienstgruppen turnusmäßig ins Haus Jahwes kamen, um dort die täglichen Aufgaben zu erfüllen, wie es ihren jeweiligen Stellungen entsprach." },
      { number: 17, text: "Die Priester wurden nach Sippen geordnet aufgeführt, die übrigen Leviten, die älter als zwanzig Jahre waren, nach ihren Dienstgruppen und Aufgaben." },
      { number: 18, text: "Für die Registrierung wurden sie mit all ihren kleinen Kindern, ihren Frauen, Söhnen und Töchtern erfasst, denn sie hatten sich gewissenhaft für den gottgeweihten Dienst geheiligt." },
      { number: 19, text: "Auch für die Nachkommen Aarons, die in den Weidegebieten ihrer Städte wohnten, war gesorgt. Für diese Priester waren in jeder Stadt Männer benannt worden, die allen männlichen Angehörigen der Priesterfamilien ihre Anteile zu geben hatten, auch allen eingeschriebenen Leviten." },
      { number: 20, text: "So verfuhr Hiskija in ganz Juda. Er tat, was vor Jahwe, seinem Gott, recht und gut war, und bewies damit seine Treue." },
      { number: 21, text: "Bei allem, was er tat im Dienst für das Haus Gottes und die Gebote betreffend, hatte er Gelingen, weil er seinem Gott gehorchen wollte." },
    ] },
    { number: 32, verses: [
      { number: 1, text: "Nach diesen Maßnahmen und Treuebeweisen Hiskijas rückte Sanherib, der König von Assyrien, an. Er fiel in Juda ein und belagerte die befestigten Städte. Er wollte sie in seine Gewalt bringen.", heading: "Assyrer vor Jerusalem" },
      { number: 2, text: "Als Hiskija erkannte, dass Sanherib es vor allem auf Jerusalem abgesehen hatte," },
      { number: 3, text: "beriet er sich mit seinen Ministern und Heerführern. Er schlug vor, alle Wasserquellen außerhalb der Stadt unzugänglich zu machen. Sie unterstützten sein Vorhaben" },
      { number: 4, text: "und sagten: \"Warum sollen die Könige von Assyrien viel Wasser finden, wenn sie kommen?\" Sie holten viele Leute zusammen und verstopften alle Quellen, auch den Zugang zu dem unterirdischen Kanal." },
      { number: 5, text: "Hiskija ging auch entschlossen daran, die Stadtmauer wieder instand zu setzen, die Risse bekommen hatte, und ihre Türme zu erhöhen; ebenso die andere Mauer draußen. Außerdem befestigte er den Stadtwall der Davidsstadt und ließ eine Menge Wurfgeschosse und Schilde anfertigen." },
      { number: 6, text: "Er setzte Hauptleute über das Volk ein und bestellte alle zu sich auf den Platz am Stadttor, um ihnen Mut zu machen. Er sagte:" },
      { number: 7, text: "\"Seid mutig und entschlossen! Habt keine Angst und erschreckt nicht vor dem König von Assyrien und der ganzen lärmenden Menge, die bei ihm ist, denn mit uns ist ein Größerer als mit ihm." },
      { number: 8, text: "Mit ihm ist eine menschliche Macht, doch mit uns ist Jahwe, unser Gott, um uns zu helfen und unseren Krieg zu führen.\" Das Volk vertraute auf die Worte Hiskijas, des Königs von Juda." },
      { number: 9, text: "Unterdessen schickte König Sanherib von Assyrien seine Boten nach Jerusalem, während er und seine ganze Streitmacht noch vor Lachisch lag. Sie sollten König Hiskija von Juda und allen Judäern in Jerusalem ausrichten:" },
      { number: 10, text: "\"König Sanherib von Assyrien lässt euch sagen: Worauf vertraut ihr eigentlich, dass ihr es in einer belagerten Stadt Jerusalem aushalten wollt?" },
      { number: 11, text: "Hiskija führt euch in den Tod, wenn er sagt: 'Jahwe, unser Gott, wird uns aus der Gewalt des Königs von Assyrien retten.' Verhungern und verdursten werdet ihr!" },
      { number: 12, text: "War es nicht gerade Hiskija, der dessen Höhenheiligtümer und Altäre beseitigt und den Leuten in Juda und Jerusalem befohlen hat, nur noch vor dem einen Altar anzubeten und Räucheropfer zu bringen?" },
      { number: 13, text: "Wisst ihr nicht, was ich und meine Vorgänger mit den anderen Völkern in ihren Ländern gemacht haben? Haben denn die Götter der anderen Völker ihr Land vor mir retten können?" },
      { number: 14, text: "Gibt es einen einzigen Gott von diesen Völkern, die durch meine Väter vernichtet wurden, der sein Volk aus unserer Gewalt befreien konnte? Und da soll ausgerechnet euer Gott euch vor mir retten können?" },
      { number: 15, text: "Lasst euch nicht von Hiskija täuschen! Lasst euch doch nicht so in die Irre führen! Glaubt ihm nicht! Kein Gott irgendeines Landes oder Königreichs konnte sein Volk vor meinen Vätern retten. Und euer Gott kann das schon gar nicht!\"" },
      { number: 16, text: "In dieser Weise redeten die Boten Sanheribs weiter gegen Jahwe und dessen Diener Hiskija." },
      { number: 17, text: "Sanherib hatte auch einen Brief geschickt, in dem er Jahwe, den Gott Israels, verhöhnte. Er schrieb darin: \"Genauso wenig, wie die Götter der Länder ihr Volk vor mir gerettet haben, wird der Gott Hiskijas sein Volk vor mir retten können.\"" },
      { number: 18, text: "Den Einwohnern von Jerusalem, die auf der Mauer standen, riefen die Boten das auch laut auf judäisch zu. Sie wollten ihnen damit Angst einjagen und sie einschüchtern, um die Stadt erobern zu können." },
      { number: 19, text: "Dabei redeten sie von dem Gott Jerusalems so, wie von den Göttern der anderen Völker, die doch Machwerke von Menschen sind." },
      { number: 20, text: "König Hiskija und der Prophet Jesaja beteten deswegen, ja, sie schrien zum Himmel um Hilfe." },
      { number: 21, text: "Da schickte Jahwe einen Engel, der jeden Wehrtüchtigen, jeden Offizier und Befehlshaber im Lager des assyrischen Königs tötete. So musste dieser mit Schimpf und Schande in sein Land zurückkehren. Und als er in das Haus seines Gottes ging, erschlugen ihn dort seine eigenen Söhne mit dem Schwert." },
      { number: 22, text: "So befreite Jahwe Hiskija und die Einwohner Jerusalems aus der Gewalt Sanheribs, des Königs von Assyrien, und von allen ihren Feinden. Er schenkte ihnen Ruhe an allen Grenzen." },
      { number: 23, text: "Viele Menschen brachten Gaben für Jahwe nach Jerusalem und kostbare Geschenke für König Hiskija von Juda, denn er war seitdem bei allen Völkern hoch angesehen." },
      { number: 24, text: "In dieser Zeit wurde Hiskija todkrank. Da betete er zu Jahwe, und dieser erhörte ihn und bestätigte ihm das durch ein Wunderzeichen.*", heading: "Hiskijas letzte Regierungsjahre", footnotes: ["todkrank ... Wunderzeichen. Diese Geschehnisse fanden etwa ein Jahr vor dem Feldzug Sanheribs statt, wie Jes 38,6 zeigt (siehe Fußnote zu Jes 38,1)."] },
      { number: 25, text: "Aber Hiskija wurde hochmütig und dankte ihm die erwiesene Wohltat nicht. Deshalb kam Gottes Zorn über ihn und auch über Juda und Jerusalem." },
      { number: 26, text: "Da demütigte sich Hiskija wegen seines Hochmuts, er und die Bewohner Jerusalems ebenso. Darum kam der Zorn Jahwes nicht schon zu Lebzeiten Hiskijas über sie." },
      { number: 27, text: "Hiskija war sehr vermögend und genoss überall hohes Ansehen. Er legte sich Schatzkammern an für sein Gold und Silber, die Edelsteine, Balsamöle, Schilde und alle möglichen kostbaren Gegenstände." },
      { number: 28, text: "Er ließ auch Vorratshäuser für Getreide, Wein und Olivenöl bauen und Ställe für das Vieh, das er in großer Zahl hielt." },
      { number: 29, text: "Er legte sich neue Städte an und vermehrte seinen Besitz an Schafen und Rindern. Gott gab ihm sehr viel Reichtum." },
      { number: 30, text: "Hiskija war es auch, der die Gihon-Quelle außerhalb der Stadt unkenntlich machen und das Wasser unterirdisch in westlicher Richtung in die Davidsstadt leiten ließ. Hiskija gelang alles, was er sich vornahm." },
      { number: 31, text: "So ging auch die Sache gut aus, als die Fürsten von Babylon Gesandte zu ihm schickten, um nach dem Wunderzeichen zu fragen, das im Land geschehen war. Damals überließ Gott ihn sich selbst, um seinen Charakter auf die Probe zu stellen." },
      { number: 32, text: "Was es sonst noch über Hiskija und seine Treue zu berichten gibt, ist nachzulesen in der Niederschrift der Offenbarung des Propheten Jesaja Ben-Amoz und in der Chronik der Könige von Juda und Israel." },
      { number: 33, text: "Als Hiskija starb, begrub man ihn beim Aufgang zu den Gräbern der Nachkommen Davids. Ganz Juda und die Bewohner Jerusalems erwiesen ihm Ehre bei seinem Tod. Sein Sohn Manasse trat die Herrschaft an." },
    ] },
    { number: 33, verses: [
      { number: 1, text: "Manasse war bei Herrschaftsantritt 12 Jahre alt und regierte 55 Jahre lang in Jerusalem.", heading: "König Manasse von Juda" },
      { number: 2, text: "Er tat, was Jahwe verabscheute, und übernahm die schrecklichen Bräuche der Völker, die Jahwe vor den Israeliten vertrieben hatte." },
      { number: 3, text: "Er baute die Höhenheiligtümer wieder auf, die sein Vater Hiskija zerstört hatte, er ließ Altäre für Baal und Pfähle für die Aschera aufstellen. Er warf sich vor dem Heer der Sterne am Himmel nieder, brachte ihm Opfer" },
      { number: 4, text: "und stellte ihm Altäre im Haus Jahwes auf, das dieser doch zur Wohnstätte seines Namens bestimmt hatte." },
      { number: 5, text: "In beiden Vorhöfen des Tempels errichtete er Altäre zur Verehrung der Sterne." },
      { number: 6, text: "Seine eigenen Söhne ließ er im Ben-Hinnom-Tal als Opfer verbrennen. Er gab sich mit Zauberei, Zeichendeutung und Wahrsagerei ab, ließ sich mit Toten- und mit Orakelgeistern ein.* So tat er vieles, was Jahwe verabscheute, und forderte seinen Zorn heraus.", footnotes: ["mit Toten- und mit Orakelgeistern ein. Damit verstieß Manasse ausdrücklich gegen das Verbot dieser Dinge in 5. Mose 18,10."] },
      { number: 7, text: "Er ließ auch ein Götzenbild anfertigen und im Haus Gottes aufstellen, von dem Gott doch zu David und seinem Sohn Salomo gesagt hatte: \"In diesem Haus und in Jerusalem, das ich mir aus allen Stämmen Israels ausgesucht habe, soll mein Name für immer wohnen." },
      { number: 8, text: "Ich will Israels Fuß nicht mehr von dem Boden entfernen, den ich euren Vorfahren gegeben habe, wenn sie mir nur gehorchen und die Gebote und Vorschriften meines Gesetzes befolgen, das mein Diener Mose ihnen verordnet hat.\"" },
      { number: 9, text: "Aber Manasse verführte sie, mehr Böses zu tun als die Völker, die Jahwe vor den Israeliten beseitigt hatte." },
      { number: 10, text: "Jahwe warnte Manasse und sein Volk, doch sie achteten nicht darauf." },
      { number: 11, text: "Da ließ Jahwe die Heerführer des Königs von Assyrien gegen sie anrücken. Sie fingen Manasse mit Widerhaken, fesselten ihn mit Bronzeketten und brachten ihn nach Babylon." },
      { number: 12, text: "In dieser Notlage wandte er sich an Jahwe, den Gott seiner Väter. Er flehte ihn an und demütigte sich tief vor ihm." },
      { number: 13, text: "Als er so zu ihm betete, ließ Gott sich von ihm erbitten und erhörte sein Gebet. Er ließ ihn nach Jerusalem zurückkehren und weiter als König regieren. So erkannte Manasse, dass Jahwe Gott ist." },
      { number: 14, text: "Nach seiner Rückkehr ließ er eine sehr hohe Mauer außen an der Davidsstadt errichten. Sie lief im Tal an der Gihon-Quelle vorbei bis zum Fischtor und umschloss den Ofel. In allen befestigten Städten Judas setzte er Kommandanten ein." },
      { number: 15, text: "Er entfernte auch die fremden Götter und das Götzenbild aus dem Haus Jahwes, ebenso die Altäre, die er auf dem Tempelberg und in Jerusalem gebaut hatte, und ließ alles vor die Stadt werfen." },
      { number: 16, text: "Den Altar Jahwes stellte er dagegen wieder her und brachte Schlacht- und Freudenopfer auf ihm dar. Auch verpflichtete er die Judäer, nur noch Jahwe, dem Gott Israels, zu dienen." },
      { number: 17, text: "Das Volk allerdings opferte auch noch auf den Opferhöhen, jedoch nur Jahwe, seinem Gott." },
      { number: 18, text: "Was es sonst noch über Manasse zu berichten gibt, über sein Gebet zu seinem Gott und über die Worte der Seher, die im Namen Jahwes zu ihm gesprochen hatten, ist nachzulesen in der Chronik der Könige von Israel." },
      { number: 19, text: "Sein Gebet und dessen Erhörung, alle seine Sünden und Treulosigkeiten, die Orte, an denen er Opferhöhen gebaut, Aschera-Pfähle und Götzenbilder aufgestellt hatte, bevor er sich demütigte, all das findet sich in der Chronik der Seher." },
      { number: 20, text: "Als Manasse starb, wurde er bei seinem Palast bestattet, und sein Sohn Amon trat die Herrschaft an." },
      { number: 21, text: "Amon war bei Herrschaftsantritt 22 Jahre alt und regierte zwei Jahre lang in Jerusalem.", heading: "König Amon von Juda" },
      { number: 22, text: "Wie sein Vater Manasse tat er, was Jahwe missfiel. Amon brachte allen Götterbildern, die sein Vater Manasse gemacht hatte, Opfer und verehrte sie." },
      { number: 23, text: "Im Gegensatz zu seinem Vater Manasse demütigte Amon sich aber nicht vor Jahwe, sondern vermehrte noch die Schuld." },
      { number: 24, text: "Da verschworen sich einige seiner Hofbeamten gegen ihn und töteten ihn in seinem Palast." },
      { number: 25, text: "Doch die Bürger des Landes erschlugen alle, die sich gegen König Amon verschworen hatten, und riefen seinen Sohn Joschija zum König aus." },
    ] },
    { number: 34, verses: [
      { number: 1, text: "Joschija war bei Herrschaftsantritt acht Jahre alt und regierte 31 Jahre* lang in Jerusalem.", heading: "Joschijas Reform (34-36)\nKönig Joschija von Juda räumt mit dem Götzendienst auf", footnotes: ["31 Jahre. 640-609 v.Chr."] },
      { number: 2, text: "Er tat, was Jahwe gefiel, und folgte damit dem Vorbild seines Vorfahren David. Er ließ sich durch nichts davon abbringen." },
      { number: 3, text: "In seinem achten Regierungsjahr*, als er noch sehr jung war, fing er an, den Gott seines Vorvaters David zu suchen. Und im zwölften Jahr* fing er an, Juda und Jerusalem von den Opferhöhen, den Aschera-Pfählen, den geschnitzten und gegossenen Götzenbildern zu reinigen.", footnotes: ["achtes Regierungsjahr = 632 v.Chr.", "zwölftes Regierungsjahr = 628 v.Chr."] },
      { number: 4, text: "Vor seinen Augen riss man die Altäre des Baal nieder. Er ließ die darauf angebrachten Räuchersäulen zerschlagen, die Aschera-Pfähle zerstören, die Schnitz- und Gussbilder zermalmen und den Staub auf die Gräber derer streuen, die ihnen geopfert hatten." },
      { number: 5, text: "Die Gebeine der Götzenpriester ließ er auf ihren eigenen Altären verbrennen. So reinigte er Juda und Jerusalem vom Götzenkult." },
      { number: 6, text: "Auch in den Städten von Manasse, Efraïm und Simeon, ja, bis nach Naftali und selbst in ihren Trümmerstätten" },
      { number: 7, text: "ließ er die Altäre niederreißen. Er ließ in ganz Israel die Aschera-Pfähle umhauen, die Götzenbilder in Stücke schlagen und die Räucheraltäre zertrümmern. Dann kehrte er nach Jerusalem zurück." },
      { number: 8, text: "In seinem 18. Regierungsjahr*, noch während er das Land und den Tempel reinigte, beauftragte er den Staatsschreiber Schafan Ben-Azalja, den Stadtobersten Maaseja und Joach Ben-Joahas, den Sprecher des Königs, das Haus Jahwes, seines Gottes, auszubessern.", footnotes: ["18. Regierungsjahr = 622 v.Chr."] },
      { number: 9, text: "Sie kamen zum Hohen Priester Hilkija und übergaben ihm das Geld, das ins Gotteshaus gebracht worden war. Die Leviten hatten es von den Leuten aus Manasse, Efraïm und dem ganzen Rest Israels sowie von Juda, Benjamin und den Einwohnern Jerusalems eingesammelt." },
      { number: 10, text: "Sie händigten es den Meistern aus, denen die Ausbesserungsarbeiten am Haus Jahwes anvertraut waren." },
      { number: 11, text: "Diese zahlten davon den Lohn für die Handwerker und Bauarbeiter und kauften behauene Steine und Holz für die Dachbinder, um die Gebäudeteile, welche die Könige von Juda hatten verfallen lassen, mit neuen Balken zu versehen." },
      { number: 12, text: "Die Männer arbeiteten sehr gewissenhaft. Die Leviten Jahat und Obadja von den Nachkommen Meraris sowie Secharja und Meschullam von den Nachkommen Kehats führten die Aufsicht. Die Leviten, die sich mit Musikinstrumenten auskannten," },
      { number: 13, text: "leiteten die Lastträger an und hatten die Aufsicht über alle Arbeiter der verschiedenen Dienstleistungen. Einzelne Leviten waren Schreiber, Listenführer und Torwächter." },
      { number: 14, text: "Als sie das Geld holten, das im Haus Jahwes eingegangen war, fand der Priester Hilkija die Schriftrolle mit dem Gesetz*, das Jahwe durch Mose gegeben hatte.", footnotes: ["Gesetz. Hier ist wohl das ganze 5. Buch Mose gemeint, das sich als geschlossenes Bundesgesetz darstellt."] },
      { number: 15, text: "Da sagte Hilkija zu Schafan, dem Staatsschreiber: \"Ich habe die Schriftrolle mit dem Gesetz im Haus Jahwes gefunden!\" und gab sie ihm." },
      { number: 16, text: "Schafan brachte sie dem König und meldete: \"Deine Leute tun alles, was ihnen aufgetragen ist." },
      { number: 17, text: "Sie haben das Geld, das sich im Haus Jahwes vorfand, gezählt und es den Verantwortlichen und den Bauleuten ausgehändigt.\"" },
      { number: 18, text: "Dann sagte er dem König noch, dass der Priester Hilkija ihm eine Schriftrolle übergeben hatte, und las ihm daraus vor." },
      { number: 19, text: "Als der König hörte, was in dem Gesetz stand, riss er sein Obergewand ein" },
      { number: 20, text: "und befahl Hilkija, Ahikam Ben-Schafan und Abdon Ben-Micha, dem Staatsschreiber Schafan und dem königlichen Vertrauten Asaja:" },
      { number: 21, text: "\"Geht und fragt Jahwe um Rat wegen der Worte in dieser gefundenen Schriftrolle. Fragt ihn für mich und für alle, die in Israel und Juda übrig geblieben sind. Denn Jahwe hat seinen ganzen Zorn über uns kommen lassen, weil unsere Vorfahren nicht auf das Wort Jahwes gehört und sich nicht nach dem gerichtet haben, was in dieser Schriftrolle steht.\"" },
      { number: 22, text: "Da ging Hilkija mit den anderen, die der König bestimmt hatte, zur Prophetin Hulda und sagte ihr das alles. Die Prophetin war die Frau von Schallum Ben-Tokhat, dem Enkel Hasras, der die Aufsicht über die Kleiderkammer hatte. Sie wohnte in der Neustadt von Jerusalem." },
      { number: 23, text: "Sie sagte ihnen: \"So spricht Jahwe, der Gott Israels: Sagt dem Mann, der euch zu mir geschickt hat:" },
      { number: 24, text: "'So spricht Jahwe: Ja, ich werde Unheil über diesen Ort und seine Bewohner bringen. Alle Flüche, die in dem Buch stehen, das man dem König von Juda vorgelesen hat, werden in Erfüllung gehen!" },
      { number: 25, text: "Weil sie mich verlassen haben und anderen Göttern Räucheropfer brachten, weil sie mich mit ihren Machwerken reizten, wird sich mein glühender Zorn über diesen Ort ergießen, und er wird nicht erlöschen!'" },
      { number: 26, text: "Aber für den König von Juda, der euch zu mir geschickt hat, um Jahwe zu befragen, habe ich folgende Botschaft: 'So spricht Jahwe, der Gott Israels: Durch die Worte, die du gehört hast," },
      { number: 27, text: "wurde dein Herz weich. Du hast dich vor Gott gedemütigt, als du seine Drohungen gegen diesen Ort und seine Bewohner gehört hast. Ja, du hast dich vor mir gedemütigt, deine Gewänder eingerissen und vor mir geweint. Darum habe ich auch auf dich gehört, spricht Jahwe." },
      { number: 28, text: "Du wirst in Frieden sterben und all das Unglück, das ich über diesen Ort und seine Bewohner kommen lasse, nicht mit ansehen müssen.'\" Die Abgesandten brachten dem König die Antwort." },
      { number: 29, text: "Darauf ließ der König alle Ältesten von Juda und Jerusalem zu sich rufen.", heading: "Die Erneuerung des Bundes" },
      { number: 30, text: "Mit allen Männern von Juda, den Einwohnern von Jerusalem, den Priestern und Leviten und allem Volk, vom Vornehmsten bis zum Einfachsten, ging er zum Haus Jahwes hinauf. Er ließ ihnen das ganze Bundesbuch vorlesen, das im Haus Jahwes gefunden worden war." },
      { number: 31, text: "Dann trat der König auf sein Podest und schloss den Bund vor Jahwe, dass man ihm nachfolgen wolle, seine Gebote, Mahnungen und Ordnungen mit ganzem Herzen und ganzer Kraft befolgen und alles genau tun wolle, was in dem Buch geschrieben steht." },
      { number: 32, text: "Er ließ alle Anwesenden aus Jerusalem und dem Gebiet von Benjamin dem Bund beitreten. Die Einwohner Jerusalems hielten sich auch an den Bund Gottes, des Gottes ihrer Vorfahren." },
      { number: 33, text: "Joschija ließ nun auch in allen übrigen Gebieten Israels all die abscheulichen Götzen entfernen und hielt alle, die dort wohnten, dazu an, Jahwe, ihrem Gott, zu dienen. Und solange Joschija lebte, folgten sie Jahwe, dem Gott ihrer Väter." },
    ] },
    { number: 35, verses: [
      { number: 1, text: "Joschija feierte in Jerusalem ein Passafest zur Ehre Jahwes. Am 14. April* wurden die Lämmer geschlachtet.", heading: "Joschijas Passafest", footnotes: ["April. Wörtlich: des 1. Monats."] },
      { number: 2, text: "Er stellte die Priester an ihre Aufgaben und ermutigte sie zum Dienst im Haus Jahwes." },
      { number: 3, text: "Den Leviten, die ganz Israel unterrichteten und Jahwe geweiht waren, sagte er: \"Stellt die heilige Lade in das Haus, das Salomo Ben-David, der König von Israel, gebaut hat. Ihr müsst sie nicht mehr auf den Schultern tragen.* Dient nun Jahwe, eurem Gott, und seinem Volk Israel.", footnotes: ["Die Bundeslade war bereits bei der Einweihung des Tempels ins Höchstheilige gebracht worden (siehe 2. Chronik 5,7). Dass sie sich jetzt außerhalb des Tempels befand mag daran liegen, dass sie entfernt worden war, sei es durch abgöttische Könige, sei es wegen der Tempelreparatur."] },
      { number: 4, text: "Macht euch in den Ordnungen eurer Sippen und Dienstgruppen bereit, so wie es König David von Israel und sein Sohn Salomo vorgeschrieben haben!" },
      { number: 5, text: "Steht im Heiligtum mit je einer Gruppe von Leviten für jede Sippe eurer Brüder bereit!" },
      { number: 6, text: "Heiligt euch, schlachtet die Lämmer und bereitet sie für eure Brüder so zu, wie Jahwe es durch Mose befohlen hat!\"" },
      { number: 7, text: "Joschija spendete aus dem königlichen Besitz für das versammelte Volk 30.000 Schaf- und Ziegenböckchen zum Passaopfer und 3000 Rinder." },
      { number: 8, text: "Auch seine hohen Beamten spendeten freiwillig für das Volk, die Priester und Leviten. Die drei führenden Priester im Haus Gottes, Hilkija, Secharja und Jehiël, spendeten der Priesterschaft 2 600 Passalämmer und 300 Rinder." },
      { number: 9, text: "Ebenso machten es die Führer der Leviten, Konanja mit seinen beiden Brüdern Schemaja und Netanel, sowie Haschabja, Jëiël und Josabad. Sie spendeten 5000 Lämmer für das Passaopfer und 500 Rinder." },
      { number: 10, text: "Als man so zum Dienst gerüstet war, traten die Priester an ihren Platz, und die Leviten stellten sich in ihren Dienstgruppen auf, wie es der König befohlen hatte." },
      { number: 11, text: "Dann wurden die Passalämmer geschlachtet. Die Priester nahmen das Blut von den Leviten entgegen und sprengten es an den Altar, während diese den Tieren die Haut abzogen." },
      { number: 12, text: "Die zum Brandopfer bestimmten Stücke legten sie beiseite, um diese den Familiengruppen zu geben, damit sie Jahwe die Stücke bringen konnten, wie es in Moses Gesetzbuch vorgeschrieben ist. Ebenso machte man es mit den Rindern." },
      { number: 13, text: "Dann wurden die Passalämmer am Feuer gebraten, wie es vorgeschrieben ist. Die heiligen Gaben kochten sie jedoch in Töpfen, Kesseln und Schüsseln. So schnell sie konnten verteilten sie es an die Leute." },
      { number: 14, text: "Danach bereiteten sie es auch für sich und die Priester zu, denn die Priester aus der Nachkommenschaft Aarons waren bis in die Nacht hinein mit der Darbringung der Brandopfer und der Fettstücke beschäftigt." },
      { number: 15, text: "Die Sänger aus der Nachkommenschaft Asafs blieben für die Dauer des Festes an ihrem Platz, wie es David, Asaf, Heman und der königliche Seher Jedutun angeordnet hatten. Auch die Torwächter blieben an ihren Toren. Sie alle brauchten ihren Dienst nicht zu unterbrechen, weil ihre Brüder, die Leviten, für sie alles zubereiteten." },
      { number: 16, text: "So war der gesamte Dienst für Jahwe an diesem Tag gut geordnet. Man feierte das Passa und brachte auf dem Altar Jahwes die Brandopfer dar, wie König Joschija es angeordnet hatte." },
      { number: 17, text: "Anschließend feierten die versammelten Israeliten sieben Tage lang das Fest der ungesäuerten Brote." },
      { number: 18, text: "Ein solches Passafest hatte es in Israel seit der Zeit des Propheten Samuel nicht mehr gegeben. Keiner der früheren Könige Israels hatte es so wie Joschija zusammen mit den Priestern und Leviten, mit ganz Juda und den anwesenden Israeliten und den Einwohnern Jerusalems gefeiert." },
      { number: 19, text: "Im 18. Regierungsjahr Joschijas war dieses Passa gefeiert worden.*", footnotes: ["18. Regspanerungsjahr. Es war dasselbe Jahr, in dem man die Schriftrolle mit dem Gesetz gefunden hatte, 622 v.Chr."] },
      { number: 20, text: "Nachdem Joschija das alles zur Instandsetzung des Tempels getan hatte, zog König Necho von Ägypten heran. Er war auf dem Weg zur Schlacht von Karkemisch am Euphrat.* Joschija stellte sich ihm entgegen.", heading: "Joschijas Tod", footnotes: ["Schlacht ... Euphrat. Weil die wachsende babylonische Macht unter Nabopolassar auch Ägypten gefährlich werden konnte, wollte Pharao Necho dem (letzten) assyrischen König Assur-Ubalit II helfen. Das muss im Jahr 609 v.Chr. gewesen sein."] },
      { number: 21, text: "Da schickte Necho Boten zu ihm und ließ ihm sagen: \"Was haben wir denn miteinander zu schaffen, König von Juda? Ich ziehe nicht gegen dich, ich bin im Krieg mit einem anderen Königshaus. Gott hat gesagt, dass ich mich beeilen soll. Stell dich also nicht gegen Gott, denn er ist auf meiner Seite, sonst wird er dich vernichten!\"" },
      { number: 22, text: "Doch Joschija zog sich nicht zurück, sondern verkleidete sich und wollte gegen ihn kämpfen. Er hörte nicht auf die Worte Nechos, durch die Gott ihn warnen wollte. In der Ebene von Megiddo stellte er sich ihm entgegen." },
      { number: 23, text: "Doch in der Schlacht wurde Joschija von feindlichen Bogenschützen getroffen. \"Bringt mich weg\", sagte er zu seinen Begleitern, \"ich bin schwer verwundet!\"" },
      { number: 24, text: "Seine Diener hoben ihn vom Streitwagen, setzten ihn auf seinen zweiten Wagen und brachten ihn nach Jerusalem. Dort starb er und wurde in der Grabstätte seiner Vorfahren bestattet. Ganz Juda und Jerusalem trauerten um Joschija." },
      { number: 25, text: "Der Prophet Jeremia dichtete ein Klagelied für Joschija, und alle Sänger und Sängerinnen besingen ihn bis heute in ihren Klageliedern. Das wurde zu einem festen Brauch in Israel. Diese Lieder stehen ja im Buch der Klagelieder." },
      { number: 26, text: "Was es sonst noch über Joschija und die Beweise seiner Treue gegenüber dem Gesetz Jahwes zu berichten gibt," },
      { number: 27, text: "seine frühere und spätere Geschichte, findet man im Buch der Könige von Israel und Juda." },
    ] },
    { number: 36, verses: [
      { number: 1, text: "Als Nachfolger für Joschija machte das Volk des Landes dessen Sohn Joahas zum König in Jerusalem.", heading: "Joahas, Jojakim und Jojachin" },
      { number: 2, text: "Joahas war bei seinem Herrschaftsantritt 23 Jahre alt und regierte drei Monate* in Jerusalem.", footnotes: ["drei Monate. Im Jahr 609 v.Chr."] },
      { number: 3, text: "Der König von Ägypten setzte ihn ab. Das Land musste einen Tribut von dreieinhalb Tonnen Silber und 34 Kilogramm Gold* an ihn zahlen.", footnotes: ["dreieinhalb ... Gold. Wörtlich: 100 Talente Silber und 1 Talent Gold."] },
      { number: 4, text: "Dann setzte der König von Ägypten Eljakim, den Bruder von Joahas, zum König über Juda und Jerusalem ein und änderte seinen Namen in Jojakim. Joahas nahm er gefangen nach Ägypten mit." },
      { number: 5, text: "Jojakim war bei seinem Herrschaftsantritt 25 Jahre alt und regierte elf Jahre* in Jerusalem. Er tat, was Jahwe, seinem Gott, missfiel.", footnotes: ["elf Jahre. 608-598 v.Chr."] },
      { number: 6, text: "Gegen ihn zog König Nebukadnezzar von Babylon heran. Er ließ ihn in Ketten legen und brachte ihn nach Babylon." },
      { number: 7, text: "Auch von den Gegenständen aus dem Haus Jahwes nahm Nebukadnezzar einen Teil mit und stellte sie in seinem Palast auf." },
      { number: 8, text: "Was sonst noch über Jojakims Herrschaft zu sagen ist, über seine abscheulichen Taten und das, was mit ihm geschah, findet man in der Chronik der Könige von Israel und Juda. Sein Sohn Jojachin trat die Herrschaft an." },
      { number: 9, text: "Jojachin war bei seinem Herrschaftsantritt* 18 Jahre alt* und regierte drei Monate und zehn Tage in Jerusalem. Auch er tat, was Jahwe missfiel.", footnotes: ["Herrschaftsantritt. Weil babylonische Schriften den Fall Jerusalems auf den 16. März 597 v.Chr. datieren, muss Jojachin im Dezember 598 v.Chr. König geworden sein.", "18 Jahre. Die Septuaginta und einige hebräische Handschriften lesen hier achtzehn, statt acht wie der masoretische Text."] },
      { number: 10, text: "Um die Jahreswende ließ König Nebukadnezzar ihn und die kostbaren Gegenstände aus dem Haus Jahwes nach Babylon holen. Zum König über Juda und Jerusalem setzte er Zidkija, einen Verwandten Jojakims, ein." },
      { number: 11, text: "Als Zidkija die Herrschaft antrat, war er 21 Jahre alt. Er regierte elf Jahre in Jerusalem", heading: "König Zidkija von Juda" },
      { number: 12, text: "und tat, was Jahwe, seinem Gott, missfiel. Er beugte sich nicht vor dem Propheten Jeremia, der im Auftrag Jahwes zu ihm sprach." },
      { number: 13, text: "Auch gegen König Nebukadnezzar, der ihn vor Gott einen Treueid hatte schwören lassen, lehnte er sich auf. Hartnäckig und stur weigerte er sich, zu Jahwe, dem Gott Israels, umzukehren." },
      { number: 14, text: "Auch die führenden Priester und das Volk trieben es mit ihrer Untreue immer schlimmer. Sie folgten den abscheulichen Bräuchen der anderen Völker und entweihten das Haus Jahwes, das er in Jerusalem zu seinem Heiligtum gemacht hatte." },
      { number: 15, text: "Immer wieder hatte Jahwe, der Gott ihrer Väter, seine Boten zu ihnen geschickt, denn sein Volk und seine Wohnung taten ihm leid." },
      { number: 16, text: "Aber sie verhöhnten die Boten Gottes, verachteten seine Worte und verspotteten seine Propheten, bis der Zorn Jahwes über sein Volk so groß wurde, dass es keine Rettung mehr gab." },
      { number: 17, text: "Jahwe ließ den König der Chaldäer* gegen sie heranrücken und auch im Haus des Heiligtums ihre jungen Männer mit dem Schwert umbringen. Er verschonte keinen jungen Mann und keine junge Frau, keinen Alten und keinen Greis. Alle gab er in seine Gewalt.", heading: "Das Ende des Königreiches Juda", footnotes: ["Die Chaldäer waren aramäisch (syrisch) sprechende Semiten aus dem südlichen Zweistromland Babylonien. Ihr König war damals Nebukadnezzar, der Nebusaradan schickte, siehe 2. Könige 25,8."] },
      { number: 18, text: "Sämtliche großen und kleinen Gegenstände des Gotteshauses ließ er nach Babylon bringen, dazu die Schätze aus dem Haus Jahwes und die Schätze des Königs und der anderen führenden Männer." },
      { number: 19, text: "Dann ließ er das Haus Gottes in Brand stecken und die Stadtmauer Jerusalems niederreißen. Auch alle Paläste in der Stadt ließ er niederbrennen und auf diese Weise alles Wertvolle vernichten." },
      { number: 20, text: "Alle, die dem Schwert entgangen waren, verschleppte er nach Babylonien. Dort mussten sie dem König und seinen Nachkommen als Sklaven dienen, bis die Perser die Herrschaft übernahmen." },
      { number: 21, text: "So bekam das Land seine Sabbatruhe ersetzt, solange die Verwüstung dauerte, bis die siebzig Jahre voll waren. Und so erfüllte sich das Wort, das Jahwe durch Jeremia hatte sagen lassen." },
      { number: 22, text: "Im ersten Regierungsjahr* des Perserkönigs Kyrus sollte sich erfüllen, was Jahwe durch den Propheten Jeremia* angekündigt hatte. Jahwe bewegte den König dazu, in seinem ganzen Reich folgende Verfügung mündlich und schriftlich bekannt zu machen:", heading: "Das Ende der Gefangenschaft", footnotes: ["erstes Regierungsjahr. Das war im Jahr 538 v.Chr., nachdem er im Oktober 539 v.Chr. Babylon erobert hatte.", "Jeremia 29,10-11"] },
      { number: 23, text: "\"Kyrus, der König von Persien, gibt bekannt: Jahwe, der Gott des Himmels, hat alle Königreiche der Erde in meine Gewalt gegeben. Nun hat er mich beauftragt, ihm in Jerusalem in Judäa ein Haus zu bauen. Wer von euch zu seinem Volk gehört, der möge zurückkehren! Jahwe, sein Gott, sei mit ihm!\"" },
    ] },
  ],
};